    NotEquals,
    Lower,
    LowerEquals,
    Greater,
    GreaterEquals,
    Not,
    And,
    Or,
    Dot,
}

impl Operator {
    pub fn text(&self) -> &'static str {
        match self {
            Operator::Plus => "+",
            Operator::Minus => "-",
            Operator::Times => "*",
            Operator::Div => "/",
            Operator::Mod => "%",
            Operator::Concat => "++",
            Operator::Equals => "==",
            Operator::NotEquals => "!=",
            Operator::Lower => "<",
            Operator::LowerEquals => "<=",
            Operator::Greater => ">",
            Operator::GreaterEquals => ">=",
            Operator::Not => "not",
            Operator::And => "and",
            Operator::Or => "or",
            Operator::Dot => ".",
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Literal {
    Nil,
    True,
    False,
    Int(i64),
    Float(f64),
    Byte(u8),
    String(Vec<u8>),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Expansion {
    Home,
    Star,
    Percent,
}

#[derive(Clone, Debug, PartialEq)]
pub enum ArgUnit {
    Literal(Vec<u8>),
    Dollar(Vec<u8>, Pos),
}

#[derive(Clone, Debug, PartialEq)]
pub enum ArgPart {
    Unquoted(ArgUnit),
    SingleQuoted(Vec<u8>),
    DoubleQuoted(Vec<ArgUnit>),
    Expansion(Expansion),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CmdOp {
    Output { append: bool },
    Input { literal: bool },
}

#[derive(Clone, Debug, PartialEq)]
pub enum TokenKind {
    Identifier(Vec<u8>),
    Keyword(Keyword),
    Operator(Operator),
    Literal(Literal),
    OpenParens,
    CloseParens,
    OpenBracket,
    CloseBracket,
    OpenDict,
    Comma,
    Colon,
    Assign,
    Try,
    Command,
    CaptureCommand,
    AsyncCommand,
    CloseCommand,
    Semicolon,
    Pipe,
    Argument(Vec<ArgPart>),
    CmdOperator(CmdOp),
}

#[derive(Clone, Debug, PartialEq)]
pub struct Token {
    pub kind: TokenKind,
    pub pos: Pos,
}

pub fn lossy(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).into_owned()
}

pub fn escape_str(bytes: &[u8]) -> String {
    lossy(bytes).escape_debug().to_string()
}

pub fn escape_char(b: u8) -> String {
    (b as char).escape_debug().to_string()
}

impl fmt::Display for ArgUnit {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ArgUnit::Literal(lit) => write!(f, "{}", escape_str(lit)),
            ArgUnit::Dollar(name, _) => write!(f, "${{{{{}}}}}", lossy(name)),
        }
    }
}

impl fmt::Display for Expansion {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Expansion::Home => write!(f, "~/"),
            Expansion::Star => write!(f, "*"),
            Expansion::Percent => write!(f, "%"),
        }
    }
}

impl fmt::Display for ArgPart {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ArgPart::Unquoted(unit) => write!(f, "{}", unit),
            ArgPart::SingleQuoted(lit) => write!(f, "'{}'", escape_str(lit)),
            ArgPart::DoubleQuoted(units) => {
                write!(f, "\"")?;
                for unit in units {
                    write!(f, "{}", unit)?;
                }
                write!(f, "\"")
            }
            ArgPart::Expansion(exp) => write!(f, "{}", exp),
        }
    }
}

pub fn fmt_float_display(x: f64) -> String {
    format!("{}", x)
}

impl fmt::Display for Literal {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Literal::Nil => write!(f, "nil"),
            Literal::True => write!(f, "true"),
            Literal::False => write!(f, "false"),
            Literal::Int(i) => write!(f, "{}", i),
            Literal::Float(x) => write!(f, "{}", fmt_float_display(*x)),
            Literal::Byte(b) => write!(f, "'{}'", escape_char(*b)),
            Literal::String(s) => write!(f, "\"{}\"", escape_str(s)),
        }
    }
}

impl fmt::Display for TokenKind {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            TokenKind::Identifier(name) => write!(f, "{}", lossy(name)),
            TokenKind::Keyword(kw) => write!(f, "{}", kw.text()),
            TokenKind::Operator(op) => write!(f, "{}", op.text()),
            TokenKind::Literal(lit) => write!(f, "{}", lit),
            TokenKind::OpenParens => write!(f, "("),
            TokenKind::CloseParens => write!(f, ")"),
            TokenKind::OpenBracket => write!(f, "["),
            TokenKind::CloseBracket => write!(f, "]"),
            TokenKind::OpenDict => write!(f, "@["),
            TokenKind::Comma => write!(f, ","),
            TokenKind::Colon => write!(f, ":"),
            TokenKind::Assign => write!(f, "="),
            TokenKind::Try => write!(f, "?"),
            TokenKind::Command => write!(f, "{{"),
            TokenKind::CaptureCommand => write!(f, "${{"),
            TokenKind::AsyncCommand => write!(f, "&{{"),
            TokenKind::CloseCommand => write!(f, "}}"),
            TokenKind::Semicolon => write!(f, ";"),
            TokenKind::Pipe => write!(f, "|"),
            TokenKind::Argument(parts) => {
                for part in parts {
                    write!(f, "{}", part)?;
                }
                Ok(())
            }
            TokenKind::CmdOperator(op) => match op {
                CmdOp::Output { append: false } => write!(f, ">"),
                CmdOp::Output { append: true } => write!(f, ">>"),
                CmdOp::Input { literal: false } => write!(f, "<"),
                CmdOp::Input { literal: true } => write!(f, "<<"),
            },
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum LexErrorKind {
    UnexpectedEof,
    Unexpected(u8),
    EmptyByteLiteral,
    InvalidEscapeSequence(Vec<u8>),
    InvalidNumber(Vec<u8>),
    InvalidIdentifier(Vec<u8>),
}

#[derive(Clone, Debug, PartialEq)]
pub struct LexError {
    pub kind: LexErrorKind,
    pub pos: Pos,
}

impl fmt::Display for LexErrorKind {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            LexErrorKind::UnexpectedEof => write!(f, "unexpected end of file."),
            LexErrorKind::Unexpected(c) => write!(f, "unexpected '{}'.", escape_char(*c)),
            LexErrorKind::EmptyByteLiteral => write!(f, "empty char literal."),
            LexErrorKind::InvalidEscapeSequence(seq) => {
                write!(f, "invalid escape sequence '{}'.", lossy(seq))
            }
            LexErrorKind::InvalidNumber(n) => write!(f, "invalid number '{}'.", lossy(n)),
            LexErrorKind::InvalidIdentifier(n) => write!(f, "invalid identifier '{}'.", lossy(n)),
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum LexItem {
    Token(Token),
    Error(LexError),
}

/// A lexer panic (unimplemented feature in the original implementation).
#[derive(Debug)]
pub struct LexPanic {
    pub location: &'static str,
}

pub fn is_keyword_word(word: &[u8]) -> bool {
    matches!(
        word,
        b"let"
            | b"if"
            | b"then"
            | b"else"
            | b"elseif"
            | b"end"
            | b"for"
            | b"in"
            | b"do"
            | b"while"
            | b"function"
            | b"return"
            | b"break"
            | b"self"
            | b"true"
            | b"false"
            | b"nil"
            | b"not"
            | b"and"
            | b"or"
    )
}

pub fn is_valid_identifier(word: &[u8]) -> bool {
    if word.is_empty() {
        return false;
    }
    let first = word[0];
    if !(first.is_ascii_alphabetic() || first == b'_') {
        return false;
    }
    if !word.iter().all(|c| c.is_ascii_alphanumeric() || *c == b'_') {
        return false;
    }
    !is_keyword_word(word)
}

fn is_ws(c: u8) -> bool {
    matches!(c, b' ' | b'\t' | b'\n' | b'\x0c' | b'\r')
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Ctx {
    Unquoted,
    Single,
    Double,
}

struct Lexer<'a> {
    src: &'a [u8],
    i: usize,
    line: u32,
    col: u32,
    items: Vec<LexItem>,
    cmd_mode: bool,
    stopped: bool,
}

/// Outcome of lexing a command word.
enum WordEnd {
    Done,
    Eof,
}

impl<'a> Lexer<'a> {
    fn pos(&self) -> Pos {
        Pos { line: self.line, column: self.col }
    }

    fn peek(&self) -> Option<u8> {
        self.src.get(self.i).copied()
    }

    fn peek_at(&self, n: usize) -> Option<u8> {
        self.src.get(self.i + n).copied()
    }

    fn bump(&mut self) {
        if let Some(c) = self.peek() {
            self.i += 1;
            if c == b'\n' {
                self.line += 1;
                self.col = 0;
            } else {
                self.col += 1;
            }
        }
    }

    fn token(&mut self, kind: TokenKind, pos: Pos) {
        self.items.push(LexItem::Token(Token { kind, pos }));
    }

    fn error(&mut self, kind: LexErrorKind, pos: Pos) {
        self.items.push(LexItem::Error(LexError { kind, pos }));
    }

    fn run(&mut self) -> Result<(), LexPanic> {
        loop {
            if self.stopped {
                return Ok(());
            }
            let c = match self.peek() {
                Some(c) => c,
                None => {
                    if self.cmd_mode {
                        let pos = self.pos();
                        self.error(LexErrorKind::UnexpectedEof, pos);
                    }
                    return Ok(());
                }
            };
            if self.cmd_mode {
                self.cmd_root(c)?;
            } else {
                self.root(c);
            }
        }
    }

    fn skip_comment(&mut self) {
        while let Some(c) = self.peek() {
            if c == b'\n' {
                break;
            }
            self.bump();
        }
    }

    fn root(&mut self, c: u8) {
        let pos = self.pos();
        match c {
            c if is_ws(c) => self.bump(),
            b'#' => self.skip_comment(),
            b'a'..=b'z' | b'A'..=b'Z' | b'_' => self.word(),
            b'0'..=b'9' => self.number(),
            b'"' => self.string(),
            b'\'' => self.byte(),
            b'{' => {
                self.bump();
                self.token(TokenKind::Command, pos);
                self.cmd_mode = true;
            }
            b'$' | b'&' => {
                if self.peek_at(1) == Some(b'{') {
                    self.bump();
                    self.bump();
                    let kind = if c == b'$' { TokenKind::CaptureCommand } else { TokenKind::AsyncCommand };
                    self.token(kind, pos);
                    self.cmd_mode = true;
                } else {
                    self.bump();
                    self.error(LexErrorKind::Unexpected(c), pos);
                }
            }
            b'@' => {
                if self.peek_at(1) == Some(b'[') {
                    self.bump();
                    self.bump();
                    self.token(TokenKind::OpenDict, pos);
                } else {
                    self.bump();
                    self.error(LexErrorKind::Unexpected(c), pos);
                }
            }
            b'+' => {
                if self.peek_at(1) == Some(b'+') {
                    self.bump();
                    self.bump();
                    self.token(TokenKind::Operator(Operator::Concat), pos);
                } else {
                    self.bump();
                    self.token(TokenKind::Operator(Operator::Plus), pos);
                }
            }
            b'-' => self.single(TokenKind::Operator(Operator::Minus)),
            b'*' => self.single(TokenKind::Operator(Operator::Times)),
            b'/' => self.single(TokenKind::Operator(Operator::Div)),
            b'%' => self.single(TokenKind::Operator(Operator::Mod)),
            b'=' => self.double(b'=', TokenKind::Operator(Operator::Equals), TokenKind::Assign),
            b'<' => self.double(b'=', TokenKind::Operator(Operator::LowerEquals), TokenKind::Operator(Operator::Lower)),
            b'>' => self.double(b'=', TokenKind::Operator(Operator::GreaterEquals), TokenKind::Operator(Operator::Greater)),
            b'!' => {
                if self.peek_at(1) == Some(b'=') {
                    self.bump();
                    self.bump();
                    self.token(TokenKind::Operator(Operator::NotEquals), pos);
                } else {
                    self.bump();
                    self.error(LexErrorKind::Unexpected(c), pos);
                }
            }
            b'.' => self.single(TokenKind::Operator(Operator::Dot)),
            b',' => self.single(TokenKind::Comma),
            b':' => self.single(TokenKind::Colon),
            b'(' => self.single(TokenKind::OpenParens),
            b')' => self.single(TokenKind::CloseParens),
            b'[' => self.single(TokenKind::OpenBracket),
            b']' => self.single(TokenKind::CloseBracket),
            b'?' => self.single(TokenKind::Try),
            _ => {
                self.bump();
                self.error(LexErrorKind::Unexpected(c), pos);
            }
        }
    }

    fn single(&mut self, kind: TokenKind) {
        let pos = self.pos();
        self.bump();
        self.token(kind, pos);
    }

    fn double(&mut self, second: u8, if_double: TokenKind, if_single: TokenKind) {
        let pos = self.pos();
        if self.peek_at(1) == Some(second) {
            self.bump();
            self.bump();
            self.token(if_double, pos);
        } else {
            self.bump();
            self.token(if_single, pos);
        }
    }

    fn word(&mut self) {
        let pos = self.pos();
        let start = self.i;
        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == b'_' {
                self.bump();
            } else {
                break;
            }
        }
        let word = &self.src[start..self.i];
        let kind = match word {
            b"let" => TokenKind::Keyword(Keyword::Let),
            b"if" => TokenKind::Keyword(Keyword::If),
            b"then" => TokenKind::Keyword(Keyword::Then),
            b"else" => TokenKind::Keyword(Keyword::Else),
            b"elseif" => TokenKind::Keyword(Keyword::ElseIf),
            b"end" => TokenKind::Keyword(Keyword::End),
            b"for" => TokenKind::Keyword(Keyword::For),
            b"in" => TokenKind::Keyword(Keyword::In),
            b"do" => TokenKind::Keyword(Keyword::Do),
            b"while" => TokenKind::Keyword(Keyword::While),
            b"function" => TokenKind::Keyword(Keyword::Function),
            b"return" => TokenKind::Keyword(Keyword::Return),
            b"break" => TokenKind::Keyword(Keyword::Break),
            b"self" => TokenKind::Keyword(Keyword::Self_),
            b"true" => TokenKind::Literal(Literal::True),
            b"false" => TokenKind::Literal(Literal::False),
            b"nil" => TokenKind::Literal(Literal::Nil),
            b"not" => TokenKind::Operator(Operator::Not),
            b"and" => TokenKind::Operator(Operator::And),
            b"or" => TokenKind::Operator(Operator::Or),
            _ => TokenKind::Identifier(word.to_vec()),
        };
        self.token(kind, pos);
    }

    fn number(&mut self) {
        let pos = self.pos();
        let mut buf = Vec::new();
        // states: 0 int, 1 after dot, 2 frac, 3 after e, 4 exp digits
        let mut state = 0;
        loop {
            let c = self.peek();
            match state {
                0 => match c {
                    Some(d @ b'0'..=b'9') => {
                        buf.push(d);
                        self.bump();
                    }
                    Some(b'.') => {
                        buf.push(b'.');
                        self.bump();
                        state = 1;
                    }
                    Some(e @ (b'e' | b'E')) => {
                        buf.push(e);
                        self.bump();
                        state = 3;
                    }
                    _ => {
                        let text = String::from_utf8_lossy(&buf).into_owned();
                        match text.parse::<i64>() {
                            Ok(n) => self.token(TokenKind::Literal(Literal::Int(n)), pos),
                            Err(_) => {
                                self.bump();
                                self.error(LexErrorKind::InvalidNumber(buf), pos);
                            }
                        }
                        return;
                    }
                },
                1 | 3 => match c {
                    Some(d @ b'0'..=b'9') => {
                        buf.push(d);
                        self.bump();
                        state = if state == 1 { 2 } else { 4 };
                    }
                    Some(other) => {
                        self.bump();
                        self.error(LexErrorKind::Unexpected(other), pos);
                        return;
                    }
                    None => {
                        self.error(LexErrorKind::UnexpectedEof, pos);
                        return;
                    }
                },
                2 => match c {
                    Some(d @ b'0'..=b'9') => {
                        buf.push(d);
                        self.bump();
                    }
                    Some(e @ (b'e' | b'E')) => {
                        buf.push(e);
                        self.bump();
                        state = 3;
                    }
                    _ => {
                        self.finish_float(buf, pos);
                        return;
                    }
                },
                _ => match c {
                    Some(d @ b'0'..=b'9') => {
                        buf.push(d);
                        self.bump();
                    }
                    _ => {
                        self.finish_float(buf, pos);
                        return;
                    }
                },
            }
        }
    }

    fn finish_float(&mut self, buf: Vec<u8>, pos: Pos) {
        let text = String::from_utf8_lossy(&buf).into_owned();
        match text.parse::<f64>() {
            Ok(x) => self.token(TokenKind::Literal(Literal::Float(x)), pos),
            Err(_) => {
                self.bump();
                self.error(LexErrorKind::InvalidNumber(buf), pos);
            }
        }
    }

    fn string(&mut self) {
        let pos = self.pos();
        self.bump();
        let mut buf = Vec::new();
        loop {
            match self.peek() {
                None => {
                    let p = self.pos();
                    self.error(LexErrorKind::UnexpectedEof, p);
                    return;
                }
                Some(b'"') => {
                    self.bump();
                    self.token(TokenKind::Literal(Literal::String(buf)), pos);
                    return;
                }
                Some(b'\\') => {
                    let esc_pos = self.pos();
                    self.bump();
                    match self.peek() {
                        None => {
                            let p = self.pos();
                            self.error(LexErrorKind::UnexpectedEof, p);
                            return;
                        }
                        Some(c) => {
                            self.bump();
                            match c {
                                b'n' => buf.push(b'\n'),
                                b't' => buf.push(b'\t'),
                                b'0' => buf.push(0),
                                b'\\' => buf.push(b'\\'),
                                b'"' => buf.push(b'"'),
                                b'\'' => buf.push(b'\''),
                                other => self.error(
                                    LexErrorKind::InvalidEscapeSequence(vec![b'\\', other]),
                                    esc_pos,
                                ),
                            }
                        }
                    }
                }
                Some(c) => {
                    buf.push(c);
                    self.bump();
                }
            }
        }
    }

    fn byte(&mut self) {
        let pos = self.pos();
        self.bump();
        let value;
        match self.peek() {
            None => {
                let p = self.pos();
                self.error(LexErrorKind::UnexpectedEof, p);
                return;
            }
            Some(b'\'') => {
                self.bump();
                self.error(LexErrorKind::EmptyByteLiteral, pos);
                return;
            }
            Some(b'\\') => {
                let esc_pos = self.pos();
                self.bump();
                match self.peek() {
                    None => {
                        let p = self.pos();
                        self.error(LexErrorKind::UnexpectedEof, p);
                        return;
                    }
                    Some(c) => {
                        self.bump();
                        value = match c {
                            b'n' => b'\n',
                            b't' => b'\t',
                            b'0' => 0,
                            b'\\' => b'\\',
                            b'\'' => b'\'',
                            b'"' => b'"',
                            other => {
                                self.error(
                                    LexErrorKind::InvalidEscapeSequence(vec![b'\\', other]),
                                    esc_pos,
                                );
                                0
                            }
                        };
                    }
                }
            }
            Some(c) => {
                self.bump();
                value = c;
            }
        }
        loop {
            match self.peek() {
                None => {
                    let p = self.pos();
                    self.error(LexErrorKind::UnexpectedEof, p);
                    return;
                }
                Some(b'\'') => {
                    self.bump();
                    self.token(TokenKind::Literal(Literal::Byte(value)), pos);
                    return;
                }
                Some(c) => {
                    let p = self.pos();
                    self.bump();
                    self.error(LexErrorKind::Unexpected(c), p);
                }
            }
        }
    }

    fn cmd_root(&mut self, c: u8) -> Result<(), LexPanic> {
        let pos = self.pos();
        match c {
            c if is_ws(c) => self.bump(),
            b'#' => self.skip_comment(),
            b'}' => {
                self.bump();
                self.token(TokenKind::CloseCommand, pos);
                self.cmd_mode = false;
            }
            b';' => self.single(TokenKind::Semicolon),
            b'|' => self.single(TokenKind::Pipe),
            b'?' => self.single(TokenKind::Try),
            b'>' => {
                if self.peek_at(1) == Some(b'>') {
                    self.bump();
                    self.bump();
                    self.token(TokenKind::CmdOperator(CmdOp::Output { append: true }), pos);
                } else {
                    self.bump();
                    self.token(TokenKind::CmdOperator(CmdOp::Output { append: false }), pos);
                }
            }
            b'<' => {
                if self.peek_at(1) == Some(b'<') {
                    self.bump();
                    self.bump();
                    self.token(TokenKind::CmdOperator(CmdOp::Input { literal: true }), pos);
                } else {
                    self.bump();
                    self.token(TokenKind::CmdOperator(CmdOp::Input { literal: false }), pos);
                }
            }
            _ => match self.arg_word()? {
                WordEnd::Done => {}
                WordEnd::Eof => self.stopped = true,
            },
        }
        Ok(())
    }

    fn arg_word(&mut self) -> Result<WordEnd, LexPanic> {
        let pos = self.pos();
        let mut parts: Vec<ArgPart> = Vec::new();
        let mut lit: Vec<u8> = Vec::new();
        let mut ctx = Ctx::Unquoted;
        let mut single: Vec<u8> = Vec::new();
        let mut dunits: Vec<ArgUnit> = Vec::new();
        let mut dlit: Vec<u8> = Vec::new();

        fn flush(lit: &mut Vec<u8>, parts: &mut Vec<ArgPart>) {
            if !lit.is_empty() {
                parts.push(ArgPart::Unquoted(ArgUnit::Literal(std::mem::take(lit))));
            }
        }
        fn dflush(dlit: &mut Vec<u8>, dunits: &mut Vec<ArgUnit>) {
            if !dlit.is_empty() {
                dunits.push(ArgUnit::Literal(std::mem::take(dlit)));
            }
        }

        loop {
            let c = match self.peek() {
                None => return Ok(WordEnd::Eof),
                Some(c) => c,
            };
            match ctx {
                Ctx::Unquoted => match c {
                    c if is_ws(c) || matches!(c, b';' | b'|' | b'?' | b'>' | b'<' | b'}' | b'#') => {
                        flush(&mut lit, &mut parts);
                        self.token(TokenKind::Argument(parts), pos);
                        return Ok(WordEnd::Done);
                    }
                    b'\'' => {
                        flush(&mut lit, &mut parts);
                        self.bump();
                        ctx = Ctx::Single;
                    }
                    b'"' => {
                        flush(&mut lit, &mut parts);
                        self.bump();
                        ctx = Ctx::Double;
                    }
                    b'\\' => {
                        if !self.escape(Ctx::Unquoted, &mut lit) {
                            return Ok(WordEnd::Eof);
                        }
                    }
                    b'$' => {
                        flush(&mut lit, &mut parts);
                        match self.dollar()? {
                            None => return Ok(WordEnd::Eof),
                            Some(Some(unit)) => parts.push(ArgPart::Unquoted(unit)),
                            Some(None) => {}
                        }
                    }
                    b'*' => {
                        flush(&mut lit, &mut parts);
                        self.bump();
                        parts.push(ArgPart::Expansion(Expansion::Star));
                    }
                    b'%' => {
                        flush(&mut lit, &mut parts);
                        self.bump();
                        parts.push(ArgPart::Expansion(Expansion::Percent));
                    }
                    b'~' if parts.is_empty() && lit.is_empty() && self.peek_at(1) == Some(b'/') => {
                        self.bump();
                        self.bump();
                        parts.push(ArgPart::Expansion(Expansion::Home));
                    }
                    b'[' => {
                        return Err(LexPanic { location: "src/syntax/lexer/automata/expansion.rs:87:17" });
                    }
                    b'{' => {
                        return Err(LexPanic { location: "src/syntax/lexer/automata/expansion.rs:91:17" });
                    }
                    other => {
                        lit.push(other);
                        self.bump();
                    }
                },
                Ctx::Single => match c {
                    b'\'' => {
                        self.bump();
                        parts.push(ArgPart::SingleQuoted(std::mem::take(&mut single)));
                        ctx = Ctx::Unquoted;
                    }
                    b'\\' => {
                        if !self.escape(Ctx::Single, &mut single) {
                            return Ok(WordEnd::Eof);
                        }
                    }
                    other => {
                        single.push(other);
                        self.bump();
                    }
                },
                Ctx::Double => match c {
                    b'"' => {
                        self.bump();
                        dflush(&mut dlit, &mut dunits);
                        parts.push(ArgPart::DoubleQuoted(std::mem::take(&mut dunits)));
                        ctx = Ctx::Unquoted;
                    }
                    b'\\' => {
                        if !self.escape(Ctx::Double, &mut dlit) {
                            return Ok(WordEnd::Eof);
                        }
                    }
                    b'$' => {
                        dflush(&mut dlit, &mut dunits);
                        match self.dollar()? {
                            None => return Ok(WordEnd::Eof),
                            Some(Some(unit)) => dunits.push(unit),
                            Some(None) => {}
                        }
                    }
                    other => {
                        dlit.push(other);
                        self.bump();
                    }
                },
            }
        }
    }

    /// Lex an escape sequence. Returns false on EOF.
    fn escape(&mut self, ctx: Ctx, out: &mut Vec<u8>) -> bool {
        let esc_pos = self.pos();
        self.bump();
        let mut seq = vec![b'\\'];
        loop {
            let c = match self.peek() {
                None => return false,
                Some(c) => c,
            };
            let valid = match ctx {
                Ctx::Unquoted => matches!(
                    c,
                    b' ' | b'"' | b'#' | b'$' | b'\'' | b'0' | b';' | b'<' | b'=' | b'>' | b'?' | b'\\'
                        | b'n' | b't' | b'\t' | b'\n' | b'\r' | b'\x0c'
                ),
                Ctx::Single => matches!(c, b'\'' | b'0' | b'\\' | b'n' | b't'),
                Ctx::Double => matches!(c, b'"' | b'$' | b'0' | b'\\' | b'n' | b't'),
            };
            self.bump();
            if valid {
                out.push(match c {
                    b'n' => b'\n',
                    b't' => b'\t',
                    b'0' => 0,
                    other => other,
                });
                return true;
            } else {
                seq.push(c);
                self.error(LexErrorKind::InvalidEscapeSequence(seq.clone()), esc_pos);
            }
        }
    }

    /// Lex a dollar. Returns None on EOF, Some(None) on error, Some(Some(unit)) on success.
    fn dollar(&mut self) -> Result<Option<Option<ArgUnit>>, LexPanic> {
        let dpos = self.pos();
        self.bump();
        let first = match self.peek() {
            None => return Ok(None),
            Some(c) => c,
        };
        if first == b'{' {
            self.bump();
            let mut name = Vec::new();
            loop {
                match self.peek() {
                    None => return Ok(None),
                    Some(b'}') => {
                        self.bump();
                        break;
                    }
                    Some(c) => {
                        name.push(c);
                        self.bump();
                    }
                }
            }
            if is_valid_identifier(&name) {
                return Ok(Some(Some(ArgUnit::Dollar(name, dpos))));
            } else {
                self.error(LexErrorKind::InvalidIdentifier(name), dpos);
                return Ok(Some(None));
            }
        }
        let mut name = vec![first];
        self.bump();
        loop {
            match self.peek() {
                None => return Ok(None),
                Some(c) if c.is_ascii_alphanumeric() || c == b'_' => {
                    name.push(c);
                    self.bump();
                }
                Some(_) => break,
            }
        }
        if is_valid_identifier(&name) {
            Ok(Some(Some(ArgUnit::Dollar(name, dpos))))
        } else {
            self.error(LexErrorKind::InvalidIdentifier(name), dpos);
            self.bump();
            Ok(Some(None))
        }
    }
}

pub fn lex(src: &[u8]) -> Result<Vec<LexItem>, LexPanic> {
    let mut lexer = Lexer {
        src,
        i: 0,
        line: 1,
        col: 0,
        items: Vec::new(),
        cmd_mode: false,
        stopped: false,
    };
    lexer.run()?;
    Ok(lexer.items)
}
