    pub column: u32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Keyword {
    Let,
    If,
    Then,
    Else,
    ElseIf,
    End,
    For,
    In,
    Do,
    While,
    Function,
    Return,
    Break,
    Self_,
}

impl Keyword {
