// AST definitions and display.

use crate::lexer::{escape_char, escape_str, lossy, Expansion, Pos};
use std::fmt::Write;

pub const ILL_FORMED: &str = "***ill-formed***";

#[derive(Clone, Debug)]
pub struct Symbol {
    /// None means ill-formed.
    pub name: Option<Vec<u8>>,
    pub pos: Pos,
}

impl Symbol {
    pub fn ill_formed() -> Symbol {
        Symbol { name: None, pos: Pos { line: 0, column: 0 } }
    }
    pub fn display(&self) -> String {
        match &self.name {
            Some(n) => lossy(n),
            None => ILL_FORMED.to_string(),
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum UnaryOp {
    Minus,
    Not,
    Try,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BinaryOp {
    Plus,
    Minus,
    Times,
    Div,
    Mod,
    Concat,
    Equals,
    NotEquals,
    Lower,
    LowerEquals,
    Greater,
    GreaterEquals,
    And,
    Or,
}

impl BinaryOp {
    pub fn text(&self) -> &'static str {
        match self {
            BinaryOp::Plus => "+",
            BinaryOp::Minus => "-",
            BinaryOp::Times => "*",
            BinaryOp::Div => "/",
            BinaryOp::Mod => "%",
            BinaryOp::Concat => "++",
            BinaryOp::Equals => "==",
            BinaryOp::NotEquals => "!=",
            BinaryOp::Lower => "<",
            BinaryOp::LowerEquals => "<=",
            BinaryOp::Greater => ">",
            BinaryOp::GreaterEquals => ">=",
            BinaryOp::And => "and",
            BinaryOp::Or => "or",
        }
    }
}

#[derive(Clone, Debug)]
pub enum Literal {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    Byte(u8),
    String(Vec<u8>),
    Array(Vec<Expr>),
    Dict(Vec<(Symbol, Expr)>),
    Function { params: Vec<Symbol>, body: Block },
}

#[derive(Clone, Debug)]
pub enum Expr {
    IllFormed,
    Self_ { pos: Pos },
    Identifier(Symbol),
    Literal { lit: Literal, pos: Pos },
    Unary { op: UnaryOp, operand: Box<Expr>, pos: Pos },
    Binary { left: Box<Expr>, op: BinaryOp, right: Box<Expr>, pos: Pos },
    If { condition: Box<Expr>, then: Block, otherwise: Block, pos: Pos },
    Access { object: Box<Expr>, field: Symbol, pos: Pos },
    Index { object: Box<Expr>, index: Box<Expr>, pos: Pos },
    Call { function: Box<Expr>, args: Vec<Expr>, pos: Pos },
    CommandBlock { block: CommandBlock, pos: Pos },
}

impl Expr {
    pub fn pos(&self) -> Pos {
        match self {
            Expr::IllFormed => Pos { line: 0, column: 0 },
            Expr::Self_ { pos } => *pos,
            Expr::Identifier(s) => s.pos,
            Expr::Literal { pos, .. } => *pos,
            Expr::Unary { pos, .. } => *pos,
            Expr::Binary { pos, .. } => *pos,
            Expr::If { pos, .. } => *pos,
            Expr::Access { pos, .. } => *pos,
            Expr::Index { pos, .. } => *pos,
            Expr::Call { pos, .. } => *pos,
            Expr::CommandBlock { pos, .. } => *pos,
        }
    }
}

pub type Block = Vec<Statement>;

#[derive(Clone, Debug)]
pub enum Statement {
    IllFormed,
    Let { identifier: Symbol, init: Expr, pos: Pos },
    Assign { left: Expr, right: Expr, pos: Pos },
    Return { expr: Expr, pos: Pos },
    Break { pos: Pos },
    While { condition: Expr, block: Block, pos: Pos },
    For { identifier: Symbol, expr: Expr, block: Block, pos: Pos },
    Expr(Expr),
}

// Commands

#[derive(Clone, Debug)]
pub enum ArgUnit {
    Literal(Vec<u8>),
    Dollar(Symbol),
    Expansion(Expansion),
}

#[derive(Clone, Debug)]
pub struct Argument {
    pub units: Vec<ArgUnit>,
    pub pos: Pos,
}

#[derive(Clone, Debug)]
pub enum RedirectionTarget {
    Fd(u8),
    Overwrite(Argument),
    Append(Argument),
}

#[derive(Clone, Debug)]
pub enum Redirection {
    IllFormed,
    Output { source: u8, target: RedirectionTarget },
    Input { literal: bool, source: Argument },
}

#[derive(Clone, Debug)]
pub enum BasicCommand {
    IllFormed,
    Command {
        program: Argument,
        arguments: Vec<Argument>,
        redirections: Vec<Redirection>,
        abort_on_error: bool,
        pos: Pos,
    },
}

#[derive(Clone, Debug)]
pub struct Command {
    pub head: BasicCommand,
    pub tail: Vec<BasicCommand>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BlockKind {
    Synchronous,
    Capture,
    Async,
}

#[derive(Clone, Debug)]
pub struct CommandBlock {
    pub kind: BlockKind,
    pub head: Command,
    pub tail: Vec<Command>,
}

impl CommandBlock {
    pub fn ill_formed() -> CommandBlock {
        CommandBlock {
            kind: BlockKind::Synchronous,
            head: Command { head: BasicCommand::IllFormed, tail: Vec::new() },
            tail: Vec::new(),
        }
    }
}

