// Display

fn tabs(out: &mut String, n: usize) {
    for _ in 0..n {
        out.push('\t');
    }
}

/// Trait to abstract symbol display (AST uses names, program uses slots).
pub struct AstFmt;

impl AstFmt {
    pub fn block_top(block: &Block) -> String {
        let mut out = String::new();
        for (i, stmt) in block.iter().enumerate() {
            if i > 0 {
                out.push('\n');
            }
            stmt_multi(&mut out, stmt, 0);
        }
        out
    }
}

pub fn stmt_multi(out: &mut String, stmt: &Statement, n: usize) {
    match stmt {
        Statement::IllFormed => out.push_str(ILL_FORMED),
        Statement::Let { identifier, init, .. } => {
            let _ = write!(out, "let {} = ", identifier.display());
            expr_multi(out, init, n);
        }
        Statement::Assign { left, right, .. } => {
            expr_inline(out, left);
            out.push_str(" = ");
            expr_multi(out, right, n);
        }
        Statement::Return { expr, .. } => {
            out.push_str("return ");
            expr_multi(out, expr, n);
        }
        Statement::Break { .. } => out.push_str("break"),
        Statement::While { condition, block, .. } => {
            out.push_str("while ");
            expr_inline(out, condition);
            out.push_str(" do");
            block_multi_prefixed(out, block, n + 1);
            out.push('\n');
            tabs(out, n);
            out.push_str("end");
        }
        Statement::For { identifier, expr, block, .. } => {
            let _ = write!(out, "for {} in ", identifier.display());
            expr_inline(out, expr);
            out.push_str(" do");
            block_multi_prefixed(out, block, n + 1);
            out.push('\n');
            tabs(out, n);
            out.push_str("end");
        }
        Statement::Expr(e) => expr_multi(out, e, n),
    }
}

fn block_multi_prefixed(out: &mut String, block: &Block, n: usize) {
    for stmt in block {
        out.push('\n');
        tabs(out, n);
        stmt_multi(out, stmt, n);
    }
}

pub fn expr_multi(out: &mut String, expr: &Expr, n: usize) {
    match expr {
        Expr::Literal { lit: Literal::Array(items), .. } => {
            if items.is_empty() {
                out.push_str("[]");
                return;
            }
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push('\n');
                tabs(out, n + 1);
                expr_multi(out, item, n + 1);
            }
            out.push('\n');
            tabs(out, n);
            out.push(']');
        }
        Expr::Literal { lit: Literal::Dict(items), .. } => {
            if items.is_empty() {
                out.push_str("@[]");
                return;
            }
            out.push_str("@[");
            for (i, (k, v)) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push('\n');
                tabs(out, n + 1);
                let _ = write!(out, "{}: ", k.display());
                expr_multi(out, v, n + 1);
            }
            out.push('\n');
            tabs(out, n);
            out.push(']');
        }
        Expr::Literal { lit: Literal::Function { params, body }, .. } => {
            out.push_str("function(");
            params_fmt(out, params);
            out.push_str(")\n");
            for (i, stmt) in body.iter().enumerate() {
                if i > 0 {
                    out.push('\n');
                }
                tabs(out, n + 1);
                stmt_multi(out, stmt, n + 1);
            }
            out.push('\n');
            tabs(out, n);
            out.push_str("end");
        }
        Expr::If { condition, then, otherwise, .. } => {
            out.push_str("if ");
            expr_inline(out, condition);
            out.push_str(" then");
            block_multi_prefixed(out, then, n + 1);
            if !otherwise.is_empty() {
                out.push('\n');
                tabs(out, n);
                out.push_str("else");
                block_multi_prefixed(out, otherwise, n + 1);
            }
            out.push('\n');
            tabs(out, n);
            out.push_str("end");
        }
        Expr::CommandBlock { block, .. } => {
            out.push_str(block_prefix(block.kind));
            let cmds = std::iter::once(&block.head).chain(block.tail.iter());
            for (i, cmd) in cmds.enumerate() {
                if i > 0 {
                    out.push(';');
                }
                out.push('\n');
                tabs(out, n + 1);
                command_fmt(out, cmd);
            }
            out.push('\n');
            tabs(out, n);
            out.push('}');
        }
        other => expr_inline(out, other),
    }
}

fn params_fmt(out: &mut String, params: &[Symbol]) {
    for (i, p) in params.iter().enumerate() {
        if i > 0 {
            out.push_str(", ");
        }
        out.push_str(&p.display());
    }
}

fn block_prefix(kind: BlockKind) -> &'static str {
    match kind {
        BlockKind::Synchronous => "{",
        BlockKind::Capture => "${",
        BlockKind::Async => "&{",
    }
}

pub fn stmt_inline(out: &mut String, stmt: &Statement) {
    match stmt {
        Statement::IllFormed => out.push_str(ILL_FORMED),
        Statement::Let { identifier, init, .. } => {
            let _ = write!(out, "let {} = ", identifier.display());
            expr_inline(out, init);
        }
        Statement::Assign { left, right, .. } => {
            expr_inline(out, left);
            out.push_str(" = ");
            expr_inline(out, right);
        }
        Statement::Return { expr, .. } => {
            out.push_str("return ");
            expr_inline(out, expr);
        }
        Statement::Break { .. } => out.push_str("break"),
        Statement::While { condition, block, .. } => {
            out.push_str("while ");
            expr_inline(out, condition);
            out.push_str(" do ");
            block_inline(out, block);
            out.push_str("end");
        }
        Statement::For { identifier, expr, block, .. } => {
            let _ = write!(out, "for {} in ", identifier.display());
            expr_inline(out, expr);
            out.push_str(" do ");
            block_inline(out, block);
            out.push_str("end");
        }
        Statement::Expr(e) => expr_inline(out, e),
    }
}

fn block_inline(out: &mut String, block: &Block) {
    if block.is_empty() {
        return;
    }
    out.push(' ');
    for (i, stmt) in block.iter().enumerate() {
        if i > 0 {
            out.push_str("; ");
        }
        stmt_inline(out, stmt);
    }
    out.push(' ');
}

pub fn literal_simple(out: &mut String, lit: &Literal) -> bool {
    match lit {
        Literal::Nil => out.push_str("nil"),
        Literal::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Literal::Int(i) => {
            let _ = write!(out, "{}", i);
        }
        Literal::Float(x) => {
            let _ = write!(out, "{}", x);
        }
        Literal::Byte(b) => {
            let _ = write!(out, "'{}'", escape_char(*b));
        }
        Literal::String(s) => {
            let _ = write!(out, "\"{}\"", escape_str(s));
        }
        _ => return false,
    }
    true
}

pub fn expr_inline(out: &mut String, expr: &Expr) {
    match expr {
        Expr::IllFormed => out.push_str(ILL_FORMED),
        Expr::Self_ { .. } => out.push_str("self"),
        Expr::Identifier(s) => out.push_str(&s.display()),
        Expr::Literal { lit, .. } => {
            if literal_simple(out, lit) {
                return;
            }
            match lit {
                Literal::Array(items) => {
                    if items.is_empty() {
                        out.push_str("[]");
                        return;
                    }
                    out.push_str("[ ");
                    for (i, item) in items.iter().enumerate() {
                        if i > 0 {
                            out.push_str(", ");
                        }
                        expr_inline(out, item);
                    }
                    out.push_str(" ]");
                }
                Literal::Dict(items) => {
                    if items.is_empty() {
                        out.push_str("@[]");
                        return;
                    }
                    out.push_str("@[ ");
                    for (i, (k, v)) in items.iter().enumerate() {
                        if i > 0 {
                            out.push_str(", ");
                        }
                        let _ = write!(out, "{}: ", k.display());
                        expr_inline(out, v);
                    }
                    out.push_str(" ]");
                }
                Literal::Function { params, body } => {
                    out.push_str("function(");
                    params_fmt(out, params);
                    out.push(')');
                    for (i, stmt) in body.iter().enumerate() {
                        if i > 0 {
                            out.push(';');
                        }
                        out.push(' ');
                        stmt_inline(out, stmt);
                    }
                    out.push_str(" end");
                }
                _ => {}
            }
        }
        Expr::Unary { op, operand, .. } => match op {
            UnaryOp::Minus => {
                out.push_str("(- ");
                expr_inline(out, operand);
                out.push(')');
            }
            UnaryOp::Not => {
                out.push_str("(not ");
                expr_inline(out, operand);
                out.push(')');
            }
            UnaryOp::Try => {
                out.push('(');
                expr_inline(out, operand);
                out.push_str(" ?)");
            }
        },
        Expr::Binary { left, op, right, .. } => {
            out.push('(');
            expr_inline(out, left);
            let _ = write!(out, " {} ", op.text());
            expr_inline(out, right);
            out.push(')');
        }
        Expr::If { condition, then, otherwise, .. } => {
            out.push_str("if ");
            expr_inline(out, condition);
            out.push_str(" then");
            block_inline(out, then);
            if !otherwise.is_empty() {
                out.push_str("else");
                block_inline(out, otherwise);
            }
            out.push_str("end");
        }
        Expr::Access { object, field, .. } => {
            expr_inline(out, object);
            out.push('.');
            out.push_str(&field.display());
        }
        Expr::Index { object, index, .. } => {
            expr_inline(out, object);
            out.push('[');
            expr_inline(out, index);
            out.push(']');
        }
        Expr::Call { function, args, .. } => {
            expr_inline(out, function);
            out.push('(');
            for (i, a) in args.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                expr_inline(out, a);
            }
            out.push(')');
        }
        Expr::CommandBlock { block, .. } => {
            out.push_str(block_prefix(block.kind));
            out.push(' ');
            let cmds = std::iter::once(&block.head).chain(block.tail.iter());
            for (i, cmd) in cmds.enumerate() {
                if i > 0 {
                    out.push_str("; ");
                }
                command_fmt(out, cmd);
            }
            out.push_str(" }");
        }
    }
}

pub fn command_fmt(out: &mut String, cmd: &Command) {
    let all = std::iter::once(&cmd.head).chain(cmd.tail.iter());
    for (i, basic) in all.enumerate() {
        if i > 0 {
            out.push_str(" | ");
        }
        basic_fmt(out, basic);
    }
}

fn basic_fmt(out: &mut String, basic: &BasicCommand) {
    match basic {
        BasicCommand::IllFormed => out.push_str("***ill-formed*** ?"),
        BasicCommand::Command { program, arguments, redirections, abort_on_error, .. } => {
            arg_fmt(out, program);
            for a in arguments {
                out.push(' ');
                arg_fmt(out, a);
            }
            for r in redirections {
                out.push(' ');
                redir_fmt(out, r);
            }
            if !abort_on_error {
                out.push_str(" ?");
            }
        }
    }
}

pub fn arg_fmt(out: &mut String, arg: &Argument) {
    out.push('"');
    for unit in &arg.units {
        match unit {
            ArgUnit::Literal(l) => out.push_str(&escape_str(l)),
            ArgUnit::Dollar(s) => {
                let _ = write!(out, "${{{}}}", s.display());
            }
            ArgUnit::Expansion(e) => {
                let _ = write!(out, "{}", e);
            }
        }
    }
    out.push('"');
}

fn redir_fmt(out: &mut String, r: &Redirection) {
    match r {
        Redirection::IllFormed => out.push_str(ILL_FORMED),
        Redirection::Output { source, target } => match target {
            RedirectionTarget::Fd(fd) => {
                let _ = write!(out, "{}>{}", source, fd);
            }
            RedirectionTarget::Overwrite(a) => {
                let _ = write!(out, "{}>", source);
                arg_fmt(out, a);
            }
            RedirectionTarget::Append(a) => {
                let _ = write!(out, "{}>>", source);
                arg_fmt(out, a);
            }
        },
        Redirection::Input { literal, source } => {
            out.push_str(if *literal { "<<" } else { "<" });
            arg_fmt(out, source);
        }
    }
}
