            Expr::Unary { pos, .. } => *pos,
            Expr::Binary { pos, .. } => *pos,
            Expr::If { pos, .. } => *pos,
            Expr::Access { pos, .. } => *pos,
            Expr::Index { pos, .. } => *pos,
            Expr::Call { pos, .. } => *pos,
            Expr::CommandBlock { pos, .. } => *pos,
        }
    }
}

pub type Block = Vec<Statement>;

#[derive(Clone, Debug)]
pub enum Statement {
    IllFormed,
    Let { identifier: Symbol, init: Expr, pos: Pos },
    Assign { left: Expr, right: Expr, pos: Pos },
    Return { expr: Expr, pos: Pos },
    Break { pos: Pos },
    While { condition: Expr, block: Block, pos: Pos },
