// Parser for the Hush language, with error recovery mimicking the reference implementation.

use crate::ast::*;
use crate::lexer::{self, CmdOp, Keyword, LexError, LexItem, Operator, Pos, Token, TokenKind};

#[derive(Clone, Debug)]
pub enum SyntaxError {
    Lex(LexError),
    Unexpected { token: Token, expected: &'static str },
    UnexpectedEof,
    EmptyCommandBlock(Pos),
}

pub struct Parser {
    items: Vec<LexItem>,
    idx: usize,
    token: Option<Token>,
    token_index: usize,
    last_error_index: Option<usize>,
    pub errors: Vec<SyntaxError>,
}

type PResult<T> = Result<T, ()>;

fn is_kw(tok: &Option<Token>, kw: Keyword) -> bool {
    matches!(tok, Some(Token { kind: TokenKind::Keyword(k), .. }) if *k == kw)
}

fn is_kind(tok: &Option<Token>, kind: &TokenKind) -> bool {
    match tok {
        Some(t) => &t.kind == kind,
        None => false,
    }
}

impl Parser {
    pub fn new(items: Vec<LexItem>) -> Parser {
        let mut p = Parser {
            items,
            idx: 0,
            token: None,
            token_index: 0,
            last_error_index: None,
            errors: Vec::new(),
        };
        p.load();
        p
    }

    fn load(&mut self) {
        self.token = None;
        while self.idx < self.items.len() {
            let item = self.items[self.idx].clone();
            self.idx += 1;
            match item {
                LexItem::Error(e) => self.errors.push(SyntaxError::Lex(e)),
                LexItem::Token(t) => {
                    self.token = Some(t);
                    return;
                }
            }
        }
    }

    fn advance(&mut self) {
        if self.token.is_some() {
            self.token_index += 1;
        }
        self.load();
    }

    /// Peek the token after the current one (without reporting lexer errors).
    fn peek_next(&self) -> Option<&Token> {
        let mut i = self.idx;
        while i < self.items.len() {
            if let LexItem::Token(t) = &self.items[i] {
                return Some(t);
            }
            i += 1;
        }
        None
    }

    fn error_unexpected(&mut self, expected: &'static str) {
        match &self.token {
            Some(t) => {
                let t = t.clone();
                self.errors.push(SyntaxError::Unexpected { token: t, expected });
            }
            None => self.errors.push(SyntaxError::UnexpectedEof),
        }
        self.last_error_index = Some(self.token_index);
    }

    /// Skip tokens until the given kind is found, consuming it.
    fn sync_to(&mut self, kind: &TokenKind) {
        loop {
            match &self.token {
                None => return,
                Some(t) => {
                    let found = &t.kind == kind;
                    self.advance();
                    if found {
                        return;
                    }
                }
            }
        }
    }

    fn sync_eof(&mut self) {
        while self.token.is_some() {
            self.advance();
        }
    }

    fn is_block_terminator(&self) -> bool {
        match &self.token {
            None => true,
            Some(Token { kind: TokenKind::Keyword(k), .. }) => {
                matches!(k, Keyword::End | Keyword::Else | Keyword::ElseIf)
            }
            _ => false,
        }
    }

    pub fn parse(&mut self) -> Block {
        loop {
            let block = self.parse_block();
            match &self.token {
                None => return block,
                Some(Token { kind: TokenKind::Keyword(k), .. })
                    if matches!(k, Keyword::End | Keyword::Else | Keyword::ElseIf) =>
                {
                    self.error_unexpected("statement");
                    return Vec::new();
                }
                _ => continue,
            }
        }
    }

    fn parse_block(&mut self) -> Block {
        let mut stmts = Vec::new();
        loop {
            if self.is_block_terminator() {
                break;
            }
            let is_return = is_kw(&self.token, Keyword::Return);
            let stmt = self.parse_statement_recover();
            stmts.push(stmt);
            if is_return {
                break;
            }
        }
        stmts
    }

    fn parse_statement_recover(&mut self) -> Statement {
        match self.parse_statement() {
            Ok(s) => s,
            Err(()) => {
                if self.token.is_some() && self.last_error_index == Some(self.token_index) {
                    self.advance();
                }
                Statement::IllFormed
            }
        }
    }

    fn parse_statement(&mut self) -> PResult<Statement> {
        let tok = match &self.token {
            Some(t) => t.clone(),
            None => {
                self.error_unexpected("statement");
                return Err(());
            }
        };
        match &tok.kind {
            TokenKind::Keyword(Keyword::Let) => {
                self.advance();
                let identifier = self.parse_identifier_soft();
                let init = if is_kind(&self.token, &TokenKind::Assign) {
                    self.advance();
                    self.parse_expression()?
                } else {
                    Expr::Literal { lit: Literal::Nil, pos: tok.pos }
                };
                Ok(Statement::Let { identifier, init, pos: tok.pos })
            }
            TokenKind::Keyword(Keyword::Function)
                if matches!(self.peek_next(), Some(Token { kind: TokenKind::Identifier(_), .. })) =>
            {
                self.advance();
                let identifier = self.parse_identifier_soft();
                let func = self.parse_function_literal(tok.pos)?;
                Ok(Statement::Let { identifier, init: func, pos: tok.pos })
            }
            TokenKind::Keyword(Keyword::Return) => {
                self.advance();
                let expr = if matches!(
                    &self.token,
                    Some(Token { kind: TokenKind::Keyword(Keyword::End | Keyword::Else | Keyword::ElseIf), .. })
                ) {
                    Expr::Literal { lit: Literal::Nil, pos: tok.pos }
                } else {
                    self.parse_expression()?
                };
                Ok(Statement::Return { expr, pos: tok.pos })
            }
            TokenKind::Keyword(Keyword::Break) => {
                self.advance();
                Ok(Statement::Break { pos: tok.pos })
            }
            TokenKind::Keyword(Keyword::While) => {
                self.advance();
                let condition = self.parse_expression_recover();
                self.expect_soft(Keyword::Do, "'do'");
                let block = self.parse_block();
                self.expect_end()?;
                Ok(Statement::While { condition, block, pos: tok.pos })
            }
            TokenKind::Keyword(Keyword::For) => {
                self.advance();
                let identifier = self.parse_identifier_soft();
                if is_kw(&self.token, Keyword::In) {
                    self.advance();
                } else {
                    self.error_unexpected("'in'");
                    self.advance();
                }
                let expr = self.parse_expression_recover();
                self.expect_soft(Keyword::Do, "'do'");
                let block = self.parse_block();
                self.expect_end()?;
                Ok(Statement::For { identifier, expr, block, pos: tok.pos })
            }
            _ => {
                let left = self.parse_expression()?;
                if let Some(Token { kind: TokenKind::Assign, pos }) = &self.token {
                    let pos = *pos;
                    self.advance();
                    let right = self.parse_expression()?;
                    Ok(Statement::Assign { left, right, pos })
                } else {
                    Ok(Statement::Expr(left))
                }
            }
        }
    }

    fn parse_identifier_soft(&mut self) -> Symbol {
        if let Some(Token { kind: TokenKind::Identifier(name), pos }) = &self.token {
            let s = Symbol { name: Some(name.clone()), pos: *pos };
            self.advance();
            s
        } else {
            self.error_unexpected("identifier");
            Symbol::ill_formed()
        }
    }

    fn expect_soft(&mut self, kw: Keyword, expected: &'static str) {
        if is_kw(&self.token, kw) {
            self.advance();
        } else {
            self.error_unexpected(expected);
        }
    }

    fn expect_end(&mut self) -> PResult<()> {
        if is_kw(&self.token, Keyword::End) {
            self.advance();
            Ok(())
        } else {
            self.error_unexpected("'end'");
            self.sync_to(&TokenKind::Keyword(Keyword::End));
            Err(())
        }
    }

    fn parse_expression_recover(&mut self) -> Expr {
        self.parse_expression().unwrap_or(Expr::IllFormed)
    }

    pub fn parse_expression(&mut self) -> PResult<Expr> {
        self.parse_or()
    }

    fn binary_op(&self, level: u8) -> Option<(BinaryOp, Pos)> {
        let tok = self.token.as_ref()?;
        let op = match &tok.kind {
            TokenKind::Operator(op) => *op,
            _ => return None,
        };
        let bop = match (level, op) {
            (0, Operator::Or) => BinaryOp::Or,
            (1, Operator::And) => BinaryOp::And,
            (2, Operator::Equals) => BinaryOp::Equals,
            (2, Operator::NotEquals) => BinaryOp::NotEquals,
            (3, Operator::Lower) => BinaryOp::Lower,
            (3, Operator::LowerEquals) => BinaryOp::LowerEquals,
            (3, Operator::Greater) => BinaryOp::Greater,
            (3, Operator::GreaterEquals) => BinaryOp::GreaterEquals,
            (4, Operator::Concat) => BinaryOp::Concat,
            (5, Operator::Plus) => BinaryOp::Plus,
            (5, Operator::Minus) => BinaryOp::Minus,
            (6, Operator::Times) => BinaryOp::Times,
            (6, Operator::Div) => BinaryOp::Div,
            (6, Operator::Mod) => BinaryOp::Mod,
            _ => return None,
        };
        Some((bop, tok.pos))
    }

    fn parse_level(&mut self, level: u8) -> PResult<Expr> {
        if level > 6 {
            return self.parse_unary();
        }
        let mut left = self.parse_level(level + 1)?;
        while let Some((op, pos)) = self.binary_op(level) {
            self.advance();
            let right = self.parse_level(level + 1)?;
            left = Expr::Binary { left: Box::new(left), op, right: Box::new(right), pos };
        }
        Ok(left)
    }

    fn parse_or(&mut self) -> PResult<Expr> {
        self.parse_level(0)
    }

    fn parse_unary(&mut self) -> PResult<Expr> {
        match &self.token {
            Some(Token { kind: TokenKind::Operator(Operator::Minus), pos }) => {
                let pos = *pos;
                self.advance();
                let operand = self.parse_unary()?;
                Ok(Expr::Unary { op: UnaryOp::Minus, operand: Box::new(operand), pos })
            }
            Some(Token { kind: TokenKind::Operator(Operator::Not), pos }) => {
                let pos = *pos;
                self.advance();
                let operand = self.parse_unary()?;
                Ok(Expr::Unary { op: UnaryOp::Not, operand: Box::new(operand), pos })
            }
            _ => self.parse_postfix(),
        }
    }

    fn parse_postfix(&mut self) -> PResult<Expr> {
        let mut expr = self.parse_primary()?;
        loop {
            match &self.token {
                Some(Token { kind: TokenKind::Operator(Operator::Dot), pos }) => {
                    let pos = *pos;
                    self.advance();
                    if let Some(Token { kind: TokenKind::Identifier(name), pos: fpos }) = &self.token {
                        let field = Symbol { name: Some(name.clone()), pos: *fpos };
                        self.advance();
                        expr = Expr::Access { object: Box::new(expr), field, pos };
                    } else {
                        self.error_unexpected("identifier");
                        return Err(());
                    }
                }
                Some(Token { kind: TokenKind::OpenBracket, pos }) => {
                    let pos = *pos;
                    self.advance();
                    let index = self.parse_expression_recover();
                    if is_kind(&self.token, &TokenKind::CloseBracket) {
                        self.advance();
                    } else {
                        self.error_unexpected("']'");
                        self.sync_to(&TokenKind::CloseBracket);
                        return Err(());
                    }
                    expr = Expr::Index { object: Box::new(expr), index: Box::new(index), pos };
                }
                Some(Token { kind: TokenKind::OpenParens, pos }) => {
                    let pos = *pos;
                    self.advance();
                    let mut args = Vec::new();
                    loop {
                        if is_kind(&self.token, &TokenKind::CloseParens) {
                            self.advance();
                            break;
                        }
                        args.push(self.parse_expression_recover());
                        if is_kind(&self.token, &TokenKind::Comma) {
                            self.advance();
                        } else if is_kind(&self.token, &TokenKind::CloseParens) {
                            self.advance();
                            break;
                        } else {
                            self.error_unexpected("')'");
                            self.sync_to(&TokenKind::CloseParens);
                            return Err(());
                        }
                    }
                    expr = Expr::Call { function: Box::new(expr), args, pos };
                }
                Some(Token { kind: TokenKind::Try, pos }) => {
                    let pos = *pos;
                    self.advance();
                    expr = Expr::Unary { op: UnaryOp::Try, operand: Box::new(expr), pos };
                }
                _ => return Ok(expr),
            }
        }
    }

    fn parse_primary(&mut self) -> PResult<Expr> {
        let tok = match &self.token {
            Some(t) => t.clone(),
            None => {
                self.error_unexpected("expression");
                return Err(());
            }
        };
        let pos = tok.pos;
        match tok.kind {
            TokenKind::Identifier(name) => {
                self.advance();
                Ok(Expr::Identifier(Symbol { name: Some(name), pos }))
            }
            TokenKind::Keyword(Keyword::Self_) => {
                self.advance();
                Ok(Expr::Self_ { pos })
            }
            TokenKind::Literal(lit) => {
                self.advance();
                let lit = match lit {
                    lexer::Literal::Nil => Literal::Nil,
                    lexer::Literal::True => Literal::Bool(true),
                    lexer::Literal::False => Literal::Bool(false),
                    lexer::Literal::Int(i) => Literal::Int(i),
                    lexer::Literal::Float(x) => Literal::Float(x),
                    lexer::Literal::Byte(b) => Literal::Byte(b),
                    lexer::Literal::String(s) => Literal::String(s),
                };
                Ok(Expr::Literal { lit, pos })
            }
            TokenKind::OpenParens => {
                self.advance();
                let inner = self.parse_expression_recover();
                if is_kind(&self.token, &TokenKind::CloseParens) {
                    self.advance();
                    Ok(inner)
                } else {
                    self.error_unexpected("')'");
                    self.sync_to(&TokenKind::CloseParens);
                    Err(())
                }
            }
            TokenKind::OpenBracket => {
                self.advance();
                let mut items = Vec::new();
                loop {
                    if is_kind(&self.token, &TokenKind::CloseBracket) {
                        self.advance();
                        break;
                    }
                    items.push(self.parse_expression_recover());
                    if is_kind(&self.token, &TokenKind::Comma) {
                        self.advance();
                    } else if is_kind(&self.token, &TokenKind::CloseBracket) {
                        self.advance();
                        break;
                    } else {
                        self.error_unexpected("']'");
                        self.sync_to(&TokenKind::CloseBracket);
                        return Err(());
                    }
                }
                Ok(Expr::Literal { lit: Literal::Array(items), pos })
            }
            TokenKind::OpenDict => {
                self.advance();
                let mut items = Vec::new();
                loop {
                    if is_kind(&self.token, &TokenKind::CloseBracket) {
                        self.advance();
                        break;
                    }
                    let key = if let Some(Token { kind: TokenKind::Identifier(name), pos }) = &self.token {
                        let s = Symbol { name: Some(name.clone()), pos: *pos };
                        self.advance();
                        s
                    } else {
                        self.error_unexpected("identifier");
                        self.advance();
                        Symbol::ill_formed()
                    };
                    if is_kind(&self.token, &TokenKind::Colon) {
                        self.advance();
                    } else {
                        self.error_unexpected("':'");
                    }
                    match self.parse_expression() {
                        Ok(value) => items.push((key, value)),
                        Err(()) => items.push((Symbol::ill_formed(), Expr::IllFormed)),
                    }
                    if is_kind(&self.token, &TokenKind::Comma) {
                        self.advance();
                    } else if is_kind(&self.token, &TokenKind::CloseBracket) {
                        self.advance();
                        break;
                    } else {
                        self.error_unexpected("']'");
                        self.sync_to(&TokenKind::CloseBracket);
                        return Err(());
                    }
                }
                Ok(Expr::Literal { lit: Literal::Dict(items), pos })
            }
            TokenKind::Keyword(Keyword::Function) => {
                self.advance();
                self.parse_function_literal(pos)
            }
            TokenKind::Keyword(Keyword::If) => {
                self.advance();
                self.parse_if(pos)
            }
            TokenKind::Command | TokenKind::CaptureCommand | TokenKind::AsyncCommand => {
                let kind = match tok.kind {
                    TokenKind::Command => BlockKind::Synchronous,
                    TokenKind::CaptureCommand => BlockKind::Capture,
                    _ => BlockKind::Async,
                };
                self.advance();
                let block = self.parse_command_block(kind);
                Ok(Expr::CommandBlock { block, pos })
            }
            _ => {
                self.error_unexpected("expression");
                Err(())
            }
        }
    }

    fn parse_function_literal(&mut self, pos: Pos) -> PResult<Expr> {
        if is_kind(&self.token, &TokenKind::OpenParens) {
            self.advance();
        } else {
            self.error_unexpected("'('");
        }
        let mut params = Vec::new();
        loop {
            if is_kind(&self.token, &TokenKind::CloseParens) {
                self.advance();
                break;
            }
            params.push(self.parse_identifier_soft());
            if is_kind(&self.token, &TokenKind::Comma) {
                self.advance();
            } else if is_kind(&self.token, &TokenKind::CloseParens) {
                self.advance();
                break;
            } else {
                self.error_unexpected("')'");
                self.sync_to(&TokenKind::CloseParens);
                break;
            }
        }
        let body = self.parse_block();
        self.expect_end()?;
        Ok(Expr::Literal { lit: Literal::Function { params, body }, pos })
    }

    fn parse_if(&mut self, pos: Pos) -> PResult<Expr> {
        let condition = self.parse_expression_recover();
        self.expect_soft(Keyword::Then, "'then'");
        let then = self.parse_block();
        let otherwise = match &self.token {
            Some(Token { kind: TokenKind::Keyword(Keyword::End), .. }) => {
                self.advance();
                Vec::new()
            }
            Some(Token { kind: TokenKind::Keyword(Keyword::Else), .. }) => {
                self.advance();
                let block = self.parse_block();
                self.expect_end()?;
                block
            }
            Some(Token { kind: TokenKind::Keyword(Keyword::ElseIf), pos: epos }) => {
                let epos = *epos;
                self.advance();
                let nested = self.parse_if(epos)?;
                vec![Statement::Expr(nested)]
            }
            _ => {
                self.error_unexpected("end, else or elseif");
                self.sync_eof();
                return Err(());
            }
        };
        Ok(Expr::If { condition: Box::new(condition), then, otherwise, pos })
    }

    // Commands

    fn parse_command_block(&mut self, kind: BlockKind) -> CommandBlock {
        if let Some(Token { kind: TokenKind::CloseCommand, pos }) = &self.token {
            let pos = *pos;
            self.advance();
            self.errors.push(SyntaxError::EmptyCommandBlock(pos));
            return CommandBlock::ill_formed();
        }
        let mut commands = Vec::new();
        loop {
            if is_kind(&self.token, &TokenKind::CloseCommand) {
                self.advance();
                break;
            }
            commands.push(self.parse_pipeline());
            match &self.token {
                Some(Token { kind: TokenKind::Semicolon, .. }) => {
                    self.advance();
                    if is_kind(&self.token, &TokenKind::CloseCommand) {
                        self.advance();
                        break;
                    }
                }
                Some(Token { kind: TokenKind::CloseCommand, .. }) => {
                    self.advance();
                    break;
                }
                _ => {
                    self.error_unexpected("'}'");
                    self.sync_to(&TokenKind::CloseCommand);
                    return CommandBlock::ill_formed();
                }
            }
        }
        let mut iter = commands.into_iter();
        let head = iter.next().unwrap();
        CommandBlock { kind, head, tail: iter.collect() }
    }

    fn parse_pipeline(&mut self) -> Command {
        let head = self.parse_basic_command();
        let mut tail = Vec::new();
        while is_kind(&self.token, &TokenKind::Pipe) {
            self.advance();
            tail.push(self.parse_basic_command());
        }
        Command { head, tail }
    }

    fn take_argument(&mut self) -> Option<Argument> {
        if let Some(Token { kind: TokenKind::Argument(parts), pos }) = &self.token {
            let arg = convert_argument(parts, *pos);
            self.advance();
            Some(arg)
        } else {
            None
        }
    }

    fn parse_basic_command(&mut self) -> BasicCommand {
        let pos = match &self.token {
            Some(t) => t.pos,
            None => Pos::default(),
        };
        let program = match self.take_argument() {
            Some(a) => a,
            None => {
                self.error_unexpected("argument");
                self.advance();
                return BasicCommand::IllFormed;
            }
        };
        let mut arguments = Vec::new();
        loop {
            match &self.token {
                Some(Token { kind: TokenKind::Argument(parts), .. }) => {
                    if is_digits_arg(parts)
                        && matches!(self.peek_next(), Some(Token { kind: TokenKind::CmdOperator(_), .. }))
                    {
                        break;
                    }
                    let a = self.take_argument().unwrap();
                    arguments.push(a);
                }
                _ => break,
            }
        }
        let mut redirections = Vec::new();
        loop {
            match &self.token {
                Some(Token { kind: TokenKind::Argument(parts), .. }) => {
                    let fd = parse_fd(parts);
                    match fd {
                        Some(fd) => {
                            self.advance();
                            match &self.token {
                                Some(Token { kind: TokenKind::CmdOperator(CmdOp::Output { append }), .. }) => {
                                    let append = *append;
                                    self.advance();
                                    redirections.push(self.parse_output_target(fd, append));
                                }
                                _ => {
                                    self.error_unexpected("output redirection");
                                    self.advance();
                                    redirections.push(Redirection::IllFormed);
                                }
                            }
                        }
                        None => {
                            self.error_unexpected("output redirection");
                            self.advance();
                            redirections.push(Redirection::IllFormed);
                        }
                    }
                }
                Some(Token { kind: TokenKind::CmdOperator(CmdOp::Output { append }), .. }) => {
                    let append = *append;
                    self.advance();
                    redirections.push(self.parse_output_target(1, append));
                }
                Some(Token { kind: TokenKind::CmdOperator(CmdOp::Input { literal }), .. }) => {
                    let literal = *literal;
                    self.advance();
                    match self.take_argument() {
                        Some(source) => redirections.push(Redirection::Input { literal, source }),
                        None => {
                            self.error_unexpected("argument");
                            redirections.push(Redirection::IllFormed);
                        }
                    }
                }
                _ => break,
            }
        }
        let abort_on_error = match &self.token {
            Some(Token { kind: TokenKind::Try, .. }) => {
                self.advance();
                false
            }
            None => {
                self.errors.push(SyntaxError::UnexpectedEof);
                true
            }
            _ => true,
        };
        BasicCommand::Command { program, arguments, redirections, abort_on_error, pos }
    }

    fn parse_output_target(&mut self, source: u8, append: bool) -> Redirection {
        match &self.token {
            Some(Token { kind: TokenKind::Argument(parts), .. }) => {
                let fd = if append { None } else { parse_fd(parts) };
                let arg = self.take_argument().unwrap();
                let target = match fd {
                    Some(fd) => RedirectionTarget::Fd(fd),
                    None => {
                        if append {
                            RedirectionTarget::Append(arg)
                        } else {
                            RedirectionTarget::Overwrite(arg)
                        }
                    }
                };
                Redirection::Output { source, target }
            }
            _ => {
                self.error_unexpected("argument");
                Redirection::IllFormed
            }
        }
    }
}

fn single_literal(parts: &[lexer::ArgPart]) -> Option<&[u8]> {
    if parts.len() == 1 {
        if let lexer::ArgPart::Unquoted(lexer::ArgUnit::Literal(l)) = &parts[0] {
            return Some(l);
        }
    }
    None
}

fn is_digits_arg(parts: &[lexer::ArgPart]) -> bool {
    match single_literal(parts) {
        Some(l) => !l.is_empty() && l.iter().all(|c| c.is_ascii_digit()),
        None => false,
    }
}

fn parse_fd(parts: &[lexer::ArgPart]) -> Option<u8> {
    let l = single_literal(parts)?;
    std::str::from_utf8(l).ok()?.parse::<u8>().ok()
}

fn convert_argument(parts: &[lexer::ArgPart], pos: Pos) -> Argument {
    let mut units = Vec::new();
    for part in parts {
        match part {
            lexer::ArgPart::Unquoted(u) => units.push(convert_unit(u)),
            lexer::ArgPart::SingleQuoted(l) => {
                if !l.is_empty() {
                    units.push(ArgUnit::Literal(l.clone()));
                }
            }
            lexer::ArgPart::DoubleQuoted(us) => {
                for u in us {
                    units.push(convert_unit(u));
                }
            }
            lexer::ArgPart::Expansion(e) => units.push(ArgUnit::Expansion(*e)),
        }
    }
    Argument { units, pos }
}

fn convert_unit(u: &lexer::ArgUnit) -> ArgUnit {
    match u {
        lexer::ArgUnit::Literal(l) => ArgUnit::Literal(l.clone()),
        lexer::ArgUnit::Dollar(name, pos) => ArgUnit::Dollar(Symbol { name: Some(name.clone()), pos: *pos }),
    }
}
