    Dict(Vec<(Rc<[u8]>, Expr)>),
    Function(Rc<FunctionDef>),
}

#[derive(Debug)]
pub enum Expr {
    Slot { slot: usize, pos: SourcePos },
    Literal { lit: Lit, pos: SourcePos },
    Unary { op: UnaryOp, operand: Box<Expr>, pos: SourcePos },
    Binary { left: Box<Expr>, op: BinaryOp, right: Box<Expr>, pos: SourcePos },
    If { condition: Box<Expr>, then: Vec<Stmt>, otherwise: Vec<Stmt>, pos: SourcePos },
    Access { object: Box<Expr>, field: Rc<[u8]>, field_pos: SourcePos, pos: SourcePos },
    Index { object: Box<Expr>, index: Box<Expr>, pos: SourcePos },
    Call { function: Box<Expr>, args: Vec<Expr>, pos: SourcePos },
    CommandBlock { block: Rc<CommandBlock>, pos: SourcePos },
}

impl Expr {
    pub fn pos(&self) -> &SourcePos {
        match self {
            Expr::Slot { pos, .. } => pos,
            Expr::Literal { pos, .. } => pos,
            Expr::Unary { pos, .. } => pos,
            Expr::Binary { pos, .. } => pos,
            Expr::If { pos, .. } => pos,
            Expr::Access { pos, .. } => pos,
            Expr::Index { pos, .. } => pos,
            Expr::Call { pos, .. } => pos,
            Expr::CommandBlock { pos, .. } => pos,
        }
    }
}

#[derive(Debug)]
pub enum Stmt {
