// Program IR (result of semantic analysis) and its display.

use crate::ast::{BinaryOp, BlockKind, UnaryOp};
use crate::lexer::{escape_char, escape_str, Expansion};
use std::fmt::Write;
use std::rc::Rc;

#[derive(Clone, Debug, PartialEq)]
pub struct SourcePos {
    pub path: Rc<str>,
    pub line: u32,
    pub column: u32,
}

impl std::fmt::Display for SourcePos {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        if self.line == 0 {
            write!(f, "***ill-formed*** (line 0, column 0)")
        } else {
            write!(f, "{} (line {}, column {})", self.path, self.line, self.column)
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SlotKind {
    Regular,
    Closed(usize),
    SelfValue,
}

#[derive(Debug)]
pub struct FunctionDef {
    pub params: usize,
    pub slots: Vec<SlotKind>,
    pub body: Vec<Stmt>,
    pub pos: SourcePos,
}

#[derive(Debug)]
pub enum Lit {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    Byte(u8),
    String(Rc<[u8]>),
    Array(Vec<Expr>),
    Dict(Vec<(Rc<[u8]>, Expr)>),
    Function(Rc<FunctionDef>),
}

#[derive(Debug)]
pub enum Expr {
    Slot { slot: usize, pos: SourcePos },
    Literal { lit: Lit, pos: SourcePos },
    Unary { op: UnaryOp, operand: Box<Expr>, pos: SourcePos },
    Binary { left: Box<Expr>, op: BinaryOp, right: Box<Expr>, pos: SourcePos },
    If { condition: Box<Expr>, then: Vec<Stmt>, otherwise: Vec<Stmt>, pos: SourcePos },
    Access { object: Box<Expr>, field: Rc<[u8]>, field_pos: SourcePos, pos: SourcePos },
    Index { object: Box<Expr>, index: Box<Expr>, pos: SourcePos },
    Call { function: Box<Expr>, args: Vec<Expr>, pos: SourcePos },
    CommandBlock { block: Rc<CommandBlock>, pos: SourcePos },
}

impl Expr {
    pub fn pos(&self) -> &SourcePos {
        match self {
            Expr::Slot { pos, .. } => pos,
            Expr::Literal { pos, .. } => pos,
            Expr::Unary { pos, .. } => pos,
            Expr::Binary { pos, .. } => pos,
            Expr::If { pos, .. } => pos,
            Expr::Access { pos, .. } => pos,
            Expr::Index { pos, .. } => pos,
            Expr::Call { pos, .. } => pos,
            Expr::CommandBlock { pos, .. } => pos,
        }
    }
}

#[derive(Debug)]
pub enum Stmt {
    Let { slot: usize, init: Expr },
    Assign { left: Expr, right: Expr, pos: SourcePos },
    Return { expr: Expr },
    Break,
    While { condition: Expr, block: Vec<Stmt> },
    For { slot: usize, expr: Expr, block: Vec<Stmt> },
    Expr(Expr),
}

// Commands

#[derive(Debug, Clone)]
pub enum ArgUnit {
    Literal(Rc<[u8]>),
    Dollar { slot: usize, pos: SourcePos },
    Expansion(Expansion),
}

#[derive(Debug, Clone)]
pub struct Argument {
    pub units: Vec<ArgUnit>,
    pub pos: SourcePos,
}

#[derive(Debug, Clone)]
pub enum RedirectionTarget {
    Fd(u8),
    Overwrite(Argument),
    Append(Argument),
}

#[derive(Debug, Clone)]
pub enum Redirection {
    Output { source: u8, target: RedirectionTarget },
    Input { literal: bool, source: Argument },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Builtin {
    Alias,
    Cd,
    Exec,
    Exec0,
    Spawn0,
}

#[derive(Debug, Clone)]
pub enum BasicCommand {
    Command {
        program: Argument,
        arguments: Vec<Argument>,
        redirections: Vec<Redirection>,
        abort_on_error: bool,
        pos: SourcePos,
    },
    Builtin {
        builtin: Builtin,
        program: Argument,
        arguments: Vec<Argument>,
        abort_on_error: bool,
        pos: SourcePos,
        redirections: Vec<Redirection>,
    },
}

#[derive(Debug, Clone)]
pub struct Command {
    pub head: BasicCommand,
    pub tail: Vec<BasicCommand>,
}

#[derive(Debug)]
pub struct CommandBlock {
    pub kind: BlockKind,
    pub head: Command,
    pub tail: Vec<Command>,
}

pub struct Program {
    pub root_slots: Vec<SlotKind>,
    pub body: Vec<Stmt>,
}

// ---------------------------------------------------------------------------
// Display

fn tabs(out: &mut String, n: usize) {
    for _ in 0..n {
        out.push('\t');
    }
}

fn slot_decl(out: &mut String, i: usize, kind: &SlotKind) {
    match kind {
        SlotKind::Regular => {
            let _ = write!(out, "let #{}: auto", i);
        }
        SlotKind::Closed(p) => {
            let _ = write!(out, "let #{}: capture #{}", i, p);
        }
        SlotKind::SelfValue => {
            let _ = write!(out, "let #{}: auto self", i);
        }
    }
}

pub fn program_fmt(program: &Program) -> String {
    let mut out = String::new();
    for (i, kind) in program.root_slots.iter().enumerate() {
        if i > 0 {
            out.push('\n');
        }
        slot_decl(&mut out, i, kind);
    }
    out.push('\n');
    for (i, stmt) in program.body.iter().enumerate() {
        if i > 0 {
            out.push('\n');
        }
        stmt_multi(&mut out, stmt, 0);
    }
    out
}

fn stmt_multi(out: &mut String, stmt: &Stmt, n: usize) {
    match stmt {
        Stmt::Let { slot, init } => {
            let _ = write!(out, "#{} = ", slot);
            expr_multi(out, init, n);
        }
        Stmt::Assign { left, right, .. } => {
            expr_inline(out, left);
            out.push_str(" = ");
            expr_multi(out, right, n);
        }
        Stmt::Return { expr } => {
            out.push_str("return ");
            expr_multi(out, expr, n);
        }
        Stmt::Break => out.push_str("break"),
        Stmt::While { condition, block } => {
            out.push_str("while ");
            expr_inline(out, condition);
            out.push_str(" do");
            block_prefixed(out, block, n + 1);
            out.push('\n');
            tabs(out, n);
            out.push_str("end");
        }
        Stmt::For { slot, expr, block } => {
            let _ = write!(out, "for #{} in ", slot);
            expr_inline(out, expr);
            out.push_str(" do");
            block_prefixed(out, block, n + 1);
            out.push('\n');
            tabs(out, n);
            out.push_str("end");
        }
        Stmt::Expr(e) => expr_multi(out, e, n),
    }
}

fn block_prefixed(out: &mut String, block: &[Stmt], n: usize) {
    for stmt in block {
        out.push('\n');
        tabs(out, n);
        stmt_multi(out, stmt, n);
    }
}

fn block_prefix(kind: BlockKind) -> &'static str {
    match kind {
        BlockKind::Synchronous => "{",
        BlockKind::Capture => "${",
        BlockKind::Async => "&{",
    }
}

fn expr_multi(out: &mut String, expr: &Expr, n: usize) {
    match expr {
        Expr::Literal { lit: Lit::Array(items), .. } => {
            if items.is_empty() {
                out.push_str("[]");
                return;
            }
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push('\n');
                tabs(out, n + 1);
                expr_multi(out, item, n + 1);
            }
            out.push('\n');
            tabs(out, n);
            out.push(']');
        }
        Expr::Literal { lit: Lit::Dict(items), .. } => {
            if items.is_empty() {
                out.push_str("@[]");
                return;
            }
            out.push_str("@[");
            for (i, (k, v)) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push('\n');
                tabs(out, n + 1);
                let _ = write!(out, "{}: ", String::from_utf8_lossy(k));
                expr_multi(out, v, n + 1);
            }
            out.push('\n');
            tabs(out, n);
            out.push(']');
        }
        Expr::Literal { lit: Lit::Function(def), .. } => {
            let _ = write!(out, "function({})\n", def.params);
            for (i, kind) in def.slots.iter().enumerate() {
                if i > 0 {
                    out.push('\n');
                }
                tabs(out, n + 1);
                slot_decl(out, i, kind);
            }
            out.push('\n');
            for (i, stmt) in def.body.iter().enumerate() {
                if i > 0 {
                    out.push('\n');
                }
                tabs(out, n + 1);
                stmt_multi(out, stmt, n + 1);
            }
            out.push('\n');
            tabs(out, n);
            out.push_str("end");
        }
        Expr::If { condition, then, otherwise, .. } => {
            out.push_str("if ");
            expr_inline(out, condition);
            out.push_str(" then");
            block_prefixed(out, then, n + 1);
            if !otherwise.is_empty() {
                out.push('\n');
                tabs(out, n);
                out.push_str("else");
                block_prefixed(out, otherwise, n + 1);
            }
            out.push('\n');
            tabs(out, n);
            out.push_str("end");
        }
        Expr::CommandBlock { block, .. } => {
            out.push_str(block_prefix(block.kind));
            let cmds = std::iter::once(&block.head).chain(block.tail.iter());
            for (i, cmd) in cmds.enumerate() {
                if i > 0 {
                    out.push(';');
                }
                out.push('\n');
                tabs(out, n + 1);
                command_fmt(out, cmd);
            }
            out.push('\n');
            tabs(out, n);
            out.push('}');
        }
        other => expr_inline(out, other),
    }
}

fn stmt_inline(out: &mut String, stmt: &Stmt) {
    match stmt {
        Stmt::Let { slot, init } => {
            let _ = write!(out, "#{} = ", slot);
            expr_inline(out, init);
        }
        Stmt::Assign { left, right, .. } => {
            expr_inline(out, left);
            out.push_str(" = ");
            expr_inline(out, right);
        }
        Stmt::Return { expr } => {
            out.push_str("return ");
            expr_inline(out, expr);
        }
        Stmt::Break => out.push_str("break"),
        Stmt::While { condition, block } => {
            out.push_str("while ");
            expr_inline(out, condition);
            out.push_str(" do ");
            block_inline(out, block);
            out.push_str("end");
        }
        Stmt::For { slot, expr, block } => {
            let _ = write!(out, "for #{} in ", slot);
            expr_inline(out, expr);
            out.push_str(" do ");
            block_inline(out, block);
            out.push_str("end");
        }
        Stmt::Expr(e) => expr_inline(out, e),
    }
}

fn block_inline(out: &mut String, block: &[Stmt]) {
    if block.is_empty() {
        return;
    }
    out.push(' ');
    for (i, stmt) in block.iter().enumerate() {
        if i > 0 {
            out.push_str("; ");
        }
        stmt_inline(out, stmt);
    }
    out.push(' ');
}

fn expr_inline(out: &mut String, expr: &Expr) {
    match expr {
        Expr::Slot { slot, .. } => {
            let _ = write!(out, "#{}", slot);
        }
        Expr::Literal { lit, .. } => match lit {
            Lit::Nil => out.push_str("nil"),
            Lit::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
            Lit::Int(i) => {
                let _ = write!(out, "{}", i);
            }
            Lit::Float(x) => {
                let _ = write!(out, "{}", x);
            }
            Lit::Byte(b) => {
                let _ = write!(out, "'{}'", escape_char(*b));
            }
            Lit::String(s) => {
                let _ = write!(out, "\"{}\"", escape_str(s));
            }
            Lit::Array(items) => {
                if items.is_empty() {
                    out.push_str("[]");
                    return;
                }
                out.push_str("[ ");
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        out.push_str(", ");
                    }
                    expr_inline(out, item);
                }
                out.push_str(" ]");
            }
            Lit::Dict(items) => {
                if items.is_empty() {
                    out.push_str("@[]");
                    return;
                }
                out.push_str("@[ ");
                for (i, (k, v)) in items.iter().enumerate() {
                    if i > 0 {
                        out.push_str(", ");
                    }
                    let _ = write!(out, "{}: ", String::from_utf8_lossy(k));
                    expr_inline(out, v);
                }
                out.push_str(" ]");
            }
            Lit::Function(def) => {
                let _ = write!(out, "function({})", def.params);
                for (i, kind) in def.slots.iter().enumerate() {
                    if i > 0 {
                        out.push(';');
                    }
                    out.push(' ');
                    slot_decl(out, i, kind);
                }
                out.push_str("  ");
                for (i, stmt) in def.body.iter().enumerate() {
                    if i > 0 {
                        out.push_str("; ");
                    }
                    stmt_inline(out, stmt);
                }
                if !def.body.is_empty() {
                    out.push(' ');
                }
                out.push_str("end");
            }
        },
        Expr::Unary { op, operand, .. } => match op {
            UnaryOp::Minus => {
                out.push_str("(- ");
                expr_inline(out, operand);
                out.push(')');
            }
            UnaryOp::Not => {
                out.push_str("(not ");
                expr_inline(out, operand);
                out.push(')');
            }
            UnaryOp::Try => {
                out.push('(');
                expr_inline(out, operand);
                out.push_str(" ?)");
            }
        },
        Expr::Binary { left, op, right, .. } => {
            out.push('(');
            expr_inline(out, left);
            let _ = write!(out, " {} ", op.text());
            expr_inline(out, right);
            out.push(')');
        }
        Expr::If { condition, then, otherwise, .. } => {
            out.push_str("if ");
            expr_inline(out, condition);
            out.push_str(" then");
            block_inline(out, then);
            if !otherwise.is_empty() {
                out.push_str("else");
                block_inline(out, otherwise);
            }
            out.push_str("end");
        }
        Expr::Access { object, field, .. } => {
            expr_inline(out, object);
            out.push('.');
            out.push_str(&String::from_utf8_lossy(field));
        }
        Expr::Index { object, index, .. } => {
            expr_inline(out, object);
            out.push('[');
            expr_inline(out, index);
            out.push(']');
        }
        Expr::Call { function, args, .. } => {
            expr_inline(out, function);
            out.push('(');
            for (i, a) in args.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                expr_inline(out, a);
            }
            out.push(')');
        }
        Expr::CommandBlock { block, .. } => {
            out.push_str(block_prefix(block.kind));
            out.push(' ');
            let cmds = std::iter::once(&block.head).chain(block.tail.iter());
            for (i, cmd) in cmds.enumerate() {
                if i > 0 {
                    out.push_str("; ");
                }
                command_fmt(out, cmd);
            }
            out.push_str(" }");
        }
    }
}

fn command_fmt(out: &mut String, cmd: &Command) {
    let all = std::iter::once(&cmd.head).chain(cmd.tail.iter());
    for (i, basic) in all.enumerate() {
        if i > 0 {
            out.push_str(" | ");
        }
        match basic {
            BasicCommand::Command { program, arguments, redirections, abort_on_error, .. }
            | BasicCommand::Builtin { program, arguments, redirections, abort_on_error, .. } => {
                arg_fmt(out, program);
                for a in arguments {
                    out.push(' ');
                    arg_fmt(out, a);
                }
                for r in redirections {
                    out.push(' ');
                    redir_fmt(out, r);
                }
                if !abort_on_error {
                    out.push_str(" ?");
                }
            }
        }
    }
}

fn arg_fmt(out: &mut String, arg: &Argument) {
    out.push('"');
    for unit in &arg.units {
        match unit {
            ArgUnit::Literal(l) => out.push_str(&escape_str(l)),
            ArgUnit::Dollar { slot, .. } => {
                let _ = write!(out, "${{#{}}}", slot);
            }
            ArgUnit::Expansion(e) => {
                let _ = write!(out, "{}", e);
            }
        }
    }
    out.push('"');
}

fn redir_fmt(out: &mut String, r: &Redirection) {
    match r {
        Redirection::Output { source, target } => match target {
            RedirectionTarget::Fd(fd) => {
                let _ = write!(out, "{}>{}", source, fd);
            }
            RedirectionTarget::Overwrite(a) => {
                let _ = write!(out, "{}>", source);
                arg_fmt(out, a);
            }
            RedirectionTarget::Append(a) => {
                let _ = write!(out, "{}>>", source);
                arg_fmt(out, a);
            }
        },
        Redirection::Input { literal, source } => {
            out.push_str(if *literal { "<<" } else { "<" });
            arg_fmt(out, source);
        }
    }
}
