// Semantic analysis: variable resolution and static checks.

use crate::ast;
use crate::lexer::Pos;
use crate::program::*;
use std::collections::HashMap;
use std::rc::Rc;

#[derive(Clone, Debug)]
pub enum SemanticErrorKind {
    UndeclaredVariable(String),
    DuplicateVariable(String),
    SelfOutsideFunction,
    ReturnOutsideFunction,
    BreakOutsideLoop,
    TryOutsideFunction,
    InvalidAssignment,
    AsyncBuiltin,
}

#[derive(Clone, Debug)]
pub struct SemanticError {
    pub kind: SemanticErrorKind,
    pub pos: SourcePos,
}

impl std::fmt::Display for SemanticError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "Error: {} - ", self.pos)?;
        match &self.kind {
            SemanticErrorKind::UndeclaredVariable(n) => write!(f, "undeclared variable '{}'", n),
            SemanticErrorKind::DuplicateVariable(n) => write!(f, "duplicate variable '{}'", n),
            SemanticErrorKind::SelfOutsideFunction => write!(f, "self keyword outside function"),
            SemanticErrorKind::ReturnOutsideFunction => write!(f, "return statement outside function"),
            SemanticErrorKind::BreakOutsideLoop => write!(f, "break statement outside loop"),
            SemanticErrorKind::TryOutsideFunction => write!(f, "try operator outside function"),
            SemanticErrorKind::InvalidAssignment => write!(f, "invalid assignment"),
            SemanticErrorKind::AsyncBuiltin => write!(f, "use of built-in command in async context"),
        }
    }
}

type Key = Option<Vec<u8>>;

struct Frame {
    slots: Vec<SlotKind>,
    scopes: Vec<HashMap<Key, usize>>,
    captures: HashMap<usize, usize>,
    self_slot: Option<usize>,
    loops: usize,
    is_function: bool,
}

impl Frame {
    fn new(is_function: bool) -> Frame {
        Frame {
            slots: Vec::new(),
            scopes: vec![HashMap::new()],
            captures: HashMap::new(),
            self_slot: None,
            loops: 0,
            is_function,
        }
    }
}

pub struct Analyzer {
    path: Rc<str>,
    frames: Vec<Frame>,
    pub errors: Vec<SemanticError>,
}

fn sym_name(s: &ast::Symbol) -> String {
    s.display()
}

impl Analyzer {
    pub fn new(path: Rc<str>) -> Analyzer {
        Analyzer { path, frames: Vec::new(), errors: Vec::new() }
    }

    fn pos(&self, p: Pos) -> SourcePos {
        SourcePos { path: self.path.clone(), line: p.line, column: p.column }
    }

    fn error(&mut self, kind: SemanticErrorKind, p: Pos) {
        let pos = self.pos(p);
        self.errors.push(SemanticError { kind, pos });
    }

    fn frame(&mut self) -> &mut Frame {
        self.frames.last_mut().unwrap()
    }

    fn declare(&mut self, sym: &ast::Symbol) -> usize {
        let key: Key = sym.name.clone();
        let exists = self.frame().scopes.last().unwrap().contains_key(&key);
        if exists {
            self.error(SemanticErrorKind::DuplicateVariable(sym_name(sym)), sym.pos);
        }
        let frame = self.frame();
        let slot = frame.slots.len();
        frame.slots.push(SlotKind::Regular);
        frame.scopes.last_mut().unwrap().insert(key, slot);
        slot
    }

    fn resolve_in(&mut self, depth: usize, key: &Key) -> Option<usize> {
        {
            let frame = &self.frames[depth];
            for scope in frame.scopes.iter().rev() {
                if let Some(slot) = scope.get(key) {
                    return Some(*slot);
                }
            }
        }
        if depth == 0 {
            return None;
        }
        let parent_slot = self.resolve_in(depth - 1, key)?;
        let frame = &mut self.frames[depth];
        if let Some(slot) = frame.captures.get(&parent_slot) {
            return Some(*slot);
        }
        let slot = frame.slots.len();
        frame.slots.push(SlotKind::Closed(parent_slot));
        frame.captures.insert(parent_slot, slot);
        Some(slot)
    }

    fn resolve(&mut self, sym: &ast::Symbol) -> Option<usize> {
        let depth = self.frames.len() - 1;
        let key = sym.name.clone();
        match self.resolve_in(depth, &key) {
            Some(s) => Some(s),
            None => {
                self.error(SemanticErrorKind::UndeclaredVariable(sym_name(sym)), sym.pos);
                None
            }
        }
    }

    pub fn analyze_root(&mut self, block: &ast::Block) -> Program {
        let mut frame = Frame::new(false);
        // slot 0: std
        frame.slots.push(SlotKind::Regular);
        frame.scopes[0].insert(Some(b"std".to_vec()), 0);
        self.frames.push(frame);
        let body = self.block_no_scope(block);
        let frame = self.frames.pop().unwrap();
        Program { root_slots: frame.slots, body }
    }

    fn block_no_scope(&mut self, block: &ast::Block) -> Vec<Stmt> {
        block.iter().filter_map(|s| self.stmt(s)).collect()
    }

    fn block_scoped(&mut self, block: &ast::Block) -> Vec<Stmt> {
        self.frame().scopes.push(HashMap::new());
        let r = self.block_no_scope(block);
        self.frame().scopes.pop();
        r
    }

    fn dummy(&self) -> Expr {
        Expr::Literal { lit: Lit::Nil, pos: self.pos(Pos::default()) }
    }

    fn stmt(&mut self, stmt: &ast::Statement) -> Option<Stmt> {
        match stmt {
            ast::Statement::IllFormed => None,
            ast::Statement::Let { identifier, init, .. } => {
                let slot = self.declare(identifier);
                let init = self.expr_or_dummy(init);
                Some(Stmt::Let { slot, init })
            }
            ast::Statement::Assign { left, right, pos } => {
                let left_ir = match left {
                    ast::Expr::Identifier(_) | ast::Expr::Access { .. } | ast::Expr::Index { .. } => {
                        self.expr_or_dummy(left)
                    }
                    ast::Expr::IllFormed => self.dummy(),
                    _ => {
                        self.error(SemanticErrorKind::InvalidAssignment, *pos);
                        self.dummy()
                    }
                };
                let right_ir = self.expr_or_dummy(right);
                Some(Stmt::Assign { left: left_ir, right: right_ir, pos: self.pos(*pos) })
            }
            ast::Statement::Return { expr, pos } => {
                if !self.frame().is_function {
                    self.error(SemanticErrorKind::ReturnOutsideFunction, *pos);
                }
                let expr = self.expr_or_dummy(expr);
                Some(Stmt::Return { expr })
            }
            ast::Statement::Break { pos } => {
                if self.frame().loops == 0 {
                    self.error(SemanticErrorKind::BreakOutsideLoop, *pos);
                }
                Some(Stmt::Break)
            }
            ast::Statement::While { condition, block, .. } => {
                let condition = self.expr_or_dummy(condition);
                self.frame().loops += 1;
                let block = self.block_scoped(block);
                self.frame().loops -= 1;
                Some(Stmt::While { condition, block })
            }
            ast::Statement::For { identifier, expr, block, .. } => {
                let expr = self.expr_or_dummy(expr);
                self.frame().scopes.push(HashMap::new());
                let slot = self.declare(identifier);
                self.frame().loops += 1;
                let block = self.block_no_scope(block);
                self.frame().loops -= 1;
                self.frame().scopes.pop();
                Some(Stmt::For { slot, expr, block })
            }
            ast::Statement::Expr(e) => {
                let e = self.expr_or_dummy(e);
                Some(Stmt::Expr(e))
            }
        }
    }

    fn expr_or_dummy(&mut self, expr: &ast::Expr) -> Expr {
        match self.expr(expr) {
            Ok(e) => e,
            Err(()) => self.dummy(),
        }
    }

    fn expr(&mut self, expr: &ast::Expr) -> Result<Expr, ()> {
        match expr {
            ast::Expr::IllFormed => Err(()),
            ast::Expr::Self_ { pos } => {
                if !self.frame().is_function {
                    self.error(SemanticErrorKind::SelfOutsideFunction, *pos);
                    return Err(());
                }
                let frame = self.frame();
                let slot = match frame.self_slot {
                    Some(s) => s,
                    None => {
                        let s = frame.slots.len();
                        frame.slots.push(SlotKind::SelfValue);
                        frame.self_slot = Some(s);
                        s
                    }
                };
                Ok(Expr::Slot { slot, pos: self.pos(*pos) })
            }
            ast::Expr::Identifier(sym) => match self.resolve(sym) {
                Some(slot) => Ok(Expr::Slot { slot, pos: self.pos(sym.pos) }),
                None => Err(()),
            },
            ast::Expr::Literal { lit, pos } => {
                let lit = match lit {
                    ast::Literal::Nil => Lit::Nil,
                    ast::Literal::Bool(b) => Lit::Bool(*b),
                    ast::Literal::Int(i) => Lit::Int(*i),
                    ast::Literal::Float(x) => Lit::Float(*x),
                    ast::Literal::Byte(b) => Lit::Byte(*b),
                    ast::Literal::String(s) => Lit::String(s.clone().into()),
                    ast::Literal::Array(items) => {
                        let items: Vec<Expr> = items.iter().map(|e| self.expr_or_dummy(e)).collect();
                        Lit::Array(items)
                    }
                    ast::Literal::Dict(items) => {
                        let mut out = Vec::new();
                        for (k, v) in items {
                            let v = self.expr_or_dummy(v);
                            let key: Rc<[u8]> = match &k.name {
                                Some(n) => n.clone().into(),
                                None => b"***ill-formed***".to_vec().into(),
                            };
                            out.push((key, v));
                        }
                        Lit::Dict(out)
                    }
                    ast::Literal::Function { params, body } => {
                        let mut frame = Frame::new(true);
                        frame.scopes = vec![HashMap::new()];
                        self.frames.push(frame);
                        for p in params {
                            self.declare(p);
                        }
                        let body = self.block_no_scope(body);
                        let frame = self.frames.pop().unwrap();
                        Lit::Function(Rc::new(FunctionDef {
                            params: params.len(),
                            slots: frame.slots,
                            body,
                            pos: self.pos(*pos),
                        }))
                    }
                };
                Ok(Expr::Literal { lit, pos: self.pos(*pos) })
            }
            ast::Expr::Unary { op, operand, pos } => {
                if *op == ast::UnaryOp::Try {
                    let operand = self.expr(operand)?;
                    if !self.frame().is_function {
                        self.error(SemanticErrorKind::TryOutsideFunction, *pos);
                        return Err(());
                    }
                    return Ok(Expr::Unary { op: *op, operand: Box::new(operand), pos: self.pos(*pos) });
                }
                let operand = self.expr(operand);
                Ok(Expr::Unary { op: *op, operand: Box::new(operand?), pos: self.pos(*pos) })
            }
            ast::Expr::Binary { left, op, right, pos } => {
                let l = self.expr(left);
                let r = self.expr(right);
                Ok(Expr::Binary { left: Box::new(l?), op: *op, right: Box::new(r?), pos: self.pos(*pos) })
            }
            ast::Expr::If { condition, then, otherwise, pos } => {
                let c = self.expr(condition);
                let t = self.block_scoped(then);
                let o = self.block_scoped(otherwise);
                Ok(Expr::If { condition: Box::new(c?), then: t, otherwise: o, pos: self.pos(*pos) })
            }
            ast::Expr::Access { object, field, pos } => {
                let o = self.expr(object)?;
                let name: Rc<[u8]> = field.name.clone().unwrap_or_default().into();
                Ok(Expr::Access { object: Box::new(o), field: name, field_pos: self.pos(field.pos), pos: self.pos(*pos) })
            }
            ast::Expr::Index { object, index, pos } => {
                let o = self.expr(object);
                let i = self.expr(index);
                Ok(Expr::Index { object: Box::new(o?), index: Box::new(i?), pos: self.pos(*pos) })
            }
            ast::Expr::Call { function, args, pos } => {
                let f = self.expr(function);
                let args: Vec<Result<Expr, ()>> = args.iter().map(|a| self.expr(a)).collect();
                let f = f?;
                let mut out = Vec::new();
                for a in args {
                    out.push(a?);
                }
                Ok(Expr::Call { function: Box::new(f), args: out, pos: self.pos(*pos) })
            }
            ast::Expr::CommandBlock { block, pos } => {
                let b = self.command_block(block)?;
                Ok(Expr::CommandBlock { block: Rc::new(b), pos: self.pos(*pos) })
            }
        }
    }

    fn command_block(&mut self, block: &ast::CommandBlock) -> Result<CommandBlock, ()> {
        let is_async = block.kind != ast::BlockKind::Synchronous;
        let mut ok = true;
        let head = self.command(&block.head, is_async);
        let tail: Vec<_> = block.tail.iter().map(|c| self.command(c, is_async)).collect();
        let head = match head {
            Ok(h) => Some(h),
            Err(()) => {
                ok = false;
                None
            }
        };
        let mut t = Vec::new();
        for c in tail {
            match c {
                Ok(c) => t.push(c),
                Err(()) => ok = false,
            }
        }
        if !ok {
            return Err(());
        }
        Ok(CommandBlock { kind: block.kind, head: head.unwrap(), tail: t })
    }

    fn command(&mut self, cmd: &ast::Command, is_async: bool) -> Result<Command, ()> {
        let pipeline = !cmd.tail.is_empty();
        let head = self.basic(&cmd.head, is_async || pipeline);
        let tail: Vec<_> = cmd.tail.iter().map(|c| self.basic(c, true)).collect();
        let head = head?;
        let mut t = Vec::new();
        for c in tail {
            t.push(c?);
        }
        Ok(Command { head, tail: t })
    }

    fn argument(&mut self, arg: &ast::Argument) -> Result<Argument, ()> {
        let mut units = Vec::new();
        let mut ok = true;
        for u in &arg.units {
            match u {
                ast::ArgUnit::Literal(l) => units.push(ArgUnit::Literal(l.clone().into())),
                ast::ArgUnit::Expansion(e) => units.push(ArgUnit::Expansion(*e)),
                ast::ArgUnit::Dollar(sym) => match self.resolve(sym) {
                    Some(slot) => units.push(ArgUnit::Dollar { slot, pos: self.pos(sym.pos) }),
                    None => ok = false,
                },
            }
        }
        if ok {
            Ok(Argument { units, pos: self.pos(arg.pos) })
        } else {
            Err(())
        }
    }

    fn basic(&mut self, basic: &ast::BasicCommand, is_async: bool) -> Result<BasicCommand, ()> {
        match basic {
            ast::BasicCommand::IllFormed => Err(()),
            ast::BasicCommand::Command { program, arguments, redirections, abort_on_error, pos } => {
                let builtin = builtin_of(program);
                if builtin.is_some() && is_async {
                    self.error(SemanticErrorKind::AsyncBuiltin, *pos);
                }
                let mut ok = true;
                let prog = self.argument(program);
                let args: Vec<_> = arguments.iter().map(|a| self.argument(a)).collect();
                let mut redirs = Vec::new();
                for r in redirections {
                    match r {
                        ast::Redirection::IllFormed => ok = false,
                        ast::Redirection::Output { source, target } => {
                            let target = match target {
                                ast::RedirectionTarget::Fd(fd) => Ok(RedirectionTarget::Fd(*fd)),
                                ast::RedirectionTarget::Overwrite(a) => self.argument(a).map(RedirectionTarget::Overwrite),
                                ast::RedirectionTarget::Append(a) => self.argument(a).map(RedirectionTarget::Append),
                            };
                            match target {
                                Ok(t) => redirs.push(Redirection::Output { source: *source, target: t }),
                                Err(()) => ok = false,
                            }
                        }
                        ast::Redirection::Input { literal, source } => match self.argument(source) {
                            Ok(a) => redirs.push(Redirection::Input { literal: *literal, source: a }),
                            Err(()) => ok = false,
                        },
                    }
                }
                let prog = prog?;
                let mut a = Vec::new();
                for x in args {
                    a.push(x?);
                }
                if !ok {
                    return Err(());
                }
                let pos = self.pos(*pos);
                Ok(match builtin {
                    Some(b) => BasicCommand::Builtin {
                        builtin: b,
                        program: prog,
                        arguments: a,
                        abort_on_error: *abort_on_error,
                        pos,
                        redirections: redirs,
                    },
                    None => BasicCommand::Command {
                        program: prog,
                        arguments: a,
                        redirections: redirs,
                        abort_on_error: *abort_on_error,
                        pos,
                    },
                })
            }
        }
    }
}

fn builtin_of(program: &ast::Argument) -> Option<Builtin> {
    if program.units.len() != 1 {
        return None;
    }
    match &program.units[0] {
        ast::ArgUnit::Literal(l) => match l.as_slice() {
            b"alias" => Some(Builtin::Alias),
            b"cd" => Some(Builtin::Cd),
            b"exec" => Some(Builtin::Exec),
            b"exec0" => Some(Builtin::Exec0),
            b"spawn0" => Some(Builtin::Spawn0),
            _ => None,
        },
        _ => None,
    }
}
