// Semantic analysis: variable resolution and static checks.

use crate::ast;
use crate::lexer::Pos;
use crate::program::*;
use std::collections::HashMap;
use std::rc::Rc;

#[derive(Clone, Debug)]
pub enum SemanticErrorKind {
    UndeclaredVariable(String),
    DuplicateVariable(String),
    SelfOutsideFunction,
    ReturnOutsideFunction,
    BreakOutsideLoop,
    TryOutsideFunction,
    InvalidAssignment,
    AsyncBuiltin,
}

#[derive(Clone, Debug)]
pub struct SemanticError {
    pub kind: SemanticErrorKind,
    pub pos: SourcePos,
}

impl std::fmt::Display for SemanticError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "Error: {} - ", self.pos)?;
        match &self.kind {
            SemanticErrorKind::UndeclaredVariable(n) => write!(f, "undeclared variable '{}'", n),
            SemanticErrorKind::DuplicateVariable(n) => write!(f, "duplicate variable '{}'", n),
            SemanticErrorKind::SelfOutsideFunction => write!(f, "self keyword outside function"),
            SemanticErrorKind::ReturnOutsideFunction => write!(f, "return statement outside function"),
            SemanticErrorKind::BreakOutsideLoop => write!(f, "break statement outside loop"),
            SemanticErrorKind::TryOutsideFunction => write!(f, "try operator outside function"),
            SemanticErrorKind::InvalidAssignment => write!(f, "invalid assignment"),
            SemanticErrorKind::AsyncBuiltin => write!(f, "use of built-in command in async context"),
        }
    }
}

type Key = Option<Vec<u8>>;

struct Frame {
    slots: Vec<SlotKind>,
    scopes: Vec<HashMap<Key, usize>>,
    captures: HashMap<usize, usize>,
    self_slot: Option<usize>,
    loops: usize,
    is_function: bool,
}

impl Frame {
    fn new(is_function: bool) -> Frame {
        Frame {
            slots: Vec::new(),
            scopes: vec![HashMap::new()],
            captures: HashMap::new(),
            self_slot: None,
            loops: 0,
            is_function,
        }
    }
}

pub struct Analyzer {
    path: Rc<str>,
    frames: Vec<Frame>,
    pub errors: Vec<SemanticError>,
}

fn sym_name(s: &ast::Symbol) -> String {
    s.display()
}

impl Analyzer {
    pub fn new(path: Rc<str>) -> Analyzer {
        Analyzer { path, frames: Vec::new(), errors: Vec::new() }
    }

    fn pos(&self, p: Pos) -> SourcePos {
        SourcePos { path: self.path.clone(), line: p.line, column: p.column }
    }

    fn error(&mut self, kind: SemanticErrorKind, p: Pos) {
        let pos = self.pos(p);
        self.errors.push(SemanticError { kind, pos });
    }

    fn frame(&mut self) -> &mut Frame {
        self.frames.last_mut().unwrap()
    }

    fn declare(&mut self, sym: &ast::Symbol) -> usize {
        let key: Key = sym.name.clone();
        let exists = self.frame().scopes.last().unwrap().contains_key(&key);
        if exists {
            self.error(SemanticErrorKind::DuplicateVariable(sym_name(sym)), sym.pos);
        }
        let frame = self.frame();
        let slot = frame.slots.len();
        frame.slots.push(SlotKind::Regular);
        frame.scopes.last_mut().unwrap().insert(key, slot);
        slot
    }

    fn resolve_in(&mut self, depth: usize, key: &Key) -> Option<usize> {
        {
            let frame = &self.frames[depth];
            for scope in frame.scopes.iter().rev() {
                if let Some(slot) = scope.get(key) {
                    return Some(*slot);
                }
            }
        }
        if depth == 0 {
            return None;
        }
        let parent_slot = self.resolve_in(depth - 1, key)?;
        let frame = &mut self.frames[depth];
        if let Some(slot) = frame.captures.get(&parent_slot) {
            return Some(*slot);
        }
        let slot = frame.slots.len();
        frame.slots.push(SlotKind::Closed(parent_slot));
        frame.captures.insert(parent_slot, slot);
        Some(slot)
    }

    fn resolve(&mut self, sym: &ast::Symbol) -> Option<usize> {
        let depth = self.frames.len() - 1;
        let key = sym.name.clone();
        match self.resolve_in(depth, &key) {
            Some(s) => Some(s),
            None => {
                self.error(SemanticErrorKind::UndeclaredVariable(sym_name(sym)), sym.pos);
                None
            }
        }
    }

    pub fn analyze_root(&mut self, block: &ast::Block) -> Program {
        let mut frame = Frame::new(false);
        // slot 0: std
        frame.slots.push(SlotKind::Regular);
        frame.scopes[0].insert(Some(b"std".to_vec()), 0);
        self.frames.push(frame);
        let body = self.block_no_scope(block);
        let frame = self.frames.pop().unwrap();
        Program { root_slots: frame.slots, body }
    }

    fn block_no_scope(&mut self, block: &ast::Block) -> Vec<Stmt> {
        block.iter().filter_map(|s| self.stmt(s)).collect()
    }

    fn block_scoped(&mut self, block: &ast::Block) -> Vec<Stmt> {
        self.frame().scopes.push(HashMap::new());
        let r = self.block_no_scope(block);
        self.frame().scopes.pop();
        r
    }

    fn dummy(&self) -> Expr {
        Expr::Literal { lit: Lit::Nil, pos: self.pos(Pos::default()) }
    }

    fn stmt(&mut self, stmt: &ast::Statement) -> Option<Stmt> {
        match stmt {
            ast::Statement::IllFormed => None,
            ast::Statement::Let { identifier, init, .. } => {
                let slot = self.declare(identifier);
                let init = self.expr_or_dummy(init);
                Some(Stmt::Let { slot, init })
            }
            ast::Statement::Assign { left, right, pos } => {
                let left_ir = match left {
                    ast::Expr::Identifier(_) | ast::Expr::Access { .. } | ast::Expr::Index { .. } => {
                        self.expr_or_dummy(left)
                    }
                    ast::Expr::IllFormed => self.dummy(),
                    _ => {
                        self.error(SemanticErrorKind::InvalidAssignment, *pos);
                        self.dummy()
                    }
                };
                let right_ir = self.expr_or_dummy(right);
                Some(Stmt::Assign { left: left_ir, right: right_ir, pos: self.pos(*pos) })
            }
            ast::Statement::Return { expr, pos } => {
                if !self.frame().is_function {
                    self.error(SemanticErrorKind::ReturnOutsideFunction, *pos);
                }
                let expr = self.expr_or_dummy(expr);
                Some(Stmt::Return { expr })
            }
            ast::Statement::Break { pos } => {
                if self.frame().loops == 0 {
                    self.error(SemanticErrorKind::BreakOutsideLoop, *pos);
                }
                Some(Stmt::Break)
            }
            ast::Statement::While { condition, block, .. } => {
                let condition = self.expr_or_dummy(condition);
                self.frame().loops += 1;
                let block = self.block_scoped(block);
                self.frame().loops -= 1;
                Some(Stmt::While { condition, block })
            }
            ast::Statement::For { identifier, expr, block, .. } => {
                let expr = self.expr_or_dummy(expr);
                self.frame().scopes.push(HashMap::new());
                let slot = self.declare(identifier);
                self.frame().loops += 1;
                let block = self.block_no_scope(block);
                self.frame().loops -= 1;
                self.frame().scopes.pop();
                Some(Stmt::For { slot, expr, block })
            }
            ast::Statement::Expr(e) => {
                let e = self.expr_or_dummy(e);
                Some(Stmt::Expr(e))
            }
        }
    }

    fn expr_or_dummy(&mut self, expr: &ast::Expr) -> Expr {
        match self.expr(expr) {
            Ok(e) => e,
            Err(()) => self.dummy(),
        }
    }

    fn expr(&mut self, expr: &ast::Expr) -> Result<Expr, ()> {
        match expr {
            ast::Expr::IllFormed => Err(()),
            ast::Expr::Self_ { pos } => {
                if !self.frame().is_function {
                    self.error(SemanticErrorKind::SelfOutsideFunction, *pos);
                    return Err(());
                }
                let frame = self.frame();
                let slot = match frame.self_slot {
                    Some(s) => s,
                    None => {
                        let s = frame.slots.len();
                        frame.slots.push(SlotKind::SelfValue);
                        frame.self_slot = Some(s);
                        s
                    }
                };
                Ok(Expr::Slot { slot, pos: self.pos(*pos) })
            }
            ast::Expr::Identifier(sym) => match self.resolve(sym) {
                Some(slot) => Ok(Expr::Slot { slot, pos: self.pos(sym.pos) }),
                None => Err(()),
