                    ast::Literal::Nil => Lit::Nil,
                    ast::Literal::Bool(b) => Lit::Bool(*b),
                    ast::Literal::Int(i) => Lit::Int(*i),
                    ast::Literal::Float(x) => Lit::Float(*x),
                    ast::Literal::Byte(b) => Lit::Byte(*b),
                    ast::Literal::String(s) => Lit::String(s.clone().into()),
                    ast::Literal::Array(items) => {
                        let items: Vec<Expr> = items.iter().map(|e| self.expr_or_dummy(e)).collect();
                        Lit::Array(items)
                    }
                    ast::Literal::Dict(items) => {
                        let mut out = Vec::new();
                        for (k, v) in items {
                            let v = self.expr_or_dummy(v);
                            let key: Rc<[u8]> = match &k.name {
                                Some(n) => n.clone().into(),
                                None => b"***ill-formed***".to_vec().into(),
                            };
                            out.push((key, v));
                        }
                        Lit::Dict(out)
                    }
                    ast::Literal::Function { params, body } => {
                        let mut frame = Frame::new(true);
                        frame.scopes = vec![HashMap::new()];
                        self.frames.push(frame);
                        for p in params {
                            self.declare(p);
                        }
                        let body = self.block_no_scope(body);
                        let frame = self.frames.pop().unwrap();
                        Lit::Function(Rc::new(FunctionDef {
                            params: params.len(),
                            slots: frame.slots,
                            body,
                            pos: self.pos(*pos),
                        }))
                    }
                };
                Ok(Expr::Literal { lit, pos: self.pos(*pos) })
            }
            ast::Expr::Unary { op, operand, pos } => {
                if *op == ast::UnaryOp::Try {
                    let operand = self.expr(operand)?;
                    if !self.frame().is_function {
                        self.error(SemanticErrorKind::TryOutsideFunction, *pos);
                        return Err(());
                    }
                    return Ok(Expr::Unary { op: *op, operand: Box::new(operand), pos: self.pos(*pos) });
                }
                let operand = self.expr(operand);
                Ok(Expr::Unary { op: *op, operand: Box::new(operand?), pos: self.pos(*pos) })
            }
            ast::Expr::Binary { left, op, right, pos } => {
                let l = self.expr(left);
                let r = self.expr(right);
                Ok(Expr::Binary { left: Box::new(l?), op: *op, right: Box::new(r?), pos: self.pos(*pos) })
            }
            ast::Expr::If { condition, then, otherwise, pos } => {
                let c = self.expr(condition);
                let t = self.block_scoped(then);
                let o = self.block_scoped(otherwise);
                Ok(Expr::If { condition: Box::new(c?), then: t, otherwise: o, pos: self.pos(*pos) })
            }
            ast::Expr::Access { object, field, pos } => {
                let o = self.expr(object)?;
                let name: Rc<[u8]> = field.name.clone().unwrap_or_default().into();
                Ok(Expr::Access { object: Box::new(o), field: name, field_pos: self.pos(field.pos), pos: self.pos(*pos) })
            }
            ast::Expr::Index { object, index, pos } => {
                let o = self.expr(object);
                let i = self.expr(index);
                Ok(Expr::Index { object: Box::new(o?), index: Box::new(i?), pos: self.pos(*pos) })
            }
            ast::Expr::Call { function, args, pos } => {
                let f = self.expr(function);
                let args: Vec<Result<Expr, ()>> = args.iter().map(|a| self.expr(a)).collect();
                let f = f?;
                let mut out = Vec::new();
                for a in args {
                    out.push(a?);
                }
                Ok(Expr::Call { function: Box::new(f), args: out, pos: self.pos(*pos) })
            }
            ast::Expr::CommandBlock { block, pos } => {
                let b = self.command_block(block)?;
                Ok(Expr::CommandBlock { block: Rc::new(b), pos: self.pos(*pos) })
            }
        }
    }

    fn command_block(&mut self, block: &ast::CommandBlock) -> Result<CommandBlock, ()> {
        let is_async = block.kind != ast::BlockKind::Synchronous;
        let mut ok = true;
        let head = self.command(&block.head, is_async);
        let tail: Vec<_> = block.tail.iter().map(|c| self.command(c, is_async)).collect();
        let head = match head {
            Ok(h) => Some(h),
            Err(()) => {
                ok = false;
                None
            }
        };
        let mut t = Vec::new();
        for c in tail {
            match c {
                Ok(c) => t.push(c),
                Err(()) => ok = false,
            }
        }
        if !ok {
            return Err(());
        }
        Ok(CommandBlock { kind: block.kind, head: head.unwrap(), tail: t })
    }

    fn command(&mut self, cmd: &ast::Command, is_async: bool) -> Result<Command, ()> {
        let pipeline = !cmd.tail.is_empty();
        let head = self.basic(&cmd.head, is_async || pipeline);
        let tail: Vec<_> = cmd.tail.iter().map(|c| self.basic(c, true)).collect();
        let head = head?;
        let mut t = Vec::new();
        for c in tail {
            t.push(c?);
        }
        Ok(Command { head, tail: t })
    }

    fn argument(&mut self, arg: &ast::Argument) -> Result<Argument, ()> {
        let mut units = Vec::new();
        let mut ok = true;
        for u in &arg.units {
            match u {
                ast::ArgUnit::Literal(l) => units.push(ArgUnit::Literal(l.clone().into())),
                ast::ArgUnit::Expansion(e) => units.push(ArgUnit::Expansion(*e)),
                ast::ArgUnit::Dollar(sym) => match self.resolve(sym) {
                    Some(slot) => units.push(ArgUnit::Dollar { slot, pos: self.pos(sym.pos) }),
                    None => ok = false,
                },
            }
        }
        if ok {
            Ok(Argument { units, pos: self.pos(arg.pos) })
        } else {
            Err(())
        }
    }

    fn basic(&mut self, basic: &ast::BasicCommand, is_async: bool) -> Result<BasicCommand, ()> {
        match basic {
            ast::BasicCommand::IllFormed => Err(()),
            ast::BasicCommand::Command { program, arguments, redirections, abort_on_error, pos } => {
                let builtin = builtin_of(program);
                if builtin.is_some() && is_async {
                    self.error(SemanticErrorKind::AsyncBuiltin, *pos);
                }
                let mut ok = true;
                let prog = self.argument(program);
                let args: Vec<_> = arguments.iter().map(|a| self.argument(a)).collect();
                let mut redirs = Vec::new();
                for r in redirections {
                    match r {
                        ast::Redirection::IllFormed => ok = false,
                        ast::Redirection::Output { source, target } => {
                            let target = match target {
                                ast::RedirectionTarget::Fd(fd) => Ok(RedirectionTarget::Fd(*fd)),
                                ast::RedirectionTarget::Overwrite(a) => self.argument(a).map(RedirectionTarget::Overwrite),
                                ast::RedirectionTarget::Append(a) => self.argument(a).map(RedirectionTarget::Append),
                            };
                            match target {
                                Ok(t) => redirs.push(Redirection::Output { source: *source, target: t }),
                                Err(()) => ok = false,
                            }
                        }
                        ast::Redirection::Input { literal, source } => match self.argument(source) {
                            Ok(a) => redirs.push(Redirection::Input { literal: *literal, source: a }),
                            Err(()) => ok = false,
                        },
                    }
                }
                let prog = prog?;
                let mut a = Vec::new();
                for x in args {
                    a.push(x?);
                }
                if !ok {
                    return Err(());
                }
                let pos = self.pos(*pos);
                Ok(match builtin {
                    Some(b) => BasicCommand::Builtin {
                        builtin: b,
                        program: prog,
                        arguments: a,
                        abort_on_error: *abort_on_error,
                        pos,
                        redirections: redirs,
                    },
                    None => BasicCommand::Command {
                        program: prog,
                        arguments: a,
                        redirections: redirs,
                        abort_on_error: *abort_on_error,
                        pos,
                    },
                })
            }
        }
    }
}

fn builtin_of(program: &ast::Argument) -> Option<Builtin> {
    if program.units.len() != 1 {
        return None;
    }
    match &program.units[0] {
        ast::ArgUnit::Literal(l) => match l.as_slice() {
            b"alias" => Some(Builtin::Alias),
            b"cd" => Some(Builtin::Cd),
            b"exec" => Some(Builtin::Exec),
            b"exec0" => Some(Builtin::Exec0),
            b"spawn0" => Some(Builtin::Spawn0),
            _ => None,
        },
        _ => None,
    }
}
