pub fn float_cmp(a: f64, b: f64) -> Ordering {
    match a.partial_cmp(&b) {
        Some(o) => o,
        None => {
            if a.is_nan() {
                Ordering::Less
            } else {
                Ordering::Greater
            }
        }
    }
}

pub fn value_cmp(a: &Value, b: &Value) -> Ordering {
    let ra = a.type_rank();
    let rb = b.type_rank();
    if ra != rb {
        return ra.cmp(&rb);
    }
    match (a, b) {
        (Value::Nil, Value::Nil) => Ordering::Equal,
        (Value::Bool(x), Value::Bool(y)) => x.cmp(y),
        (Value::Byte(x), Value::Byte(y)) => x.cmp(y),
        (Value::Int(x), Value::Int(y)) => x.cmp(y),
        (Value::Float(x), Value::Float(y)) => float_cmp(*x, *y),
        (Value::String(x), Value::String(y)) => x.as_ref().cmp(y.as_ref()),
        (Value::Array(x), Value::Array(y)) => {
            if Rc::ptr_eq(x, y) {
                return Ordering::Equal;
            }
            let x = x.borrow();
            let y = y.borrow();
            for (p, q) in x.iter().zip(y.iter()) {
                let o = value_cmp(p, q);
                if o != Ordering::Equal {
                    return o;
                }
            }
            x.len().cmp(&y.len())
        }
        (Value::Dict(x), Value::Dict(y)) => {
            if Rc::ptr_eq(x, y) {
                return Ordering::Equal;
            }
            let mut xe: Vec<(Value, Value)> = x.borrow().entries.clone();
            let mut ye: Vec<(Value, Value)> = y.borrow().entries.clone();
            xe.sort_by(|a, b| value_cmp(&a.0, &b.0).then_with(|| value_cmp(&a.1, &b.1)));
            ye.sort_by(|a, b| value_cmp(&a.0, &b.0).then_with(|| value_cmp(&a.1, &b.1)));
            for (p, q) in xe.iter().zip(ye.iter()) {
                let o = value_cmp(&p.0, &q.0).then_with(|| value_cmp(&p.1, &q.1));
                if o != Ordering::Equal {
                    return o;
                }
            }
            xe.len().cmp(&ye.len())
        }
        (Value::Function(x), Value::Function(y)) => match (x, y) {
            (Function::Hush(_), Function::Rust(_)) => Ordering::Less,
            (Function::Rust(_), Function::Hush(_)) => Ordering::Greater,
            _ => x.addr().cmp(&y.addr()),
        },
        (Value::Error(x), Value::Error(y)) => x
            .description
            .as_ref()
            .cmp(y.description.as_ref())
            .then_with(|| value_cmp(&x.context, &y.context)),
        _ => Ordering::Equal,
    }
}

impl PartialEq for Value {
    fn eq(&self, other: &Value) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(x), Value::Bool(y)) => x == y,
            (Value::Int(x), Value::Int(y)) => x == y,
            (Value::Float(x), Value::Float(y)) => x == y,
            (Value::Byte(x), Value::Byte(y)) => x == y,
            (Value::String(x), Value::String(y)) => x == y,
            (Value::Array(x), Value::Array(y)) => {
                if Rc::ptr_eq(x, y) {
                    return true;
                }
                let x = x.borrow();
                let y = y.borrow();
                x.len() == y.len() && x.iter().zip(y.iter()).all(|(p, q)| p == q)
            }
            (Value::Dict(x), Value::Dict(y)) => {
                if Rc::ptr_eq(x, y) {
                    return true;
                }
                let x = x.borrow();
                let y = y.borrow();
                if x.len() != y.len() {
                    return false;
                }
                x.entries.iter().all(|(k, v)| match y.get(k) {
                    Some(w) => &w == v,
                    None => false,
                })
            }
            (Value::Function(x), Value::Function(y)) => x.ptr_eq(y),
            (Value::Error(x), Value::Error(y)) => x.description == y.description && x.context == y.context,
            _ => false,
        }
    }
}

impl Eq for Value {}

impl Hash for Value {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.type_rank().hash(state);
        match self {
            Value::Nil => {}
            Value::Bool(b) => b.hash(state),
            Value::Int(i) => i.hash(state),
            Value::Float(x) => {
                if *x == 0.0 {
                    0u64.hash(state)
                } else {
                    x.to_bits().hash(state)
                }
            }
            Value::Byte(b) => b.hash(state),
            Value::String(s) => s.hash(state),
            Value::Array(a) => {
                for v in a.borrow().iter() {
                    v.hash(state);
                }
            }
            Value::Dict(d) => {
                d.borrow().len().hash(state);
            }
            Value::Function(f) => f.addr().hash(state),
            Value::Error(e) => e.description.hash(state),
        }
    }
}

pub fn pos_string(pos: &SourcePos) -> String {
    format!("{}", pos)
}
