// Interpreter.

use crate::ast::{BinaryOp, UnaryOp};
use crate::program::*;
use crate::value::*;
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

pub struct Panic {
    pub message: String,
    pub pos: SourcePos,
}

impl std::fmt::Display for Panic {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "Panic in {}: {}", self.pos, self.message)
    }
}

pub enum Control {
    Return(Value),
    Break,
    Panic(Panic),
}

pub type Exec<T> = Result<T, Control>;

pub fn panic<T>(pos: &SourcePos, message: String) -> Exec<T> {
    Err(Control::Panic(Panic { message, pos: pos.clone() }))
}

pub fn type_error<T>(pos: &SourcePos, value: &Value, expected: &str) -> Exec<T> {
    panic(pos, format!("value ({}) has unexpected type, expected {}", value.display_nested(), expected))
}

pub fn index_oob<T>(pos: &SourcePos, index: &Value) -> Exec<T> {
    panic(pos, format!("index ({}) out of bounds", index.display_nested()))
}

pub struct Runtime {
    pub std: Value,
    pub args: Vec<Vec<u8>>,
    pub modules: HashMap<std::path::PathBuf, Value>,
    pub rng: RefCell<Option<rand_chacha::ChaCha8Rng>>,
}

fn new_frame(slots: usize) -> Vec<Cell> {
    (0..slots).map(|_| Rc::new(RefCell::new(Value::Nil))).collect()
}

impl Runtime {
    pub fn new(args: Vec<Vec<u8>>) -> Runtime {
        let std = crate::stdlib::make_std();
        Runtime { std, args, modules: HashMap::new(), rng: RefCell::new(None) }
    }

    /// Run a root program; returns the value of the last statement.
    pub fn run_root(&mut self, program: &Program) -> Result<Value, Panic> {
        let frame = new_frame(program.root_slots.len());
        *frame[0].borrow_mut() = self.std.clone();
        match self.block(&program.body, &frame) {
            Ok(v) => Ok(v),
            Err(Control::Panic(p)) => Err(p),
            Err(Control::Return(v)) => Ok(v),
            Err(Control::Break) => Ok(Value::Nil),
        }
    }

    pub fn block(&mut self, block: &[Stmt], frame: &[Cell]) -> Exec<Value> {
        let mut last = Value::Nil;
        for stmt in block {
            last = self.stmt(stmt, frame)?;
        }
        Ok(last)
    }

    fn stmt(&mut self, stmt: &Stmt, frame: &[Cell]) -> Exec<Value> {
        match stmt {
            Stmt::Let { slot, init } => {
                let v = self.expr(init, frame)?;
                *frame[*slot].borrow_mut() = v;
                Ok(Value::Nil)
            }
            Stmt::Assign { left, right, .. } => {
                let v = self.expr(right, frame)?;
                self.assign(left, v, frame)?;
                Ok(Value::Nil)
            }
            Stmt::Return { expr } => {
                let v = self.expr(expr, frame)?;
                Err(Control::Return(v))
            }
            Stmt::Break => Err(Control::Break),
            Stmt::While { condition, block } => {
                loop {
                    let c = self.expr(condition, frame)?;
                    match c {
                        Value::Bool(true) => {}
                        Value::Bool(false) => break,
                        other => {
                            return panic(
                                condition.pos(),
                                format!("condition ({}) is not a boolean", other.display_nested()),
                            )
                        }
                    }
                    match self.block(block, frame) {
                        Ok(_) => {}
                        Err(Control::Break) => break,
                        Err(e) => return Err(e),
                    }
                }
                Ok(Value::Nil)
            }
            Stmt::For { slot, expr, block } => {
                let iter = self.expr(expr, frame)?;
                let pos = expr.pos().clone();
                if !matches!(iter, Value::Function(_)) {
                    return type_error(&pos, &iter, "function");
                }
                loop {
                    let r = self.call(&iter, Value::Nil, Vec::new(), &pos)?;
                    let d = match &r {
                        Value::Dict(d) => d.clone(),
                        other => return type_error(&pos, other, "dict"),
                    };
                    let finished = d.borrow().get(&Value::str(b"finished"));
                    let finished = match finished {
                        Some(Value::Bool(b)) => b,
                        Some(other) => return type_error(&pos, &other, "bool"),
                        None => return index_oob(&pos, &Value::str(b"finished")),
                    };
                    if finished {
                        break;
                    }
                    let value = d.borrow().get(&Value::str(b"value"));
                    let value = match value {
                        Some(v) => v,
                        None => return index_oob(&pos, &Value::str(b"value")),
                    };
                    *frame[*slot].borrow_mut() = value;
                    match self.block(block, frame) {
                        Ok(_) => {}
                        Err(Control::Break) => break,
                        Err(e) => return Err(e),
                    }
                }
                Ok(Value::Nil)
            }
            Stmt::Expr(e) => self.expr(e, frame),
        }
    }

    fn assign(&mut self, left: &Expr, value: Value, frame: &[Cell]) -> Exec<()> {
        match left {
            Expr::Slot { slot, .. } => {
                *frame[*slot].borrow_mut() = value;
                Ok(())
            }
            Expr::Access { object, field, field_pos, .. } => {
                let obj = self.expr(object, frame)?;
                let key = Value::String(field.clone());
                self.assign_field(&obj, object.pos(), key, field_pos, Some(field_pos), value)
            }
            Expr::Index { object, index, pos } => {
                let obj = self.expr(object, frame)?;
                let key = self.expr(index, frame)?;
                let ipos = index.pos().clone();
                self.assign_field(&obj, object.pos(), key, &ipos, Some(pos), value)
            }
            _ => Ok(()),
        }
    }

    fn assign_field(
        &mut self,
        obj: &Value,
        obj_pos: &SourcePos,
        key: Value,
        key_pos: &SourcePos,
        bracket_pos: Option<&SourcePos>,
        value: Value,
    ) -> Exec<()> {
        match obj {
            Value::Array(a) => {
                let i = match &key {
                    Value::Int(i) => *i,
                    other => return type_error(key_pos, other, "int"),
                };
                let mut a = a.borrow_mut();
                if i < 0 {
                    return index_oob(bracket_pos.unwrap_or(key_pos), &key);
                }
                if (i as usize) >= a.len() {
                    return index_oob(key_pos, &key);
                }
                a[i as usize] = value;
                Ok(())
            }
            Value::Dict(d) => {
                d.borrow_mut().insert(key, value);
                Ok(())
            }
            Value::Error(_) => panic(
                key_pos,
                format!("attempt to assign field ({}), which is readonly", key.display_nested()),
            ),
            other => type_error(obj_pos, other, "array, dict or error"),
        }
    }

    pub fn get_field(&mut self, obj: &Value, obj_pos: &SourcePos, key: &Value, key_pos: &SourcePos) -> Exec<Value> {
        match obj {
            Value::Array(a) => {
                let i = match key {
                    Value::Int(i) => *i,
                    other => return type_error(key_pos, other, "int"),
                };
                let a = a.borrow();
                if i < 0 || (i as usize) >= a.len() {
                    return index_oob(key_pos, key);
                }
                Ok(a[i as usize].clone())
            }
            Value::String(s) => {
                let i = match key {
                    Value::Int(i) => *i,
                    other => return type_error(key_pos, other, "int"),
                };
                if i < 0 || (i as usize) >= s.len() {
                    return index_oob(key_pos, key);
                }
                Ok(Value::Byte(s[i as usize]))
            }
            Value::Dict(d) => match d.borrow().get(key) {
                Some(v) => Ok(v),
                None => index_oob(key_pos, key),
            },
            Value::Error(e) => {
                if let Value::String(s) = key {
                    if s.as_ref() == b"description" {
                        return Ok(Value::String(e.description.clone()));
                    }
                    if s.as_ref() == b"context" {
                        return Ok(e.context.clone());
                    }
                }
                index_oob(key_pos, key)
            }
            other => type_error(obj_pos, other, "string, array, dict or error"),
        }
    }

    pub fn expr(&mut self, expr: &Expr, frame: &[Cell]) -> Exec<Value> {
        match expr {
            Expr::Slot { slot, .. } => Ok(frame[*slot].borrow().clone()),
            Expr::Literal { lit, pos } => self.literal(lit, pos, frame),
            Expr::Unary { op, operand, .. } => {
                let v = self.expr(operand, frame)?;
                match op {
                    UnaryOp::Minus => match v {
                        Value::Int(i) => Ok(Value::Int(i.wrapping_neg())),
                        Value::Float(x) => Ok(Value::Float(-x)),
                        other => type_error(operand.pos(), &other, "int or float"),
                    },
                    UnaryOp::Not => match v {
                        Value::Bool(b) => Ok(Value::Bool(!b)),
                        other => type_error(operand.pos(), &other, "bool"),
                    },
                    UnaryOp::Try => match v {
                        Value::Error(_) => Err(Control::Return(v)),
                        other => Ok(other),
                    },
                }
            }
            Expr::Binary { left, op, right, pos } => self.binary(left, *op, right, pos, frame),
            Expr::If { condition, then, otherwise, .. } => {
                let c = self.expr(condition, frame)?;
                match c {
                    Value::Bool(true) => self.block(then, frame),
                    Value::Bool(false) => self.block(otherwise, frame),
                    other => panic(
                        condition.pos(),
                        format!("condition ({}) is not a boolean", other.display_nested()),
                    ),
                }
            }
            Expr::Access { object, field, field_pos, .. } => {
                let obj = self.expr(object, frame)?;
                let key = Value::String(field.clone());
                self.get_field(&obj, object.pos(), &key, field_pos)
            }
            Expr::Index { object, index, .. } => {
                let obj = self.expr(object, frame)?;
                let key = self.expr(index, frame)?;
                self.get_field(&obj, object.pos(), &key, index.pos())
            }
            Expr::Call { function, args, pos } => {
                let (func, self_value) = match function.as_ref() {
                    Expr::Access { object, field, field_pos, .. } => {
                        let obj = self.expr(object, frame)?;
                        let key = Value::String(field.clone());
                        let f = self.get_field(&obj, object.pos(), &key, field_pos)?;
                        (f, obj)
                    }
                    Expr::Index { object, index, .. } => {
                        let obj = self.expr(object, frame)?;
                        let key = self.expr(index, frame)?;
                        let f = self.get_field(&obj, object.pos(), &key, index.pos())?;
                        (f, obj)
                    }
                    other => (self.expr(other, frame)?, Value::Nil),
                };
                if !matches!(func, Value::Function(_)) {
                    return panic(
                        function.pos(),
                        format!("attempt to call ({}), which is not a function", func.display_nested()),
                    );
                }
                let mut argv = Vec::with_capacity(args.len());
                for a in args {
                    argv.push(self.expr(a, frame)?);
                }
                self.call(&func, self_value, argv, pos)
            }
            Expr::CommandBlock { block, pos } => crate::command::eval_block(self, block, pos, frame),
        }
    }

    fn literal(&mut self, lit: &Lit, _pos: &SourcePos, frame: &[Cell]) -> Exec<Value> {
        Ok(match lit {
            Lit::Nil => Value::Nil,
            Lit::Bool(b) => Value::Bool(*b),
            Lit::Int(i) => Value::Int(*i),
            Lit::Float(x) => Value::Float(*x),
            Lit::Byte(b) => Value::Byte(*b),
            Lit::String(s) => Value::String(s.clone()),
            Lit::Array(items) => {
                let mut v = Vec::with_capacity(items.len());
                for item in items {
                    v.push(self.expr(item, frame)?);
                }
                Value::array(v)
            }
            Lit::Dict(items) => {
                let mut d = Dict::new();
                for (k, e) in items {
                    let v = self.expr(e, frame)?;
                    d.insert(Value::String(k.clone()), v);
                }
                Value::dict(d)
            }
            Lit::Function(def) => {
                let captures = def
                    .slots
                    .iter()
                    .filter_map(|k| match k {
                        SlotKind::Closed(p) => Some(frame[*p].clone()),
                        _ => None,
                    })
                    .collect();
                Value::Function(Function::Hush(Rc::new(HushFunction {
                    def: def.clone(),
                    captures,
                    path: def.pos.path.clone(),
                })))
            }
        })
    }

    fn binary(&mut self, left: &Expr, op: BinaryOp, right: &Expr, pos: &SourcePos, frame: &[Cell]) -> Exec<Value> {
        match op {
            BinaryOp::And | BinaryOp::Or => {
                let l = self.expr(left, frame)?;
                let lb = match l {
                    Value::Bool(b) => b,
                    other => return type_error(left.pos(), &other, "bool"),
                };
                if op == BinaryOp::And && !lb {
                    return Ok(Value::Bool(false));
                }
                if op == BinaryOp::Or && lb {
                    return Ok(Value::Bool(true));
                }
                let r = self.expr(right, frame)?;
                match r {
                    Value::Bool(b) => Ok(Value::Bool(b)),
                    other => type_error(right.pos(), &other, "bool"),
                }
            }
            _ => {
                let l = self.expr(left, frame)?;
                let r = self.expr(right, frame)?;
                binary_values(op, l, r, left.pos(), right.pos(), pos)
            }
        }
    }

    pub fn call(&mut self, func: &Value, self_value: Value, args: Vec<Value>, pos: &SourcePos) -> Exec<Value> {
        match func {
            Value::Function(Function::Hush(h)) => {
                let def = &h.def;
                if args.len() != def.params {
                    return panic(
                        pos,
                        format!(
                            "incorrect amount of function parameters -- supplied {}, expected {}",
                            args.len(),
                            def.params
                        ),
                    );
                }
                let mut frame: Vec<Cell> = Vec::with_capacity(def.slots.len());
                let mut cap = 0;
                let mut args = args.into_iter();
                for (i, kind) in def.slots.iter().enumerate() {
                    match kind {
                        SlotKind::Closed(_) => {
                            frame.push(h.captures[cap].clone());
                            cap += 1;
                        }
                        SlotKind::SelfValue => frame.push(Rc::new(RefCell::new(self_value.clone()))),
                        SlotKind::Regular => {
                            let v = if i < def.params { args.next().unwrap_or(Value::Nil) } else { Value::Nil };
                            frame.push(Rc::new(RefCell::new(v)));
                        }
                    }
                }
                match self.block(&def.body, &frame) {
                    Ok(v) => Ok(v),
                    Err(Control::Return(v)) => Ok(v),
                    Err(Control::Break) => Ok(Value::Nil),
                    Err(e) => Err(e),
                }
            }
            Value::Function(Function::Rust(r)) => {
                let r = r.clone();
                crate::stdlib::call_native(self, &r, self_value, args, pos)
            }
            other => panic(pos, format!("attempt to call ({}), which is not a function", other.display_nested())),
        }
    }
}

pub fn binary_values(
    op: BinaryOp,
    l: Value,
    r: Value,
    lpos: &SourcePos,
    rpos: &SourcePos,
    pos: &SourcePos,
) -> Exec<Value> {
    match op {
        BinaryOp::Plus | BinaryOp::Minus | BinaryOp::Times | BinaryOp::Div | BinaryOp::Mod => match (&l, &r) {
            (Value::Int(a), Value::Int(b)) => {
                let (a, b) = (*a, *b);
                let res = match op {
                    BinaryOp::Plus => a.checked_add(b),
                    BinaryOp::Minus => a.checked_sub(b),
                    BinaryOp::Times => a.checked_mul(b),
                    BinaryOp::Div => {
                        if b == 0 {
                            return panic(pos, "division by zero".into());
                        }
                        match a.checked_div(b) {
                            Some(v) => Some(v),
                            None => return panic(pos, "division by zero".into()),
                        }
                    }
                    _ => {
                        if b == 0 {
                            return panic(pos, "division by zero".into());
                        }
                        match a.checked_rem(b) {
                            Some(v) => Some(v),
                            None => return panic(pos, "division by zero".into()),
                        }
                    }
                };
                match res {
                    Some(v) => Ok(Value::Int(v)),
                    None => panic(pos, "integer overflow".into()),
                }
            }
            (Value::Int(_), other) => type_error(rpos, other, "int"),
            (Value::Float(a), Value::Float(b)) => {
                let (a, b) = (*a, *b);
                Ok(Value::Float(match op {
                    BinaryOp::Plus => a + b,
                    BinaryOp::Minus => a - b,
                    BinaryOp::Times => a * b,
                    BinaryOp::Div => a / b,
                    _ => a % b,
                }))
            }
            (Value::Float(_), other) => type_error(rpos, other, "float"),
            (other, _) => type_error(lpos, other, "int or float"),
        },
        BinaryOp::Concat => match (&l, &r) {
            (Value::String(a), Value::String(b)) => {
                let mut v = Vec::with_capacity(a.len() + b.len());
                v.extend_from_slice(a);
                v.extend_from_slice(b);
                Ok(Value::String(v.into()))
            }
            (Value::String(_), other) => type_error(rpos, other, "string"),
            (other, _) => type_error(lpos, other, "string"),
        },
        BinaryOp::Equals => Ok(Value::Bool(l == r)),
        BinaryOp::NotEquals => Ok(Value::Bool(l != r)),
        BinaryOp::Lower | BinaryOp::LowerEquals | BinaryOp::Greater | BinaryOp::GreaterEquals => {
            use std::cmp::Ordering;
            let ord = match (&l, &r) {
                (Value::Int(a), Value::Int(b)) => a.cmp(b),
                (Value::Int(_), other) => return type_error(rpos, other, "int"),
                (Value::Float(a), Value::Float(b)) => float_cmp(*a, *b),
                (Value::Float(_), other) => return type_error(rpos, other, "float"),
                (Value::Byte(a), Value::Byte(b)) => a.cmp(b),
                (Value::Byte(_), other) => return type_error(rpos, other, "char"),
                (Value::String(a), Value::String(b)) => a.as_ref().cmp(b.as_ref()),
                (Value::String(_), other) => return type_error(rpos, other, "string"),
                (other, _) => return type_error(lpos, other, "int, float, byte or string"),
            };
            let res = match op {
                BinaryOp::Lower => ord == Ordering::Less,
                BinaryOp::LowerEquals => ord != Ordering::Greater,
                BinaryOp::Greater => ord == Ordering::Greater,
                _ => ord != Ordering::Less,
            };
            Ok(Value::Bool(res))
        }
        BinaryOp::And | BinaryOp::Or => unreachable!(),
    }
}
