    Sleep,
    Len,
    Assert,
    Sort,
    Print,
    Trim,
    Glob,
    Randseed,
    HexEncode,
    HexDecode,
    Contains,
    HasError,
    JsonEncode,
    JsonDecode,
    Int,
    ToString,
    Exit,
    Iter,
    Read,
    Println,
    Rand,
    Replace,
    Pop,
    Substr,
    Args,
    Typecheck,
    Base64Encode,
    Base64Decode,
    Catch,
    Panic,
    Import,
    Randint,
}

pub enum IterState {
    Array(Rc<RefCell<Vec<Value>>>, usize),
    Dict(Vec<(Value, Value)>, usize),
    String(Rc<[u8]>, usize),
}

pub enum RangeState {
    Int { cur: i64, to: i64, step: i64 },
    Float { cur: f64, to: f64, step: f64 },
}

pub enum NativeKind {
    Std(StdFn),
    Range(RefCell<RangeState>),
    Iter(RefCell<IterState>),
    Bind { obj: Value, func: Value },
    RegexMatch(Rc<regex::bytes::Regex>),
    RegexSplit(Rc<regex::bytes::Regex>),
    RegexReplace(Rc<regex::bytes::Regex>),
    Join(RefCell<Option<crate::command::AsyncHandle>>),
}

fn native(name: &str, kind: NativeKind) -> Value {
    Value::Function(Function::Rust(Rc::new(RustFunction { name: name.to_string(), kind })))
}

fn stdfn(name: &str, f: StdFn) -> Value {
    native(&format!("std.{}", name), NativeKind::Std(f))
}

pub fn make_std() -> Value {
    let mut d = Dict::new();
    let mut add = |name: &str, v: Value| d.insert(Value::str(name.as_bytes()), v);
    add("cd", stdfn("cd", StdFn::Cd));
    add("type", stdfn("type", StdFn::Type));
    add("cwd", stdfn("cwd", StdFn::Cwd));
    add("is_empty", stdfn("is_empty", StdFn::IsEmpty));
    add("range", stdfn("range", StdFn::Range));
    add("bind", stdfn("bind", StdFn::Bind));
    add("error", stdfn("error", StdFn::Error));
    add("export", stdfn("export", StdFn::Export));
    add("env", stdfn("env", StdFn::Env));
    add("bytes", stdfn("bytes", StdFn::Bytes));
    add("split", stdfn("split", StdFn::Split));
    add("float", stdfn("float", StdFn::Float));
    add("regex", stdfn("regex", StdFn::Regex));
    add("push", stdfn("push", StdFn::Push));
    add("try_typecheck", stdfn("try_typecheck", StdFn::TryTypecheck));
    add("sleep", stdfn("sleep", StdFn::Sleep));
    add("len", stdfn("len", StdFn::Len));
    add("assert", stdfn("assert", StdFn::Assert));
    add("sort", stdfn("sort", StdFn::Sort));
    add("print", stdfn("print", StdFn::Print));
    add("trim", stdfn("trim", StdFn::Trim));
    add("glob", stdfn("glob", StdFn::Glob));
    add("randseed", stdfn("randseed", StdFn::Randseed));
    let hex = Value::dict_from(vec![
        ("encode", stdfn("hex.encode", StdFn::HexEncode)),
        ("decode", stdfn("hex.decode", StdFn::HexDecode)),
    ]);
    add("hex", hex);
    add("contains", stdfn("contains", StdFn::Contains));
    add("has_error", stdfn("has_error", StdFn::HasError));
    let json = Value::dict_from(vec![
        ("encode", stdfn("json.encode", StdFn::JsonEncode)),
        ("decode", stdfn("json.decode", StdFn::JsonDecode)),
    ]);
    add("json", json);
    add("int", stdfn("int", StdFn::Int));
    add("to_string", stdfn("to_string", StdFn::ToString));
    add("exit", stdfn("exit", StdFn::Exit));
    add("iter", stdfn("iter", StdFn::Iter));
    add("read", stdfn("read", StdFn::Read));
    add("println", stdfn("println", StdFn::Println));
    add("rand", stdfn("rand", StdFn::Rand));
    add("replace", stdfn("replace", StdFn::Replace));
    add("pop", stdfn("pop", StdFn::Pop));
    add("substr", stdfn("substr", StdFn::Substr));
    add("args", stdfn("args", StdFn::Args));
    add("typecheck", stdfn("typecheck", StdFn::Typecheck));
    let b64 = Value::dict_from(vec![
        ("encode", stdfn("base64.encode", StdFn::Base64Encode)),
        ("decode", stdfn("base64.decode", StdFn::Base64Decode)),
    ]);
    add("base64", b64);
    add("catch", stdfn("catch", StdFn::Catch));
    add("panic", stdfn("panic", StdFn::Panic));
    add("import", stdfn("import", StdFn::Import));
    add("randint", stdfn("randint", StdFn::Randint));
    Value::dict(d)
}

fn arity(pos: &SourcePos, args: &[Value], n: usize) -> Exec<()> {
    if args.len() != n {
        return panic(
            pos,
            format!("incorrect amount of function parameters -- supplied {}, expected {}", args.len(), n),
        );
    }
    Ok(())
}

fn get_string(pos: &SourcePos, v: &Value) -> Exec<Rc<[u8]>> {
    match v {
        Value::String(s) => Ok(s.clone()),
        other => type_error(pos, other, "string"),
    }
}

fn get_int(pos: &SourcePos, v: &Value) -> Exec<i64> {
    match v {
        Value::Int(i) => Ok(*i),
        other => type_error(pos, other, "int"),
    }
}

fn invalid_value<T>(pos: &SourcePos, v: &Value, expected: &str) -> Exec<T> {
    panic(pos, format!("invalid value ({}), expected {}", v.display_nested(), expected))
}

fn finished() -> Value {
    Value::dict_from(vec![("finished", Value::Bool(true))])
}

fn iteration(v: Value) -> Value {
    Value::dict_from(vec![("finished", Value::Bool(false)), ("value", v)])
}

pub fn stdout_write(bytes: &[u8]) {
    let out = std::io::stdout();
    let mut lock = out.lock();
    let _ = lock.write_all(bytes);
}

pub fn stdout_flush() {
    let _ = std::io::stdout().flush();
}

fn has_error(v: &Value) -> bool {
    match v {
        Value::Error(_) => true,
        Value::Array(a) => a.borrow().iter().any(has_error),
        Value::Dict(d) => d.borrow().entries.iter().any(|(k, v)| has_error(k) || has_error(v)),
        _ => false,
    }
}

fn str_lossy(b: &[u8]) -> String {
    String::from_utf8_lossy(b).into_owned()
}

fn valid_type(name: &[u8]) -> bool {
    matches!(
        name,
        b"nil" | b"bool" | b"int" | b"float" | b"char" | b"string" | b"array" | b"dict" | b"function" | b"error"
    )
}

impl Runtime {
    fn rng_with<T>(&self, f: impl FnOnce(&mut rand_chacha::ChaCha8Rng) -> T) -> T {
        let mut r = self.rng.borrow_mut();
        if r.is_none() {
            *r = Some(rand_chacha::ChaCha8Rng::from_entropy());
        }
        f(r.as_mut().unwrap())
    }
}

pub fn call_native(rt: &mut Runtime, f: &Rc<RustFunction>, self_value: Value, args: Vec<Value>, pos: &SourcePos) -> Exec<Value> {
    let _ = self_value;
    match &f.kind {
        NativeKind::Std(s) => call_std(rt, *s, args, pos),
        NativeKind::Range(state) => {
            arity(pos, &args, 0)?;
            let mut st = state.borrow_mut();
            match &mut *st {
                RangeState::Int { cur, to, step } => {
                    let more = if *step > 0 { *cur < *to } else if *step < 0 { *cur > *to } else { false };
                    if !more {
                        return Ok(finished());
                    }
                    let v = *cur;
                    *cur = cur.wrapping_add(*step);
                    Ok(iteration(Value::Int(v)))
                }
                RangeState::Float { cur, to, step } => {
                    let more = if *step > 0.0 { *cur < *to } else if *step < 0.0 { *cur > *to } else { false };
                    if !more {
                        return Ok(finished());
                    }
                    let v = *cur;
                    *cur += *step;
                    Ok(iteration(Value::Float(v)))
                }
            }
        }
        NativeKind::Iter(state) => {
            arity(pos, &args, 0)?;
            let mut st = state.borrow_mut();
            match &mut *st {
                IterState::Array(a, i) => {
                    let a = a.borrow();
                    if *i < a.len() {
                        let v = a[*i].clone();
                        *i += 1;
                        Ok(iteration(v))
                    } else {
                        Ok(finished())
                    }
                }
                IterState::Dict(entries, i) => {
                    if *i < entries.len() {
                        let (k, v) = entries[*i].clone();
                        *i += 1;
                        Ok(iteration(Value::dict_from(vec![("key", k), ("value", v)])))
                    } else {
                        Ok(finished())
                    }
                }
                IterState::String(s, i) => {
                    if *i < s.len() {
                        let v = Value::Byte(s[*i]);
                        *i += 1;
                        Ok(iteration(v))
                    } else {
                        Ok(finished())
                    }
                }
            }
        }
        NativeKind::Bind { obj, func } => {
            let obj = obj.clone();
            let func = func.clone();
            rt.call(&func, obj, args, pos)
        }
        NativeKind::RegexMatch(re) => {
            arity(pos, &args, 1)?;
            let s = get_string(pos, &args[0])?;
            Ok(Value::Bool(re.is_match(&s)))
        }
        NativeKind::RegexSplit(re) => {
            arity(pos, &args, 1)?;
            let s = get_string(pos, &args[0])?;
            let parts: Vec<Value> = re.split(&s).map(Value::str).collect();
            Ok(Value::array(parts))
        }
        NativeKind::RegexReplace(re) => {
            arity(pos, &args, 2)?;
            let s = get_string(pos, &args[0])?;
            let r = get_string(pos, &args[1])?;
            let out = re.replace_all(&s, r.as_ref());
            Ok(Value::str(&out))
        }
        NativeKind::Join(handle) => {
            arity(pos, &args, 0)?;
            let h = handle.borrow_mut().take();
            match h {
                None => panic(pos, "attempt to call join more than once".into()),
                Some(h) => crate::command::join_async(rt, h, pos),
            }
        }
    }
}

fn call_std(rt: &mut Runtime, f: StdFn, args: Vec<Value>, pos: &SourcePos) -> Exec<Value> {
    match f {
        StdFn::Print | StdFn::Println => {
            let mut out = Vec::new();
            for (i, a) in args.iter().enumerate() {
                if i > 0 {
                    out.push(b'\t');
                }
                a.fmt(&mut out, true);
            }
            if f == StdFn::Println {
                out.push(b'\n');
            }
            stdout_write(&out);
            Ok(Value::Nil)
        }
        StdFn::Len => {
            arity(pos, &args, 1)?;
            match &args[0] {
                Value::String(s) => Ok(Value::Int(s.len() as i64)),
                Value::Array(a) => Ok(Value::Int(a.borrow().len() as i64)),
                Value::Dict(d) => Ok(Value::Int(d.borrow().len() as i64)),
                other => type_error(pos, other, "string, array or dict"),
            }
        }
        StdFn::IsEmpty => {
            arity(pos, &args, 1)?;
            match &args[0] {
                Value::String(s) => Ok(Value::Bool(s.is_empty())),
                Value::Array(a) => Ok(Value::Bool(a.borrow().is_empty())),
                Value::Dict(d) => Ok(Value::Bool(d.borrow().is_empty())),
                other => type_error(pos, other, "string, array or dict"),
            }
        }
        StdFn::Contains => {
            arity(pos, &args, 2)?;
            match &args[0] {
                Value::Array(a) => Ok(Value::Bool(a.borrow().iter().any(|v| v == &args[1]))),
                Value::Dict(d) => Ok(Value::Bool(d.borrow().contains(&args[1]))),
                Value::String(s) => match &args[1] {
                    Value::Byte(b) => Ok(Value::Bool(s.contains(b))),
                    other => type_error(pos, other, "char"),
                },
                other => type_error(pos, other, "string ,array or dict"),
            }
        }
        StdFn::Push => {
            arity(pos, &args, 2)?;
            match &args[0] {
                Value::Array(a) => {
                    a.borrow_mut().push(args[1].clone());
                    Ok(Value::Nil)
                }
                other => type_error(pos, other, "array"),
            }
        }
        StdFn::Pop => {
            arity(pos, &args, 1)?;
            match &args[0] {
                Value::Array(a) => match a.borrow_mut().pop() {
                    Some(v) => Ok(v),
                    None => panic(pos, "collection is empty".into()),
                },
                other => type_error(pos, other, "array"),
            }
        }
        StdFn::Sort => {
            arity(pos, &args, 1)?;
            match &args[0] {
                Value::Array(a) => {
                    let mut v = a.borrow().clone();
                    v.sort_by(value_cmp);
                    *a.borrow_mut() = v;
                    Ok(Value::Nil)
                }
                other => type_error(pos, other, "array"),
            }
        }
        StdFn::Type => {
            arity(pos, &args, 1)?;
            Ok(Value::str(args[0].type_name().as_bytes()))
        }
        StdFn::ToString => {
            arity(pos, &args, 1)?;
            Ok(Value::String(args[0].display_top().into()))
        }
        StdFn::Int => {
            arity(pos, &args, 1)?;
            match &args[0] {
                Value::Int(i) => Ok(Value::Int(*i)),
                Value::Float(x) => Ok(Value::Int(*x as i64)),
                Value::String(s) => match std::str::from_utf8(s).ok().and_then(|s| s.parse::<i64>().ok()) {
                    Some(i) => Ok(Value::Int(i)),
                    None => invalid_value(pos, &args[0], "valid integer"),
                },
                other => type_error(pos, other, "int, float or string"),
            }
        }
        StdFn::Float => {
            arity(pos, &args, 1)?;
            match &args[0] {
                Value::Int(i) => Ok(Value::Float(*i as f64)),
                Value::Float(x) => Ok(Value::Float(*x)),
                Value::String(s) => match std::str::from_utf8(s).ok().and_then(|s| s.parse::<f64>().ok()) {
                    Some(x) => Ok(Value::Float(x)),
                    None => invalid_value(pos, &args[0], "valid integer"),
                },
                other => type_error(pos, other, "int, float or string"),
            }
        }
        StdFn::Bytes => {
            arity(pos, &args, 1)?;
            let s = get_string(pos, &args[0])?;
            Ok(Value::array(s.iter().map(|b| Value::Byte(*b)).collect()))
        }
        StdFn::Split => {
            arity(pos, &args, 2)?;
            let s = get_string(pos, &args[0])?;
            let sep = get_string(pos, &args[1])?;
            let s = str_lossy(&s);
            let sep = str_lossy(&sep);
            Ok(Value::array(s.split(sep.as_str()).map(|p| Value::str(p.as_bytes())).collect()))
        }
        StdFn::Substr => {
            arity(pos, &args, 3)?;
            let s = get_string(pos, &args[0])?;
            let start = get_int(pos, &args[1])?;
            let len = get_int(pos, &args[2])?;
            if start < 0 || len < 0 {
                return Ok(Value::Nil);
            }
            let (start, len) = (start as usize, len as usize);
            match start.checked_add(len) {
                Some(end) if end <= s.len() => Ok(Value::str(&s[start..end])),
                _ => Ok(Value::Nil),
            }
        }
        StdFn::Trim => {
            arity(pos, &args, 1)?;
            let s = get_string(pos, &args[0])?;
            match std::str::from_utf8(&s) {
                Ok(st) => Ok(Value::str(st.trim().as_bytes())),
                Err(_) => {
                    let st = str_lossy(&s);
                    Ok(Value::str(st.trim().as_bytes()))
                }
            }
        }
        StdFn::Replace => {
            arity(pos, &args, 3)?;
            let s = get_string(pos, &args[0])?;
            let from = get_string(pos, &args[1])?;
            let to = get_string(pos, &args[2])?;
            let s = str_lossy(&s);
            let from = str_lossy(&from);
            let to = str_lossy(&to);
            Ok(Value::str(s.replace(from.as_str(), to.as_str()).as_bytes()))
        }
        StdFn::Range => {
            arity(pos, &args, 3)?;
            let mut any_float = false;
            for a in &args {
                match a {
                    Value::Int(_) => {}
                    Value::Float(_) => any_float = true,
                    other => return type_error(pos, other, "int or float"),
                }
            }
            let state = if any_float {
                let f = |v: &Value| match v {
                    Value::Int(i) => *i as f64,
                    Value::Float(x) => *x,
                    _ => 0.0,
                };
                RangeState::Float { cur: f(&args[0]), to: f(&args[1]), step: f(&args[2]) }
            } else {
                let f = |v: &Value| match v {
                    Value::Int(i) => *i,
                    _ => 0,
                };
                RangeState::Int { cur: f(&args[0]), to: f(&args[1]), step: f(&args[2]) }
            };
            Ok(native("std.range<impl>", NativeKind::Range(RefCell::new(state))))
        }
        StdFn::Iter => {
            arity(pos, &args, 1)?;
            let state = match &args[0] {
                Value::Array(a) => IterState::Array(a.clone(), 0),
                Value::Dict(d) => IterState::Dict(d.borrow().entries.clone(), 0),
                Value::String(s) => IterState::String(s.clone(), 0),
                other => return type_error(pos, other, "string, array or dict"),
            };
            Ok(native("std.iter<impl>", NativeKind::Iter(RefCell::new(state))))
        }
        StdFn::Bind => {
            arity(pos, &args, 2)?;
            match &args[1] {
                Value::Function(_) => {}
                other => return type_error(pos, other, "function"),
            }
            Ok(native("std.bind<impl>", NativeKind::Bind { obj: args[0].clone(), func: args[1].clone() }))
        }
        StdFn::Error => {
            arity(pos, &args, 2)?;
            let d = get_string(pos, &args[0])?;
            Ok(Value::Error(Rc::new(ErrorValue { description: d, context: args[1].clone() })))
        }
        StdFn::HasError => {
            arity(pos, &args, 1)?;
            Ok(Value::Bool(has_error(&args[0])))
        }
        StdFn::Typecheck | StdFn::TryTypecheck => {
            arity(pos, &args, 2)?;
            let t = get_string(pos, &args[1])?;
            if !valid_type(&t) {
                return invalid_value(pos, &args[1], "valid type");
            }
            let actual = args[0].type_name();
            if actual.as_bytes() == t.as_ref() {
                if f == StdFn::Typecheck {
                    Ok(args[0].clone())
                } else {
                    Ok(Value::Nil)
                }
            } else if f == StdFn::Typecheck {
                type_error(pos, &args[0], &str_lossy(&t))
            } else {
                let msg = format!(
                    "type error: expected {}, got {} ({})",
                    str_lossy(&t),
                    actual,
                    args[0].display_nested()
                );
                Ok(Value::error(msg.as_bytes(), args[0].clone()))
            }
        }
        StdFn::Assert => {
            arity(pos, &args, 1)?;
            match &args[0] {
                Value::Bool(true) => Ok(Value::Nil),
                Value::Bool(false) => panic(pos, "assertion failed".into()),
                other => type_error(pos, other, "bool"),
            }
        }
        StdFn::Panic => {
            arity(pos, &args, 1)?;
            panic(pos, format!("std.panic({})", args[0].display_nested()))
        }
        StdFn::Catch => {
            arity(pos, &args, 1)?;
            match &args[0] {
                Value::Function(_) => {}
                other => return type_error(pos, other, "function"),
            }
            match rt.call(&args[0], Value::Nil, Vec::new(), pos) {
                Ok(v) => Ok(v),
                Err(Control::Panic(p)) => {
                    let desc = format!("caught panic: {}", p);
                    Ok(Value::error(desc.as_bytes(), Value::str(b"panic")))
                }
                Err(other) => Err(other),
            }
        }
        StdFn::Import => {
            arity(pos, &args, 1)?;
            let p = get_string(pos, &args[0])?;
            crate::import_module(rt, &p, pos)
        }
        StdFn::Args => {
            arity(pos, &args, 0)?;
            Ok(Value::array(rt.args.iter().map(|a| Value::str(a)).collect()))
        }
        StdFn::Env => {
            arity(pos, &args, 1)?;
            let k = get_string(pos, &args[0])?;
            use std::os::unix::ffi::{OsStrExt, OsStringExt};
            match std::env::var_os(std::ffi::OsStr::from_bytes(&k)) {
                Some(v) => Ok(Value::str(&v.into_vec())),
                None => Ok(Value::Nil),
            }
        }
        StdFn::Export => {
            arity(pos, &args, 2)?;
            let k = get_string(pos, &args[0])?;
            let v = get_string(pos, &args[1])?;
            use std::os::unix::ffi::OsStrExt;
            std::env::set_var(std::ffi::OsStr::from_bytes(&k), std::ffi::OsStr::from_bytes(&v));
            Ok(Value::Nil)
        }
        StdFn::Cd => {
            arity(pos, &args, 1)?;
            let p = get_string(pos, &args[0])?;
            use std::os::unix::ffi::OsStrExt;
            match std::env::set_current_dir(std::ffi::OsStr::from_bytes(&p)) {
                Ok(()) => Ok(Value::Nil),
                Err(e) => Ok(Value::error(e.to_string().as_bytes(), Value::Nil)),
            }
        }
        StdFn::Cwd => {
            arity(pos, &args, 0)?;
            use std::os::unix::ffi::OsStringExt;
            match std::env::current_dir() {
                Ok(p) => Ok(Value::str(&p.into_os_string().into_vec())),
                Err(e) => panic(pos, e.to_string()),
            }
        }
        StdFn::Read => {
            if args.len() > 1 {
                return arity(pos, &args, 1).map(|_| Value::Nil);
            }
            if let Some(p) = args.first() {
                let p = get_string(pos, p)?;
                stdout_write(&p);
            }
            stdout_flush();
            let mut line = String::new();
            match std::io::stdin().lock().read_line(&mut line) {
                Ok(_) => Ok(Value::str(line.as_bytes())),
                Err(e) => panic(pos, e.to_string()),
            }
        }
        StdFn::Sleep => {
            arity(pos, &args, 1)?;
            let ms = get_int(pos, &args[0])?;
            if ms < 0 {
                return invalid_value(pos, &args[0], "positive integer");
            }
            std::thread::sleep(std::time::Duration::from_millis(ms as u64));
            Ok(Value::Nil)
        }
        StdFn::Exit => {
            arity(pos, &args, 1)?;
            let code = get_int(pos, &args[0])?;
            if !(0..=255).contains(&code) {
                return invalid_value(pos, &args[0], "valid exit code");
            }
            stdout_flush();
            std::process::exit(code as i32);
        }
        StdFn::Rand => {
            arity(pos, &args, 0)?;
            let x: f64 = rt.rng_with(|r| r.gen());
            Ok(Value::Float(x))
        }
        StdFn::Randint => {
            arity(pos, &args, 2)?;
            let a = get_int(pos, &args[0])?;
            let b = get_int(pos, &args[1])?;
            let x: i64 = rt.rng_with(|r| r.gen_range(a..=b));
            Ok(Value::Int(x))
        }
        StdFn::Randseed => {
            arity(pos, &args, 1)?;
            let s = get_int(pos, &args[0])?;
            *rt.rng.borrow_mut() = Some(rand_chacha::ChaCha8Rng::seed_from_u64(s as u64));
            Ok(Value::Nil)
        }
        StdFn::Glob => {
            arity(pos, &args, 1)?;
            let p = get_string(pos, &args[0])?;
            let p = str_lossy(&p);
