pub fn base64_decode(input: &[u8]) -> Result<Vec<u8>, String> {
    let rem = input.len() % 8;
    if rem == 1 || rem == 5 {
        if let Some(b) = input.last() {
            if *b != b'=' && decode_value(*b).is_none() {
                return Err(invalid_byte(input.len() - 1, *b));
            }
        }
        return Err("Encoded text cannot have a 6-bit remainder.".to_string());
    }
    if input.is_empty() {
        return Ok(Vec::new());
    }
    let num_chunks = (input.len() + 7) / 8;
    let mut out = Vec::new();
    let mut input_index = 0;
    for _ in 1..num_chunks {
        let chunk = &input[input_index..input_index + 8];
        let mut acc: u64 = 0;
        for (i, b) in chunk.iter().enumerate() {
            match decode_value(*b) {
                Some(m) => acc = (acc << 6) | m as u64,
                None => return Err(invalid_byte(input_index + i, *b)),
            }
        }
        for k in (0..6).rev() {
            out.push((acc >> (k * 8)) as u8);
        }
        input_index += 8;
    }
