    let start = input_index;
    let mut leftover_bits: u64 = 0;
    let mut morsels: u32 = 0;
    let mut padding_bytes = 0;
    let mut first_padding_index = 0usize;
    let mut last_symbol = 0u8;
    for (i, b) in input[start..].iter().enumerate() {
        if *b == b'=' {
            if i % 4 < 2 {
                let bad = start + if padding_bytes > 0 { first_padding_index } else { i };
                return Err(invalid_byte(bad, *b));
            }
            if padding_bytes == 0 {
                first_padding_index = i;
            }
            padding_bytes += 1;
            continue;
        }
        if padding_bytes > 0 {
            return Err(invalid_byte(start + first_padding_index, b'='));
        }
        last_symbol = *b;
        let shift = 64 - (morsels + 1) * 6;
        let m = match decode_value(*b) {
            Some(m) => m,
            None => return Err(invalid_byte(start + i, *b)),
        };
        leftover_bits |= (m as u64) << shift;
        morsels += 1;
    }
    let ready: u32 = match morsels {
        0 => 0,
        2 => 8,
        3 => 16,
        4 => 24,
        6 => 32,
        7 => 40,
        8 => 48,
        _ => return Err("Encoded text cannot have a 6-bit remainder.".to_string()),
    };
    let mask: u64 = if ready == 0 { !0 } else { !0u64 >> ready };
    if (leftover_bits & mask) != 0 {
        return Err(format!(
            "Invalid last symbol {}, offset {}.",
            last_symbol,
            start + morsels as usize - 1
        ));
    }
    let mut appended = 0;
    while appended < ready {
        out.push((leftover_bits >> (56 - appended)) as u8);
        appended += 8;
    }
    Ok(out)
