// JSON encoding/decoding.

use crate::value::*;
use serde::de::{self, Deserialize, Deserializer, MapAccess, SeqAccess, Visitor};
use std::fmt;

fn escape_json(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\x08' => out.push_str("\\b"),
            '\x0c' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
}

fn indent(out: &mut String, n: usize) {
    for _ in 0..n {
        out.push_str("  ");
    }
}

fn enc(out: &mut String, v: &Value, n: usize) -> bool {
    match v {
        Value::Nil => out.push_str("null"),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Int(i) => out.push_str(&i.to_string()),
        Value::Float(x) => {
            if x.is_finite() {
                let mut buf = ryu::Buffer::new();
                out.push_str(buf.format_finite(*x));
            } else {
                out.push_str("null");
            }
        }
        Value::Byte(b) => {
            let s = (*b as char).to_string();
            escape_json(out, &s);
        }
        Value::String(s) => escape_json(out, &String::from_utf8_lossy(s)),
        Value::Array(a) => {
            let a = a.borrow();
            if a.is_empty() {
                out.push_str("[]");
                return true;
            }
            out.push_str("[\n");
            for (i, item) in a.iter().enumerate() {
                if i > 0 {
                    out.push_str(",\n");
                }
                indent(out, n + 1);
                if !enc(out, item, n + 1) {
                    return false;
                }
            }
            out.push('\n');
            indent(out, n);
            out.push(']');
        }
        Value::Dict(d) => {
            let d = d.borrow();
            if d.is_empty() {
                out.push_str("{}");
                return true;
            }
            out.push_str("{\n");
            for (i, (k, item)) in d.entries.iter().enumerate() {
                if i > 0 {
                    out.push_str(",\n");
                }
                indent(out, n + 1);
                match k {
                    Value::String(s) => escape_json(out, &String::from_utf8_lossy(s)),
                    _ => return false,
                }
                out.push_str(": ");
                if !enc(out, item, n + 1) {
                    return false;
                }
            }
            out.push('\n');
            indent(out, n);
            out.push('}');
        }
        Value::Function(_) | Value::Error(_) => return false,
    }
    true
}

pub fn encode(v: &Value) -> Option<String> {
    let mut out = String::new();
    if enc(&mut out, v, 0) {
        Some(out)
    } else {
        None
    }
}

struct JsonValue(Value);

struct ValueVisitor;

impl<'de> Visitor<'de> for ValueVisitor {
    type Value = JsonValue;

    fn expecting(&self, f: &mut fmt::Formatter) -> fmt::Result {
        f.write_str("any valid JSON value")
    }

    fn visit_bool<E>(self, v: bool) -> Result<JsonValue, E> {
        Ok(JsonValue(Value::Bool(v)))
    }
    fn visit_i64<E>(self, v: i64) -> Result<JsonValue, E> {
        Ok(JsonValue(Value::Int(v)))
    }
    fn visit_u64<E: de::Error>(self, v: u64) -> Result<JsonValue, E> {
        match i64::try_from(v) {
            Ok(i) => Ok(JsonValue(Value::Int(i))),
            Err(e) => Err(E::custom(e)),
        }
    }
    fn visit_f64<E>(self, v: f64) -> Result<JsonValue, E> {
        Ok(JsonValue(Value::Float(v)))
    }
    fn visit_str<E>(self, v: &str) -> Result<JsonValue, E> {
        Ok(JsonValue(Value::str(v.as_bytes())))
    }
    fn visit_string<E>(self, v: String) -> Result<JsonValue, E> {
        Ok(JsonValue(Value::str(v.as_bytes())))
    }
    fn visit_none<E>(self) -> Result<JsonValue, E> {
        Ok(JsonValue(Value::Nil))
    }
    fn visit_unit<E>(self) -> Result<JsonValue, E> {
        Ok(JsonValue(Value::Nil))
    }
    fn visit_some<D: Deserializer<'de>>(self, d: D) -> Result<JsonValue, D::Error> {
        JsonValue::deserialize(d)
    }
    fn visit_seq<A: SeqAccess<'de>>(self, mut seq: A) -> Result<JsonValue, A::Error> {
        let mut v = Vec::new();
        while let Some(JsonValue(item)) = seq.next_element()? {
            v.push(item);
        }
        Ok(JsonValue(Value::array(v)))
    }
    fn visit_map<A: MapAccess<'de>>(self, mut map: A) -> Result<JsonValue, A::Error> {
        let mut d = Dict::new();
        while let Some(key) = map.next_key::<String>()? {
            let JsonValue(v) = map.next_value()?;
            d.insert(Value::str(key.as_bytes()), v);
        }
        Ok(JsonValue(Value::dict(d)))
    }
}

impl<'de> Deserialize<'de> for JsonValue {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<JsonValue, D::Error> {
        d.deserialize_any(ValueVisitor)
    }
}

pub fn decode(s: &[u8]) -> Result<Value, String> {
    match serde_json::from_slice::<JsonValue>(s) {
        Ok(JsonValue(v)) => Ok(v),
        Err(e) => Err(e.to_string()),
    }
}
