// Command block execution.

use crate::ast::BlockKind;
use crate::interp::{panic, type_error, Control, Exec, Panic, Runtime};
use crate::lexer::Expansion;
use crate::program::*;
use crate::value::*;
use std::io::{Read, Write};
use std::os::unix::ffi::{OsStrExt, OsStringExt};
use std::os::unix::io::{AsRawFd, FromRawFd, IntoRawFd, RawFd};
use std::os::unix::process::{CommandExt, ExitStatusExt};
use std::process::{Child, Stdio};
use std::rc::Rc;

#[derive(Clone, Debug)]
pub enum Piece {
    Lit(Vec<u8>),
    Star,
    Percent,
    Home,
}

#[derive(Clone, Debug, Default)]
pub struct Fragment {
    pub pieces: Vec<Piece>,
}

impl Fragment {
    fn push_lit(&mut self, b: &[u8]) {
        if let Some(Piece::Lit(l)) = self.pieces.last_mut() {
            l.extend_from_slice(b);
        } else {
            self.pieces.push(Piece::Lit(b.to_vec()));
        }
    }
    fn is_glob(&self) -> bool {
        self.pieces.iter().any(|p| matches!(p, Piece::Star | Piece::Percent))
    }
}

#[derive(Clone, Debug)]
pub enum RTarget {
    Fd(u8),
    Overwrite(Fragment),
    Append(Fragment),
}

#[derive(Clone, Debug)]
pub enum RRedir {
    Output { source: u8, target: RTarget },
    Input { literal: bool, source: Fragment },
}

#[derive(Clone, Debug)]
pub struct RCommand {
    pub builtin: Option<Builtin>,
    pub program: Fragment,
    pub args: Vec<Fragment>,
    pub redirections: Vec<RRedir>,
    pub abort_on_error: bool,
    pub pos: SourcePos,
}

#[derive(Clone, Debug)]
pub struct RPipeline {
    pub commands: Vec<RCommand>,
}

/// Errors as plain Rust data (sendable across threads).
#[derive(Clone, Debug)]
pub enum CmdError {
    NonZero { pos: String, status: i64 },
    Io { message: String, pos: String },
    Pipeline(Vec<CmdError>),
    Block(Vec<CmdError>),
}

pub struct BlockOutcome {
    pub errors: Vec<CmdError>,
    pub stdout: Vec<u8>,
    pub stderr: Vec<u8>,
}

pub enum BlockFail {
    Panic { message: String, pos: SourcePos },
    RustPanic(&'static str),
}

pub struct AsyncHandle {
    thread: std::thread::JoinHandle<Result<BlockOutcome, BlockFail>>,
}

fn pos_str(pos: &SourcePos) -> String {
    format!("{}", pos)
}

impl CmdError {
    pub fn to_value(&self) -> Value {
        match self {
            CmdError::NonZero { pos, status } => Value::error(
                b"command returned non-zero",
                Value::dict_from(vec![("pos", Value::str(pos.as_bytes())), ("status", Value::Int(*status))]),
            ),
            CmdError::Io { message, pos } => Value::error(
                message.as_bytes(),
                Value::dict_from(vec![("pos", Value::str(pos.as_bytes())), ("status", Value::Int(127))]),
            ),
            CmdError::Pipeline(errs) => Value::error(
                b"Some commands failed in the pipeline",
                Value::array(errs.iter().map(|e| e.to_value()).collect()),
            ),
            CmdError::Block(errs) => Value::error(
                b"Some commands failed in the block",
                Value::array(errs.iter().map(|e| e.to_value()).collect()),
            ),
        }
    }
}

// ---------------------------------------------------------------------------
// Phase 1: argument evaluation.

fn value_bytes(v: &Value, pos: &SourcePos) -> Exec<Vec<u8>> {
    match v {
        Value::Nil => Ok(Vec::new()),
        Value::Bool(b) => Ok(if *b { b"true".to_vec() } else { b"false".to_vec() }),
        Value::Int(i) => Ok(i.to_string().into_bytes()),
        Value::Float(x) => Ok(format!("{:?}", x).into_bytes()),
        Value::Byte(b) => Ok(vec![*b]),
        Value::String(s) => Ok(s.to_vec()),
        other => type_error(pos, other, "nil, bool, int, float, byte or string"),
    }
}

fn eval_argument(arg: &Argument, frame: &[Cell]) -> Exec<Vec<Fragment>> {
    let mut current: Vec<Fragment> = Vec::new();
    for unit in &arg.units {
        match unit {
            ArgUnit::Literal(l) => {
                if current.is_empty() {
                    current.push(Fragment::default());
                }
                for f in current.iter_mut() {
                    f.push_lit(l);
                }
            }
            ArgUnit::Expansion(e) => {
                if current.is_empty() {
                    current.push(Fragment::default());
                }
                let piece = match e {
                    Expansion::Home => Piece::Home,
                    Expansion::Star => Piece::Star,
                    Expansion::Percent => Piece::Percent,
                };
                for f in current.iter_mut() {
                    f.pieces.push(piece.clone());
                }
            }
            ArgUnit::Dollar { slot, pos } => {
                let v = frame[*slot].borrow().clone();
                match &v {
                    Value::Array(a) => {
                        let items: Vec<Value> = a.borrow().clone();
                        let mut vals = Vec::new();
                        for item in &items {
                            vals.push(value_bytes(item, pos)?);
                        }
                        if vals.is_empty() {
                            continue;
                        }
                        if current.is_empty() {
                            current = vals
                                .into_iter()
                                .map(|b| {
                                    let mut f = Fragment::default();
                                    f.push_lit(&b);
                                    f
                                })
                                .collect();
                        } else {
                            let mut next = Vec::new();
                            for b in &vals {
                                for f in &current {
                                    let mut f = f.clone();
                                    f.push_lit(b);
                                    next.push(f);
                                }
                            }
                            current = next;
                        }
                    }
                    other => {
                        let b = value_bytes(other, pos)?;
                        if current.is_empty() {
                            current.push(Fragment::default());
                        }
                        for f in current.iter_mut() {
                            f.push_lit(&b);
                        }
                    }
                }
            }
        }
    }
    Ok(current)
}

fn eval_single(arg: &Argument, frame: &[Cell], what: &str) -> Exec<Fragment> {
    let mut frags = eval_argument(arg, frame)?;
    let first = frags.pop();
    match first {
        Some(f) if frags.is_empty() => Ok(f),
        _ => panic(&arg.pos, format!("{} expansion resulted in {} items", what, frags.len())),
    }
}

fn eval_command(cmd: &BasicCommand, frame: &[Cell]) -> Exec<RCommand> {
    let (builtin, program, arguments, redirections, abort_on_error, pos) = match cmd {
        BasicCommand::Command { program, arguments, redirections, abort_on_error, pos } => {
            (None, program, arguments, redirections, *abort_on_error, pos)
        }
        BasicCommand::Builtin { builtin, program, arguments, redirections, abort_on_error, pos } => {
            (Some(*builtin), program, arguments, redirections, *abort_on_error, pos)
        }
    };
    let program = eval_single(program, frame, "program")?;
    let mut args = Vec::new();
    for a in arguments {
        args.extend(eval_argument(a, frame)?);
    }
    let mut redirs = Vec::new();
    for r in redirections {
        match r {
            Redirection::Output { source, target } => {
                let target = match target {
                    RedirectionTarget::Fd(fd) => RTarget::Fd(*fd),
                    RedirectionTarget::Overwrite(a) => RTarget::Overwrite(eval_single(a, frame, "redirection")?),
                    RedirectionTarget::Append(a) => RTarget::Append(eval_single(a, frame, "redirection")?),
                };
                redirs.push(RRedir::Output { source: *source, target });
            }
            Redirection::Input { literal, source } => {
                let source = eval_single(source, frame, "redirection")?;
                redirs.push(RRedir::Input { literal: *literal, source });
            }
        }
    }
    Ok(RCommand { builtin, program, args, redirections: redirs, abort_on_error, pos: pos.clone() })
}

pub fn eval_block(rt: &mut Runtime, block: &Rc<CommandBlock>, _pos: &SourcePos, frame: &[Cell]) -> Exec<Value> {
    let mut pipelines = Vec::new();
    for cmd in std::iter::once(&block.head).chain(block.tail.iter()) {
        let mut commands = Vec::new();
        for basic in std::iter::once(&cmd.head).chain(cmd.tail.iter()) {
            commands.push(eval_command(basic, frame)?);
        }
        pipelines.push(RPipeline { commands });
    }
    match block.kind {
        BlockKind::Synchronous => {
            let outcome = run_block(&pipelines, false);
            let outcome = outcome_to_exec(outcome)?;
            Ok(errors_value(&outcome.errors).unwrap_or(Value::Nil))
        }
        BlockKind::Capture => {
            let outcome = run_block(&pipelines, true);
            let outcome = outcome_to_exec(outcome)?;
            Ok(capture_value(outcome))
        }
        BlockKind::Async => {
            let thread = std::thread::spawn(move || run_block(&pipelines, false));
            let handle = AsyncHandle { thread };
            let join = Value::Function(Function::Rust(Rc::new(RustFunction {
                name: "<command>.join".to_string(),
                kind: crate::stdlib::NativeKind::Join(std::cell::RefCell::new(Some(handle))),
            })));
            let _ = rt;
            Ok(Value::dict_from(vec![("join", join)]))
        }
    }
}

fn outcome_to_exec(r: Result<BlockOutcome, BlockFail>) -> Exec<BlockOutcome> {
    match r {
        Ok(o) => Ok(o),
        Err(BlockFail::Panic { message, pos }) => Err(Control::Panic(Panic { message, pos })),
        Err(BlockFail::RustPanic(loc)) => crate::rust_panic(loc, "not yet implemented"),
    }
}

fn errors_value(errors: &[CmdError]) -> Option<Value> {
    match errors.len() {
        0 => None,
        1 => Some(errors[0].to_value()),
        _ => Some(CmdError::Block(errors.to_vec()).to_value()),
    }
}

fn capture_value(outcome: BlockOutcome) -> Value {
    let stdout = Value::str(&outcome.stdout);
    let stderr = Value::str(&outcome.stderr);
    match errors_value(&outcome.errors) {
        None => Value::dict_from(vec![("stdout", stdout), ("stderr", stderr)]),
        Some(Value::Error(e)) => Value::error(
            &e.description,
            Value::dict_from(vec![("stdout", stdout), ("stderr", stderr), ("error", e.context.clone())]),
        ),
        Some(other) => other,
    }
}

pub fn join_async(_rt: &mut Runtime, handle: AsyncHandle, _pos: &SourcePos) -> Exec<Value> {
    let r = match handle.thread.join() {
        Ok(r) => r,
        Err(_) => return Ok(Value::Nil),
    };
    let outcome = outcome_to_exec(r)?;
    Ok(errors_value(&outcome.errors).unwrap_or(Value::Nil))
}

// ---------------------------------------------------------------------------
// Phase 2: execution.

fn home_dir() -> Vec<u8> {
    match std::env::var_os("HOME") {
        Some(h) => h.into_vec(),
        None => Vec::new(),
    }
}

fn glob_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '?' | '*' | '[' | ']' => {
                out.push('[');
                out.push(c);
                out.push(']');
            }
            c => out.push(c),
        }
    }
    out
}

/// Expand a fragment into final arguments.
fn expand(frag: &Fragment, pos: &SourcePos) -> Result<Vec<Vec<u8>>, BlockFail> {
    if !frag.is_glob() {
        let mut out = Vec::new();
        for p in &frag.pieces {
            match p {
                Piece::Lit(l) => out.extend_from_slice(l),
                Piece::Home => {
                    out.extend_from_slice(&home_dir());
                    out.push(b'/');
                }
                _ => {}
            }
        }
        return Ok(vec![out]);
    }
    let mut pattern = String::new();
    for p in &frag.pieces {
        match p {
            Piece::Lit(l) => pattern.push_str(&glob_escape(&String::from_utf8_lossy(l))),
            Piece::Home => {
                pattern.push_str(&glob_escape(&String::from_utf8_lossy(&home_dir())));
                pattern.push('/');
            }
            Piece::Star => pattern.push('*'),
            Piece::Percent => pattern.push('?'),
        }
    }
    match glob::glob(&pattern) {
        Ok(paths) => {
            let mut out = Vec::new();
            for p in paths.flatten() {
                let p = if p.is_absolute() { p } else { std::path::Path::new(".").join(p) };
                out.push(p.into_os_string().into_vec());
            }
            Ok(out)
        }
        Err(_) => Err(BlockFail::Panic {
            message: format!("pattern ({:?}) has invalid UTF-8", pattern),
            pos: pos.clone(),
        }),
    }
}

fn expand_single(frag: &Fragment, pos: &SourcePos, what: &str) -> Result<Vec<u8>, BlockFail> {
    let mut items = expand(frag, pos)?;
    if items.len() != 1 {
        return Err(BlockFail::Panic {
            message: format!("{} expansion resulted in {} items", what, items.len()),
            pos: pos.clone(),
        });
    }
    Ok(items.pop().unwrap())
}

fn exit_status_code(status: std::process::ExitStatus) -> i64 {
    match status.code() {
        Some(c) => c as i64,
        None => 255 + status.signal().unwrap_or(0) as i64,
    }
}

struct Prepared {
    program: Vec<u8>,
    arg0: Option<Vec<u8>>,
    args: Vec<Vec<u8>>,
    /// dup2 operations: (from_fd, to_fd)
    dups: Vec<(RawFd, RawFd)>,
    /// files kept open until spawn
    files: Vec<std::fs::File>,
    literal_inputs: Vec<(std::io::PipeWriter, Vec<u8>)>,
    readers: Vec<std::io::PipeReader>,
}

enum PrepError {
    Fail(BlockFail),
    Io(String),
}

fn prepare(cmd: &RCommand) -> Result<Prepared, PrepError> {
    let program = expand_single(&cmd.program, &cmd.pos, "program").map_err(PrepError::Fail)?;
    let mut args = Vec::new();
    for a in &cmd.args {
        args.extend(expand(a, &cmd.pos).map_err(PrepError::Fail)?);
    }
    let mut p = Prepared {
        program,
        arg0: None,
        args,
        dups: Vec::new(),
        files: Vec::new(),
        literal_inputs: Vec::new(),
        readers: Vec::new(),
    };
    for r in &cmd.redirections {
        match r {
            RRedir::Output { source, target } => {
                if *source != 1 && *source != 2 {
                    return Err(PrepError::Fail(BlockFail::Panic {
                        message: format!("unsupported file descriptor ({})", source),
                        pos: cmd.pos.clone(),
                    }));
                }
                match target {
                    RTarget::Fd(fd) => {
                        if *fd != 1 && *fd != 2 {
                            return Err(PrepError::Fail(BlockFail::Panic {
                                message: format!("unsupported file descriptor ({})", fd),
                                pos: cmd.pos.clone(),
                            }));
                        }
                        p.dups.push((*fd as RawFd, *source as RawFd));
                    }
                    RTarget::Overwrite(f) | RTarget::Append(f) => {
                        let path = expand_single(f, &cmd.pos, "redirection").map_err(PrepError::Fail)?;
                        let append = matches!(target, RTarget::Append(_));
                        let file = std::fs::OpenOptions::new()
                            .write(true)
                            .create(true)
                            .append(append)
                            .truncate(!append)
                            .open(std::ffi::OsStr::from_bytes(&path))
                            .map_err(|e| PrepError::Io(e.to_string()))?;
                        p.dups.push((file.as_raw_fd(), *source as RawFd));
                        p.files.push(file);
                    }
                }
            }
            RRedir::Input { literal, source } => {
                let data = expand_single(source, &cmd.pos, "redirection").map_err(PrepError::Fail)?;
                if *literal {
                    let (reader, writer) = std::io::pipe().map_err(|e| PrepError::Io(e.to_string()))?;
                    let mut data = data;
                    data.push(b'\n');
                    p.dups.push((reader.as_raw_fd(), 0));
                    p.readers.push(reader);
                    p.literal_inputs.push((writer, data));
                } else {
                    let file = std::fs::File::open(std::ffi::OsStr::from_bytes(&data))
                        .map_err(|e| PrepError::Io(e.to_string()))?;
                    p.dups.push((file.as_raw_fd(), 0));
                    p.files.push(file);
                }
            }
        }
    }
    Ok(p)
}

fn build_command(p: &Prepared) -> std::process::Command {
    let mut c = std::process::Command::new(std::ffi::OsStr::from_bytes(&p.program));
    if let Some(a0) = &p.arg0 {
        c.arg0(std::ffi::OsStr::from_bytes(a0));
    }
    for a in &p.args {
        c.arg(std::ffi::OsStr::from_bytes(a));
    }
    if !p.dups.is_empty() {
        let dups = p.dups.clone();
        unsafe {
            c.pre_exec(move || {
                for (from, to) in &dups {
                    if from == to {
                        let flags = libc_fcntl(*to, 1, 0);
                        if flags >= 0 {
                            libc_fcntl(*to, 2, flags & !1);
                        }
                    } else if libc_dup2(*from, *to) < 0 {
                        return Err(std::io::Error::last_os_error());
                    }
                }
                Ok(())
            });
        }
    }
    c
}

extern "C" {
    fn dup2(oldfd: i32, newfd: i32) -> i32;
    fn fcntl(fd: i32, cmd: i32, ...) -> i32;
}

fn libc_dup2(a: i32, b: i32) -> i32 {
    unsafe { dup2(a, b) }
}

fn libc_fcntl(fd: i32, cmd: i32, arg: i32) -> i32 {
    unsafe { fcntl(fd, cmd, arg) }
}

fn start_literal_writers(lits: Vec<(std::io::PipeWriter, Vec<u8>)>) -> Vec<std::thread::JoinHandle<()>> {
    lits.into_iter()
        .map(|(mut w, data)| {
            std::thread::spawn(move || {
                let _ = w.write_all(&data);
            })
        })
        .collect()
}

struct PipelineResult {
    errors: Vec<(CmdError, bool)>,
    abort: bool,
}

/// Run a pipeline. Output capture pipes are given optionally.
fn run_pipeline(
    pipeline: &RPipeline,
    capture: Option<(&std::io::PipeWriter, &std::io::PipeWriter)>,
) -> Result<PipelineResult, BlockFail> {
    let n = pipeline.commands.len();
    let mut children: Vec<(Child, &RCommand)> = Vec::new();
    let mut prev_stdout: Option<std::process::ChildStdout> = None;
    let mut writers = Vec::new();
    let mut result = PipelineResult { errors: Vec::new(), abort: false };
    for (i, cmd) in pipeline.commands.iter().enumerate() {
        let prepared = match prepare(cmd) {
            Ok(p) => p,
            Err(PrepError::Fail(f)) => {
                for (mut c, _) in children {
                    let _ = c.wait();
                }
                return Err(f);
            }
            Err(PrepError::Io(msg)) => {
                result.errors.push((CmdError::Io { message: msg, pos: pos_str(&cmd.pos) }, true));
                result.abort = true;
                break;
            }
        };
        let mut c = build_command(&prepared);
        if let Some(out) = prev_stdout.take() {
            c.stdin(Stdio::from(out));
        }
        if i + 1 < n {
            c.stdout(Stdio::piped());
        } else if let Some((out, _)) = capture {
            match out.try_clone() {
                Ok(w) => {
                    c.stdout(Stdio::from(w));
                }
                Err(_) => {}
            }
        }
        if let Some((_, err)) = capture {
            if let Ok(w) = err.try_clone() {
                c.stderr(Stdio::from(w));
            }
        }
        let lits = prepared.literal_inputs;
        match c.spawn() {
            Ok(mut child) => {
                drop(prepared.readers);
                drop(prepared.files);
                writers.extend(start_literal_writers(lits));
                if i + 1 < n {
                    prev_stdout = child.stdout.take();
                }
                children.push((child, cmd));
            }
            Err(e) => {
                drop(c);
                result.errors.push((CmdError::Io { message: e.to_string(), pos: pos_str(&cmd.pos) }, true));
                result.abort = true;
                break;
            }
        }
    }
    drop(prev_stdout);
    for (mut child, cmd) in children {
        match child.wait() {
            Ok(status) => {
                let code = exit_status_code(status);
                if code != 0 {
                    result.errors.push((CmdError::NonZero { pos: pos_str(&cmd.pos), status: code }, cmd.abort_on_error));
                    if cmd.abort_on_error {
                        result.abort = true;
                    }
                }
            }
            Err(e) => {
                result.errors.push((CmdError::Io { message: e.to_string(), pos: pos_str(&cmd.pos) }, true));
                result.abort = true;
            }
        }
    }
    for w in writers {
        let _ = w.join();
    }
    Ok(result)
}

fn run_builtin(cmd: &RCommand) -> Result<Option<CmdError>, BlockFail> {
    let builtin = cmd.builtin.unwrap();
    let mut args = Vec::new();
    for a in &cmd.args {
        args.extend(expand(a, &cmd.pos)?);
    }
    let fail = |what: &str, n: usize| BlockFail::Panic {
        message: format!("{} expansion resulted in {} items", what, n),
        pos: cmd.pos.clone(),
    };
    match builtin {
        Builtin::Alias => Err(BlockFail::RustPanic("src/runtime/command/exec/mod.rs:171:28")),
        Builtin::Cd => {
            if args.len() != 1 {
                return Err(fail("argument", args.len()));
            }
            match std::env::set_current_dir(std::ffi::OsStr::from_bytes(&args[0])) {
                Ok(()) => Ok(None),
                Err(e) => Ok(Some(CmdError::Io { message: e.to_string(), pos: pos_str(&cmd.pos) })),
            }
        }
        Builtin::Exec | Builtin::Exec0 | Builtin::Spawn0 => {
            if args.is_empty() {
                return Err(fail("argument", 0));
            }
            let program = args.remove(0);
            let arg0 = if builtin == Builtin::Exec {
                None
            } else {
                if args.is_empty() {
                    return Err(fail("arg0", 0));
                }
                Some(args.remove(0))
            };
            let p = Prepared {
                program,
                arg0,
                args,
                dups: Vec::new(),
                files: Vec::new(),
                literal_inputs: Vec::new(),
                readers: Vec::new(),
            };
            let mut c = build_command(&p);
            if builtin == Builtin::Spawn0 {
                match c.spawn() {
                    Ok(mut child) => match child.wait() {
                        Ok(status) => {
                            let code = exit_status_code(status);
                            if code != 0 {
                                Ok(Some(CmdError::NonZero { pos: pos_str(&cmd.pos), status: code }))
                            } else {
                                Ok(None)
                            }
                        }
                        Err(e) => Ok(Some(CmdError::Io { message: e.to_string(), pos: pos_str(&cmd.pos) })),
                    },
                    Err(e) => Ok(Some(CmdError::Io { message: e.to_string(), pos: pos_str(&cmd.pos) })),
                }
            } else {
                let e = c.exec();
                Ok(Some(CmdError::Io { message: e.to_string(), pos: pos_str(&cmd.pos) }))
            }
        }
    }
}

pub fn run_block(pipelines: &[RPipeline], capture: bool) -> Result<BlockOutcome, BlockFail> {
    let mut outcome = BlockOutcome { errors: Vec::new(), stdout: Vec::new(), stderr: Vec::new() };
    for pipeline in pipelines {
        if pipeline.commands.len() == 1 && pipeline.commands[0].builtin.is_some() {
            let cmd = &pipeline.commands[0];
            match run_builtin(cmd)? {
                None => {}
                Some(e) => {
                    let is_nonzero = matches!(e, CmdError::NonZero { .. });
                    outcome.errors.push(e);
                    if !is_nonzero || cmd.abort_on_error {
                        break;
                    }
                }
            }
            continue;
        }
        let result = if capture {
            let (mut out_r, out_w) = match std::io::pipe() {
                Ok(p) => p,
                Err(_) => break,
            };
            let (mut err_r, err_w) = match std::io::pipe() {
                Ok(p) => p,
                Err(_) => break,
            };
            let out_thread = std::thread::spawn(move || {
                let mut buf = Vec::new();
                let _ = out_r.read_to_end(&mut buf);
                buf
            });
            let err_thread = std::thread::spawn(move || {
                let mut buf = Vec::new();
                let _ = err_r.read_to_end(&mut buf);
                buf
            });
            let r = run_pipeline(pipeline, Some((&out_w, &err_w)));
            drop(out_w);
            drop(err_w);
            let o = out_thread.join().unwrap_or_default();
            let e = err_thread.join().unwrap_or_default();
            outcome.stdout.extend_from_slice(&o);
            outcome.stderr.extend_from_slice(&e);
            r?
        } else {
            run_pipeline(pipeline, None)?
        };
        let errs: Vec<CmdError> = result.errors.iter().map(|(e, _)| e.clone()).collect();
        match errs.len() {
            0 => {}
            1 => outcome.errors.push(errs[0].clone()),
            _ => outcome.errors.push(CmdError::Pipeline(errs)),
        }
        if result.abort {
            break;
        }
    }
    Ok(outcome)
}

#[allow(dead_code)]
fn unused_fd(f: std::fs::File) -> RawFd {
    let fd = f.into_raw_fd();
    let _ = unsafe { std::fs::File::from_raw_fd(fd) };
    fd
}
