pub fn rust_panic<T>(location: &str, message: &str) -> T {
    let _ = std::io::stdout().flush();
    let s = format!(
        "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        std::process::id(),
        location,
        message
    );
    let _ = std::io::stderr().write_all(s.as_bytes());
    std::process::exit(101);
}

fn eprint_line(s: &str) {
    let mut e = std::io::stderr();
    let _ = e.write_all(s.as_bytes());
    let _ = e.write_all(b"\n");
}

fn lex_pos(path: &str, pos: lexer::Pos) -> String {
    if pos.line == 0 {
        "***ill-formed*** (line 0, column 0)".to_string()
    } else {
        format!("{} (line {}, column {})", path, pos.line, pos.column)
    }
}

fn syntax_error_string(path: &str, e: &parser::SyntaxError) -> String {
    match e {
        parser::SyntaxError::Lex(le) => format!("Error: {} - {}", lex_pos(path, le.pos), le.kind),
        parser::SyntaxError::Unexpected { token, expected } => {
            format!("Error: {} - unexpected '{}', expected {}", lex_pos(path, token.pos), token.kind, expected)
        }
        parser::SyntaxError::UnexpectedEof => "Error: unexpected end of file".to_string(),
        parser::SyntaxError::EmptyCommandBlock(pos) => format!("Error: {} - empty command block", lex_pos(path, *pos)),
    }
}

pub struct Analysis {
    pub program: Option<program::Program>,
}

/// Lex, parse and analyze a source. Prints errors. Returns the program if no errors.
fn analyze(source: &[u8], path: &str, flags: &Flags) -> Analysis {
    let items = match lexer::lex(source) {
        Ok(items) => items,
        Err(p) => rust_panic(p.location, "not yet implemented"),
    };
    let mut parser = parser::Parser::new(items.clone());
    let ast = parser.parse();
    let syntax_errors = parser.errors.clone();
    for (i, e) in syntax_errors.iter().enumerate() {
        if i >= 20 {
            eprint_line("20 more supressed syntax errors");
            break;
        }
        eprint_line(&syntax_error_string(path, e));
    }
    if flags.lex {
        let mut out = String::new();
        out.push_str(SEPARATOR);
        out.push('\n');
        for item in &items {
            match item {
                lexer::LexItem::Token(t) => {
                    out.push_str(&format!("{} (line {}, column {}):\t{}\n", path, t.pos.line, t.pos.column, t.kind));
                }
                lexer::LexItem::Error(e) => {
                    out.push_str(&format!("Error: line {}, column {} - {}\n", e.pos.line, e.pos.column, e.kind));
                }
            }
        }
        out.push_str(SEPARATOR);
        out.push('\n');
        stdlib::stdout_write(out.as_bytes());
    }
    if flags.ast {
        let mut out = String::new();
        out.push_str(SEPARATOR);
        out.push('\n');
        out.push_str(&format!("AST for {}\n", path));
        out.push_str(&ast::AstFmt::block_top(&ast));
        out.push('\n');
        out.push_str(SEPARATOR);
        out.push('\n');
        stdlib::stdout_write(out.as_bytes());
    }
    let mut analyzer = semantic::Analyzer::new(Rc::from(path));
    let program = analyzer.analyze_root(&ast);
    for (i, e) in analyzer.errors.iter().enumerate() {
        if i >= 20 {
            eprint_line("20 more supressed semantic errors");
            break;
        }
        eprint_line(&format!("{}", e));
    }
    if !syntax_errors.is_empty() || !analyzer.errors.is_empty() {
        return Analysis { program: None };
    }
    Analysis { program: Some(program) }
}

thread_local! {
    static MAIN_DIR: std::cell::RefCell<std::path::PathBuf> = std::cell::RefCell::new(std::path::PathBuf::new());
    static MAIN_PATH: std::cell::RefCell<String> = std::cell::RefCell::new(String::new());
}

pub fn import_module(
    rt: &mut interp::Runtime,
    path: &[u8],
    pos: &program::SourcePos,
) -> interp::Exec<value::Value> {
    use std::path::{Path, PathBuf};
    let p = Path::new(std::ffi::OsStr::from_bytes(path));
    let base: PathBuf = if pos.path.as_ref() == MAIN_PATH.with(|m| m.borrow().clone()) {
        MAIN_DIR.with(|d| d.borrow().clone())
    } else {
        Path::new(pos.path.as_ref()).parent().map(|x| x.to_path_buf()).unwrap_or_default()
    };
    let full = if p.is_absolute() { p.to_path_buf() } else { base.join(p) };
    let canonical = match std::fs::canonicalize(&full) {
        Ok(c) => c,
        Err(e) => return interp::panic(pos, e.to_string()),
    };
    if let Some(v) = rt.modules.get(&canonical) {
        return Ok(v.clone());
    }
    let source = match std::fs::read(&canonical) {
        Ok(s) => s,
        Err(e) => return interp::panic(pos, e.to_string()),
    };
    let cpath = canonical.to_string_lossy().into_owned();
    let analysis = analyze(&source, &cpath, &Flags::default());
    let program = match analysis.program {
        Some(p) => p,
        None => return interp::panic(pos, format!("failed to import module ({})", cpath)),
    };
    match rt.run_root(&program) {
        Ok(v) => {
            rt.modules.insert(canonical, v.clone());
            Ok(v)
        }
        Err(p) => Err(interp::Control::Panic(p)),
    }
}

fn main() {
    let (flags, positional) = parse_cli();
    let mut script: Option<Vec<u8>> = None;
    let mut args = positional.clone();
    if let Some(first) = positional.first() {
        let p = std::path::Path::new(std::ffi::OsStr::from_bytes(first));
        if p.is_file() {
            script = Some(first.clone());
            args = positional[1..].to_vec();
        }
    }
    let (source, path, dir) = match &script {
        Some(s) => {
            let path_str = String::from_utf8_lossy(s).into_owned();
            let p = std::path::Path::new(std::ffi::OsStr::from_bytes(s));
            let dir = p.parent().map(|x| x.to_path_buf()).unwrap_or_default();
            match std::fs::read(p) {
                Ok(src) => (src, path_str, dir),
                Err(e) => {
                    eprint_line(&format!("Panic in {} (line 0, column 0): {}", path_str, e));
                    std::process::exit(127);
                }
            }
        }
        None => {
            let mut src = Vec::new();
            let _ = std::io::stdin().read_to_end(&mut src);
            (src, "<stdin>".to_string(), std::path::PathBuf::new())
        }
    };
    MAIN_DIR.with(|d| *d.borrow_mut() = dir);
    MAIN_PATH.with(|m| *m.borrow_mut() = path.clone());
    let analysis = analyze(&source, &path, &flags);
    let program = match analysis.program {
        Some(p) => p,
        None => {
            stdlib::stdout_flush();
            std::process::exit(2);
        }
    };
    if flags.program {
        let mut out = String::new();
        out.push_str(SEPARATOR);
        out.push('\n');
        out.push_str(&format!("Program for {}\n", path));
        out.push_str(&program::program_fmt(&program));
        out.push('\n');
        out.push_str(SEPARATOR);
        out.push('\n');
        stdlib::stdout_write(out.as_bytes());
    }
    if flags.check {
        stdlib::stdout_flush();
        std::process::exit(0);
    }
    let mut rt = interp::Runtime::new(args);
    match rt.run_root(&program) {
        Ok(_) => {
            stdlib::stdout_flush();
            std::process::exit(0);
        }
        Err(p) => {
            eprint_line(&format!("{}", p));
            stdlib::stdout_flush();
            std::process::exit(127);
        }
    }
}
