                Some(c) if c.is_ascii_alphanumeric() || c == b'_' => {
                    name.push(c);
                    self.bump();
                }
                Some(_) => break,
            }
        }
        if is_valid_identifier(&name) {
            Ok(DollarResult::Unit(ArgUnit::Dollar(name, dpos)))
        } else {
            self.error(LexErrorKind::InvalidIdentifier(name), dpos);
            self.bump();
            Ok(DollarResult::Error)
        }
    }
}

enum DollarResult {
    Unit(ArgUnit),
    Error,
    SilentEof,
    EofUnwind,
}

