/// Build the command, applying redirections on top of the base standard streams.
fn build_command(p: &mut Prepared, base: [Handle; 3]) -> std::process::Command {
    let mut c = std::process::Command::new(std::ffi::OsStr::from_bytes(&p.program));
    if let Some(a0) = &p.arg0 {
        c.arg0(std::ffi::OsStr::from_bytes(a0));
    }
    for a in &p.args {
        c.arg(std::ffi::OsStr::from_bytes(a));
    }
    for (k, v) in &p.env {
        c.env(std::ffi::OsStr::from_bytes(k), std::ffi::OsStr::from_bytes(v));
    }
    let mut targets = base;
    for op in p.ops.drain(..) {
        match op {
            RedirOp::Dup { set, from } => targets[set] = targets[from].clone(),
            RedirOp::Set { set, handle } => targets[set] = handle,
        }
    }
    c.stdin(targets[0].to_stdio(0));
    c.stdout(targets[1].to_stdio(1));
    c.stderr(targets[2].to_stdio(2));
    c
