#[derive(Clone)]
enum Handle {
    /// One of the parent's standard file descriptors.
    Parent(i32),
    Fd(Rc<std::os::fd::OwnedFd>),
}

impl Handle {
    fn to_stdio(&self, index: i32) -> Stdio {
        match self {
            Handle::Parent(n) if *n == index => Stdio::inherit(),
            Handle::Parent(n) => {
                let fd = unsafe { std::os::fd::BorrowedFd::borrow_raw(*n) };
                match fd.try_clone_to_owned() {
                    Ok(o) => Stdio::from(o),
                    Err(_) => Stdio::inherit(),
                }
            }
            Handle::Fd(o) => match o.try_clone() {
                Ok(o) => Stdio::from(o),
                Err(_) => Stdio::null(),
            },
        }
    }
}

enum RedirOp {
    /// Make fd `set` refer to what fd `from` refers to.
    Dup { set: usize, from: usize },
    /// Make fd `set` refer to the given handle.
    Set { set: usize, handle: Handle },
}

struct Prepared {
    env: Vec<(Vec<u8>, Vec<u8>)>,
    program: Vec<u8>,
    arg0: Option<Vec<u8>>,
    args: Vec<Vec<u8>>,
    ops: Vec<RedirOp>,
    literal_inputs: Vec<(std::io::PipeWriter, Vec<u8>)>,
}

enum PrepError {
    Fail(BlockFail),
    Io(String),
}

fn prepare(cmd: &RCommand) -> Result<Prepared, PrepError> {
    let program = expand_single(&cmd.program, &cmd.pos, "program").map_err(PrepError::Fail)?;
    let mut env = Vec::new();
    for (name, value) in &cmd.env {
        env.push((name.clone(), expand_single(value, &cmd.pos, "env variable").map_err(PrepError::Fail)?));
    }
    let mut args = Vec::new();
    for a in &cmd.args {
        args.extend(expand(a, &cmd.pos).map_err(PrepError::Fail)?);
    }
    let mut p = Prepared { env, program, arg0: None, args, ops: Vec::new(), literal_inputs: Vec::new() };
    for r in &cmd.redirections {
        match r {
            RRedir::Output { source, target } => {
                if *source != 1 && *source != 2 {
                    return Err(PrepError::Fail(BlockFail::Panic {
                        message: format!("unsupported file descriptor ({})", source),
                        pos: cmd.pos.clone(),
                    }));
                }
                match target {
                    RTarget::Fd(fd) => {
                        if *fd != 1 && *fd != 2 {
                            return Err(PrepError::Fail(BlockFail::Panic {
                                message: format!("unsupported file descriptor ({})", fd),
                                pos: cmd.pos.clone(),
                            }));
                        }
                        p.ops.push(RedirOp::Dup { set: *source as usize, from: *fd as usize });
                    }
                    RTarget::Overwrite(f) | RTarget::Append(f) => {
                        let path = expand_single(f, &cmd.pos, "redirection").map_err(PrepError::Fail)?;
                        let append = matches!(target, RTarget::Append(_));
                        let file = std::fs::OpenOptions::new()
                            .write(true)
                            .create(true)
                            .append(append)
                            .truncate(!append)
                            .open(std::ffi::OsStr::from_bytes(&path))
                            .map_err(|e| PrepError::Io(e.to_string()))?;
                        let fd: std::os::fd::OwnedFd = file.into();
                        p.ops.push(RedirOp::Set { set: *source as usize, handle: Handle::Fd(Rc::new(fd)) });
                    }
                }
            }
            RRedir::Input { literal, source } => {
                let data = expand_single(source, &cmd.pos, "redirection").map_err(PrepError::Fail)?;
                if *literal {
                    let (reader, writer) = std::io::pipe().map_err(|e| PrepError::Io(e.to_string()))?;
                    let mut data = data;
                    data.push(b'\\n');
                    let fd: std::os::fd::OwnedFd = reader.into();
                    p.ops.push(RedirOp::Set { set: 0, handle: Handle::Fd(Rc::new(fd)) });
                    p.literal_inputs.push((writer, data));
                } else {
                    let file = std::fs::File::open(std::ffi::OsStr::from_bytes(&data))
                        .map_err(|e| PrepError::Io(e.to_string()))?;
                    let fd: std::os::fd::OwnedFd = file.into();
                    p.ops.push(RedirOp::Set { set: 0, handle: Handle::Fd(Rc::new(fd)) });
                }
            }
        }
    }
    Ok(p)
}

/// Build the command, applying redirections on top of the base standard streams.
fn build_command(p: &mut Prepared, base: [Handle; 3]) -> std::process::Command {
    let mut c = std::process::Command::new(std::ffi::OsStr::from_bytes(&p.program));
    if let Some(a0) = &p.arg0 {
        c.arg0(std::ffi::OsStr::from_bytes(a0));
    }
    for a in &p.args {
        c.arg(std::ffi::OsStr::from_bytes(a));
    }
    for (k, v) in &p.env {
        c.env(std::ffi::OsStr::from_bytes(k), std::ffi::OsStr::from_bytes(v));
    }
    let mut targets = base;
    for op in p.ops.drain(..) {
        match op {
            RedirOp::Dup { set, from } => targets[set] = targets[from].clone(),
            RedirOp::Set { set, handle } => targets[set] = handle,
        }
    }
    c.stdin(targets[0].to_stdio(0));
    c.stdout(targets[1].to_stdio(1));
    c.stderr(targets[2].to_stdio(2));
    c
}

